\section{Categories of complete BAOs with stable morphisms}\label{sec: cBA}

In this section we show that the negative results of the previous section extend to the categories of complete BAOs with stable morphisms. In other words, the situation remains the same if instead of complete stable morphisms we consider all stable morphisms. 
This we do by showing that products don't exist in the corresponding dual categories of extremally disconnected compact Hausdorff spaces. 


\begin{theorem} \label{thm: general}
    Let $\C$ be a complete category.
    Suppose $\pazocal{H}$ is a class of objects of $\C$ such that every morphism $f \colon X \to Y$ in $\C$ is an isomorphism if and only if for each $Z \in \pazocal{H}$, $f \circ - \colon \hom_\C(Z, X) \to \hom_\C(Z, Y)$ is a bijection.
    Then the inclusion $\mathbf{E} \hookrightarrow \C$ of any full subcategory $\mathbf{E}$ containing all objects of $\pazocal{H}$ preserves limits.
\end{theorem}

\begin{proof}
    Let $D \colon \mathbf{I} \to \mathbf{E}$ be a diagram and $(m_i \colon M \to D(i))_{i \in \mathbf{I}}$ a limit cone in $\mathbf{E}$.
    Suppose $(n_i \colon N \to D(i))_{i \in \mathbf{I}}$ is the limit in $\mathbf{C}$, which exists because $\C$ is complete.
    Then there is a unique morphism $f \colon M \to N$ such that for every $i \in I$ we have $m_i = n_i \circ f$.
    It is enough to prove that $f$ is an isomorphism.

    Fix $Z \in \pazocal{H}$.
    The functors $\hom_\E(Z, -) \colon \E \to \Set$ and $\hom_\C(Z, -) \colon \C \to \Set$ preserve limits because every representable functor does \cite[Cor.~13.9]{AHS06}.\footnote{We recall that a representable functor is a functor that up to natural isomorphism is of the form $\hom(A,-)$ for some object $A$.}
    Therefore,
    \[
    (m_i \circ - \colon \hom_\E(Z,M) \to \hom_\E(Z,D(i)))_{i \in \mathbf{I}}
    \]
    is a limit cone in $\Set$ 
    over the diagram $\hom_\E(Z,-) \circ D \colon \mathbf{I} \to \Set$
    and 
    \[
    (n_i \circ - \colon \hom_\C(Z,N) \to \hom_\C(Z,D(i)))_{i \in \mathbf{I}}
    \]
    is a limit cone in $\Set$ over the diagram 
    $\hom_\C(Z,-) \circ D  \colon \mathbf{I} \to \Set$.
    Since $\E$ is a full subcategory of $\C$, for every $Z  \in \pazocal{H}$ we have that $\hom_\E(Z,M) = \hom_\C(Z,M)$ and $\hom_\E(Z,D(i)) = \hom_\C(Z,D(i))$ for each $i \in \mathbf{I}$.

    Moreover, we have a function $f \circ -\colon \hom_\C(Z,M) \to \hom_\C(Z, N)$ that maps ${h \colon Z \to M}$ to $f \circ h \colon Z \to N$. We claim that $f \circ -$ is a bijection.
    Since $m_i = n_i \circ f$ for every $i$, the function 
    \[
    m_i \circ - \colon \hom_\C(Z,M) \to \hom_\C(Z,D(i))
    \]
    is the composite 
    \[
    \begin{tikzcd}[column sep=10ex]
    \hom_\C(Z,M) \arrow[r, "f \circ -"] & \hom_\C(Z, N) \arrow[r, "n_i \circ -"] & \hom_\C(Z,D(i)).
    \end{tikzcd}
    \]
    Therefore, $f \circ -$ is the unique factorization of the limit cone
    \[
    (m_i \circ - \colon \hom_\C(Z,M) \to \hom_\C(Z,D(i)))_{i \in \mathbf{I}}
    \]
    through the limit cone
    \[
    (n_i \circ - \colon \hom_\C(Z,N) \to \hom_\C(Z,D(i)))_{i \in \mathbf{I}}.
    \]
    Because both cones are limit cones over the same diagram, $f \circ -$ must be an isomorphism in $\Set$, hence a bijection.
    Thus, it is enough to use the assumption to conclude that $f$ is an isomorphism in $\C$.
\end{proof}


 We recall that a \emph{conservative} functor is a functor $\mathcal F \colon \mathbf{A} \to \mathbf{B}$ that reflects isomorphisms, i.e.~such that, for every morphism $f$ in $\mathbf{A}$, if $\mathcal F(f)$ is an isomorphism in $\mathbf{B}$ then $f$ is an isomorphism in $\mathbf{A}$ (see, e.g., \cite[Sec.\ 5.6]{Riehl2016}).

\begin{corollary} \label{cor: general-conservative}
    Let $\C$ be a category with a conservative functor to $\Set$ that is represented by an object $X \in \C$.
    The inclusion $\mathbf{E} \hookrightarrow \C$ of any full subcategory $\mathbf{E}$ containing $X$ preserves limits.
\end{corollary}

\begin{proof}
    This is the specialization of \cref{thm: general} to the case of $\pazocal{H}=\{X\}$. 
\end{proof}

Let $\KHaus$ denote the category of compact Hausdorff spaces and continuous maps. 

\begin{theorem} \label{t:limits-as-in-KH}
    Let $\bf E$ be a full subcategory of $\KHaus$ containing a singleton. The inclusion $\mathbf{E} \hookrightarrow \KHaus$ preserves limits.
\end{theorem}

\begin{proof}
    We show that $\mathbf{E}$ and $\KHaus$ satisfy the condition 
    of \cref{cor: general-conservative} by taking $\mathbf{C} = \KHaus$. Since a continuous map between compact Hausdorff spaces is a homeomorphism if and only if it is a bijection, the forgetful functor $\mathcal U \colon\KHaus \to \Set$ is conservative. Let $\{x\} \in \mathbf{E}$ be a singleton 
    space. There is a natural isomorphism between $\hom_\KHaus(\{x\},-)$ and $\mathcal U$ whose component relative to $Y \in \KHaus$ sends $f \colon \{x\} \to Y$ to $f(x)$. Thus, $\mathcal U \colon \KHaus \to \Set$ is a conservative functor represented by $\{x\}$. Since $\mathbf{E}$ contains $\{x\}$, the result follows from
    \cref{cor: general-conservative}.
\end{proof}

We recall that an \emph{ED-space} is an extremally disconnected compact Hausdorff space. It is straightforward to see that each ED-space is a Stone space (that is, a zero-dimensional compact Hausdorff space). Let $\ED$ denote the full subcategory of $\KHaus$ consisting of ED-spaces.

\begin{theorem}\label{thm: ED lacks products}
    The category $\ED$ lacks some binary powers.
\end{theorem}

\begin{proof}
    This is an immediate consequence of \cref{t:limits-as-in-KH} and the well-known fact in topology that there are ED-spaces whose product is not extremally disconnected (for example, $\beta\N\times\beta\N$ is not ED; see \cite[p.~97]{GJ60}). 
\end{proof}

Let $\cBA$ denote the category of complete boolean algebras with boolean morphisms. Dualizing \cref{thm: ED lacks products}, we get: 

\begin{corollary} \label{c:lacking-binary-coproducts}
    $\cBA$ lacks some binary copowers, and hence is not equivalent to a prevariety.
\end{corollary}

\begin{proof}
    Since a boolean algebra is complete if and only if its Stone space is ED \cite[Thm.~39]{GH09}, restricting Stone duality to complete boolean algebras yields that $\cBA$ is dually equivalent to $\ED$. 
    Therefore, since
    $\ED$ lacks some binary powers, $\cBA$ lacks some binary copowers. Thus, $\cBA$ is not cocomplete, and hence is not equivalent to a prevariety. 
\end{proof} 

As an immediate consequence of \cref{c:lacking-binary-coproducts}, we obtain:

\begin{corollary} \label{l:no-bin-prod-if-surjects}
    Let $\C$ be a category and $\mathcal U \colon \C \to \cBA$ a colimit-preserving essentially surjective functor.
    The category $\C$ lacks some binary copowers.
\end{corollary}

Let $\cBAO$ denote the category whose objects are complete BAOs and whose morphisms are stable maps, and define $\cT$, $\cKfour$, $\cB$, $\cTB$, $\MTst$, and $\cMA$ similarly.

\begin{corollary}
    Each of the categories $\cBAO$, $\cT$, $\cKfour$, $\cB$, $\cTB$, $\MTst$, and $\cMA$ lacks some binary copowers. Consequently, neither is equivalent to a prevariety.
\end{corollary}

\begin{proof}
Let $\C$ denote $\cBAO$, $\cT$, $\cKfour$, $\cB$, $\cTB$, $\MTst$, or $\cMA$. 
The same proof as in \cref{t:adjoints}
shows that the forgetful functor $\mathcal U\colon\C\to\cBA$ has both left and right adjoints. The latter gives that $\mathcal U$ is colimit-preserving and it is clearly essentially surjective. Thus, \cref{l:no-bin-prod-if-surjects} applies yielding that $\C$ lacks some binary copowers.
\end{proof}

