\section{Categories of BAOs with stable morphisms}\label{sec: 3.2}

In this section we show that various categories of compact Hausdorff spaces and Stone spaces with continuous relations lack equalizers. This together with J\'onsson-Tarski duality for BAOs with stable morphisms yields 
that various categories of BAOs with stable morphisms lack coequalizers, and hence are not equivalent to a prevariety. 

Let $X$ and $X'$ be compact Hausdorff spaces, $R$ a closed relation on $X$ (i.e., a closed subset of $X \times X$), and $R'$ a closed relation on $X'$. Following \cite[Def.~3.2]{BBI16}, we call a continuous map $f\colon X\to X'$ {\em stable} provided 
\[
x \mathrel{R} y \Longrightarrow f(x) \mathrel{R'} f(y) \quad \forall x,y\in X.
\]

\begin{definition}
    Let $\KHausR$ denote the category whose objects are pairs $(X,R)$ where $X$ is a compact Hausdorff space and $R$ is a closed relation on $X$, and whose morphisms are stable maps.
\end{definition}

We will also be interested in full subcategories of $\KHausR$ whose objects $(X,R)$ satisfy extra conditions on the relation $R$:

\begin{definition}\ \label{def: Sub Cat of KHausR}
\begin{enumerate}
\item Let $\KHausT$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is reflexive.
\item Let $\KHausKfour$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is transitive.
\item Let $\KHausB$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is symmetric. 
\item Let $\KHausTB$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is reflexive and symmetric. 
\item Let $\KHausSfour$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is reflexive and transitive. 
\item Let $\KHausSfive$ denote the full subcategory of $\KHausR$ whose objects $(X,R)$ satisfy the extra condition that $R$ is an equivalence relation.
\end{enumerate}
\end{definition} 

It is clear that isomorphisms in $\KHausR$ are continuous bijections that preserve and reflect the binary relations, and the same is true for the categories in \cref{def: Sub Cat of KHausR}. 
The next proposition is straightforward.

\begin{proposition}\label{Prop: KHausR complete}
    The category $\KHausR$ and its full subcategories in \cref{def: Sub Cat of KHausR} 
    are complete.
\end{proposition}

\begin{proof}
    The product of $\{(X_i,R_i) : i \in I\}$ in $\KHausR$ is $(\prod X_i, \prod R_i)$, where $\prod X_i$ is the product of $\{X_i : i \in I\}$ in $\KHaus$ and $\prod R_i$ is the product relation given by 
    \[
    f \left(\mathrel{\prod R_i}\right) g \iff f(i) \mathrel{R_i} g(i) \ \ \forall i \in I.
    \]
    The equalizer of $f, g \colon (X,R) \to (X',R')$ 
    in $\KHausR$ 
    is their equalizer 
    \[
    \{ x \in X : f(x) = g(x)\}
    \]
    in $\KHaus$ equipped with the restriction of $R$. Consequently, $\KHausR$ is complete, and a similar argument yields that so are all its full subcategories in \cref{def: Sub Cat of KHausR}.
\end{proof} 

We follow the convention in modal logic (see \cite[p.~66]{CZ97}) and denote reflexive points by 
$\tikz[baseline=-0.5ex]{
\node[circle,draw,inner sep=2pt,fill=white] (a) at (0,0) {};
}$
and irreflexive points by
$\tikz[baseline=-0.5ex]{
\node[circle,draw,inner sep=2pt,fill=black] (a) at (0,0) {};
}$.
Let $\oneirr$ denote the irreflexive singleton $\tikz[baseline=-0.5ex]{
\node[circle,draw,inner sep=2pt,fill=black] (a) at (0,0) {};
}$. Let also $\twoirr$ denote the irreflexive 2-element chain
$\tikz[baseline=-0.5ex]{
  \node[circle,draw,inner sep=2pt,fill=black] (a) at (0,0) {};
  \node[circle,draw,inner sep=2pt,fill=black] (b) at (0.7,0) {};
  \draw[->, shorten <=0.5pt, shorten >=0.5pt] (a) -- (b);
}
$ and $\tworef$ the reflexive 2-element chain 
$\tikz[baseline=-0.5ex]{
  \node[circle,draw,inner sep=2pt,fill=white] (a) at (0,0) {};
  \node[circle,draw,inner sep=2pt,fill=white] (b) at (0.7,0) {};
  \draw[->, shorten <=0.5pt, shorten >=0.5pt] (a) -- (b);
}
$. We denote the bottom of these two chains by $0$ and the top by $1$.
Finally, let 
$\twoirrsym$ denote the irreflexive doubleton
$\tikz[baseline=-0.5ex]{
  \node[circle,draw,inner sep=2pt,fill=black] (a) at (0,0) {};
  \node[circle,draw,inner sep=2pt,fill=black] (b) at (0.7,0) {};
  \draw[<->, shorten <=0.5pt, shorten >=0.5pt] (a) -- (b);
}$ and 
$\tworefsym$ the reflexive doubleton
$\tikz[baseline=-0.5ex]{
  \node[circle,draw,inner sep=2pt,fill=white] (a) at (0,0) {};
  \node[circle,draw,inner sep=2pt,fill=white] (b) at (0.7,0) {};
  \draw[<->, shorten <=0.5pt, shorten >=0.5pt] (a) -- (b);
}$. In each of these cases, the two points (which we also denote by $0$ and $1$) are both related to each other.
We view $\oneirr$, $\twoirr$, $\tworef$, $\twoirrsym$, and $\tworefsym$  as objects of $\KHausR$ by equipping them with the discrete topology.
The next theorem is an analogue of \cref{t:limits-as-in-KH}. 

\begin{theorem}\plabel{thm: preservation limits}
\hfill
\begin{enumerate}
    \item\label[thm: preservation limits]{thm: preservation limits: irreflexive} If $\E$ is a full subcategory of $\KHausR$ containing $\oneirr$ and $\twoirr$, 
    then the inclusion functor $\E \hookrightarrow \KHausR$ preserves limits. 
    \item\label[thm: preservation limits]{thm: preservation limits: reflexive} If $\E$ is a full subcategory of $\KHausT$ containing 
    $\tworef$,
    then the inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
    \item\label[thm: preservation limits]{thm: preservation limits: irreflexive symmetric} If $\E$ is a full subcategory of $\KHausB$ containing $\oneirr$ and $\twoirrsym$, 
    then the inclusion functor $\E \hookrightarrow \KHausR$ preserves limits. 
    \item\label[thm: preservation limits]{thm: preservation limits: reflexive symmetric} If $\E$ is a full subcategory of $\KHausTB$ containing 
    $\tworefsym$,
    then the inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
\end{enumerate}
\end{theorem}

\begin{proof}
    \eqref{thm: preservation limits: irreflexive}.
    Let $\C = \KHausR$ and $\pazocal{H} = \{ \oneirr,\twoirr \}$. 
    We prove that the condition
    of \cref{thm: general} is satisfied by showing that, for any morphism $f \colon (X,R) \to (X',R')$ in $\KHausR$, if the functions
    \[
    f \circ - \colon \hom_{\KHausR}(\oneirr,X)  \to \hom_{\KHausR}(\oneirr,X')
    \]
    and
    \[
    f \circ - \colon \hom_{\KHausR}(\twoirr,X)  \to \hom_{\KHausR}(\twoirr,X')
    \]
    are bijections, then $f$ is an isomorphism.
    To prove that $f$ is an isomorphism in $\KHausR$ it is sufficient to show that it is a bijection that reflects the relation. We first show that $f$ is a bijection. Let $y \in X'$, and consider the map $c_y \colon  \oneirr \to X'$ with constant value $y$, which is a morphism in $\KHausR$. Since $f \circ -$ is onto, there is a morphism $g \colon \oneirr \to X$ in $\KHausR$ such that $f \circ g = c_y$. Therefore, $y$ is in the image of $f$, and so $f$ is onto. Suppose that $x_1,x_2 \in X$ are such that $f(x_1)=f(x_2)$ and consider the maps $c_{x_1}, c_{x_2} \colon  \oneirr \to X$ with constant values $x_1,x_2$. Then $f \circ c_{x_1} = f \circ c_{x_2}$ because $f(x_1)=f(x_2)$. Since $f \circ -$ is one-to-one, $c_{x_1}=c_{x_2}$, and so $x_1=x_2$. Thus, $f$ is one-to-one, and hence $f$ is a bijection.

    We now show that $f$ reflects the relation. Let $x_1,x_2 \in X$ be such that $f(x_1) \mathrel{R'} f(x_2)$. Define $h \colon \twoirr \to X'$ by $h(0) = f(x_1)$ and $h(1) = f(x_2)$. Because $\twoirr$ is discrete, $h$ is continuous. Since ${f(x_1) \mathrel{R'} f(x_2)}$, we have that $h$ is a morphism in $\KHausR$. Because $f \circ -$ is onto, there is a morphism $g \colon \twoirr \to X$ such that $f \circ g = h$. Therefore,  $fg(0)=h(0)=f(x_1)$ and $fg(1)=h(1)=f(x_2)$. Since $f$ is one-to-one, we conclude that $g(0)=x_1$ and $g(1)=x_2$. Thus, $x_1 \mathrel{R} x_2$ because $0 < 1$ and $g$ is a morphism in $\KHausR$. 

    \eqref{thm: preservation limits: reflexive}.
    By the proof of \cref{Prop: KHausR complete}, the inclusion $\KHausT \hookrightarrow \KHausR$ preserves limits. Therefore, it is enough to prove that
    the inclusion $\E \hookrightarrow \KHausT$ preserves limits.
    This can be done by verifying the condition
    of \cref{cor: general-conservative} by showing that 
    \[
    \hom_{\KHausT}(\tworef,-) \colon \KHausT \to \Set
    \]
    is conservative. Let $f \colon (X,R) \to (X',R')$ be a morphism in $\KHausT$ whose image  
    \[
    f \circ - \colon \hom_{\KHausT}(\tworef,X) \to \hom_{\KHausT}(\tworef, X')
    \]
    is a bijection. As above, to prove that $f$ is an isomorphism in $\KHausT$ it is sufficient to show that it is a bijection that reflects the relation. This is proved similarly to \eqref{thm: preservation limits: irreflexive}: to see that $f$ is a bijection replace $\oneirr$ with $\tworef$ and use that the relation is reflexive, and to see that $f$ 
    reflects the relation replace $\twoirr$ with $\tworef$.

    \eqref{thm: preservation limits: irreflexive symmetric}.
    By the proof of \cref{Prop: KHausR complete}, the inclusion $\KHausB \hookrightarrow \KHausR$ preserves limits. Therefore, it is enough to prove that
    the inclusion $\E \hookrightarrow \KHausB$ preserves limits, which can be done by replacing $\twoirr$ with $\twoirrsym$ in the proof of \eqref{thm: preservation limits: irreflexive}.

    \eqref{thm: preservation limits: reflexive symmetric}.
    By the proof of \cref{Prop: KHausR complete}, the inclusion $\KHausTB \hookrightarrow \KHausR$ preserves limits. Thus, it is enough to prove that
    the inclusion $\E \hookrightarrow \KHausTB$ preserves limits, which can be done by replacing $\tworef$ by $\tworefsym$ in the proof of \eqref{thm: preservation limits: reflexive}.
\end{proof}

\begin{remark}
    Comparing the statements of \cref{thm: preservation limits}, in the reflexive cases we don't need $\E$ to contain the reflexive singleton because every constant map from $\tworef$ to an object of $\KHausT$ is a morphism of $\KHausT$.
    The analogous statement for $\KHausR$ is false: given $X' \in \KHausR$ and an irreflexive element $y \in X'$, the constant map $c_y \colon \twoirr \to X'$ with constant value $y$ does not preserve the relation, and hence is not a morphism of $\KHausR$.
\end{remark}

We recall that a closed relation $R$ on a compact Hausdorff space $X$ is {\em continuous} provided 
\[
R^{-1}[U] \coloneqq \{ x \in X : x \mathrel{R} u \mbox{ for some } u \in U\}
\]
is open for each open $U \subseteq X$. 


\begin{definition}\ \label{def: Cat with cont R}
    \begin{enumerate}
        \item Let $\KHausC$ denote the full subcategory of $\KHausR$ whose objects are those $(X,R)$ where $R$ is continuous and define $\KHausCT$, $\KHausCKfour$, $\KHausCB$, $\KHausCTB$,  $\KHausCSfour$, and $\KHausCSfive$
        similarly.
        \item Let also $\StoneC$ denote the full subcategory of $\KHausC$ consisting of Stone spaces, and define $\StoneCT$, $\StoneCKfour$, $\StoneCB$, $\StoneCTB$, $\StoneCSfour$, and $\StoneCSfive$ 
        similarly.
    \end{enumerate}
\end{definition}


Applying \cref{thm: preservation limits} yields:

\begin{corollary}\label{cor: inclusion C preserves limits}
\hfill\begin{enumerate}
\item Let $\E$ be $\StoneC$, $\KHausC$, $\StoneCKfour$, or $\KHausCKfour$. The inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
\item Let $\E$ be $\StoneCT$, $\KHausCT$, $\StoneCSfour$, or $\KHausCSfour$. The inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
\item Let $\E$ be $\StoneCB$ or $\KHausCB$. The inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
\item Let $\E$ be $\StoneCTB$, $\KHausCTB$, $\StoneCSfive$, or $\KHausCSfive$. The inclusion functor $\E \hookrightarrow \KHausR$ preserves limits.
\end{enumerate}
\end{corollary}

We are ready to prove that the categories in \cref{def: Cat with cont R} are not complete.

\begin{theorem}\ \label{thm: continuous}
\begin{enumerate}
    \item\label[thm: continuous]{thm: continuous KHaus} $\KHausC$, $\KHausCT$, $\KHausCKfour$, $\KHausCB$, $\KHausCTB$,  $\KHausCSfour$, and $\KHausCSfive$ lack some equalizers.
    \item\label[thm: continuous]{thm: continuous Stone} $\StoneC$, $\StoneCT$, $\StoneCKfour$, $\StoneCB$, $\StoneCTB$, $\StoneCSfour$, and $\StoneCSfive$ lack some equalizers.
\end{enumerate}
\end{theorem}

\begin{proof}
The proofs of \eqref{thm: continuous KHaus} and \eqref{thm: continuous Stone} are the same, and we concentrate on the latter. Let $\E$ be one of $\StoneC$, $\StoneCT$, $\StoneCKfour$, $\StoneCB$, $\StoneCTB$, $\StoneCSfour$, and $\StoneCSfive$. Consider the space $X$ shown in \cref{fig1}, where $x_\infty$ is the limit of the sequence $(x_n)$ of isolated points and $y_\infty$ is the limit of the sequence $(y_n)$ of isolated points. Therefore, $X$ is a Stone space.  
The relation $R$ is defined on $X$ as shown in \cref{fig1}. It is not difficult to see that $R$ is a continuous  relation.
Thus, $(X,R)$ is an object of $\StoneCSfive$, and hence of $\E$. 

