        \item $\Kfour$ is dually equivalent to $\StoneCKfour$.
        \item $\B$ is dually equivalent to $\StoneCB$.
        \item $\TB$ is dually equivalent to $\StoneCTB$.
        \item $\CA$ is dually equivalent to $\StoneCSfour$.
        \item $\MA$ is dually equivalent to $\StoneCSfive$.
    \end{enumerate}
\end{theorem}

Putting \cref{thm: continuous} together with \cref{thm: JT for BAOs} immediately gives:

\begin{corollary}
    Each of $\BAOst$, $\T$, $\Kfour$, $\B$, $\TB$, $\CA$, and $\MA$ lacks some coequalizers. 
    Consequently, neither is equivalent to a prevariety.
\end{corollary}


