\begin{itemize}
    \item \textbf{QNN~\cite{mitarai2018quantum}:} A traditional quantum neural network that projects classical input $x \in \mathbb{R}^{d}$ into a low-dimensional quantum state using angle embedding. Given a trainable projection $x' = W x \in \mathbb{R}^{n}$ with $n$ equal to the number of qubits, we apply an embedding via single-qubit rotations:
    \begin{align*}
        \text{Embed:} \quad &|0\rangle^{\otimes n} \xrightarrow{\text{RX}(x'_i), \text{RZ}(x'_i)} |\psi_{\text{in}}(x)\rangle \\
        \text{VQC:} \quad &|\psi_{\text{in}}(x)\rangle \xrightarrow{\text{U}(\theta)} |\psi_{\text{out}}(x, \theta)\rangle
    \end{align*}
    The circuit $\text{U}(\theta)$ consists of entangling layers (e.g., CNOT gates) and parameterized rotations. The measurement is performed as:
    \[
        z_i = \langle \psi_{\text{out}} | Z_i | \psi_{\text{out}} \rangle, \quad \text{for } i = 1, \dots, n
    \]
    The output vector $z$ is treated as a latent feature for downstream prediction.

    \item \textbf{QRWKV~\cite{chen2025qrwkv}:} A quantum RWKV model that replaces part of the feedforward channel mixing layer with a variational quantum circuit. For input $x \in \mathbb{R}^{d}$, the classical projection $x' = W x$ is mapped to quantum observables using:
    \[
        z = \text{QuantumCircuit}(x') \in \mathbb{R}^{n}
    \]
    The RWKV recurrence is preserved, and quantum layers enhance expressiveness in the time-mixing component:
    \[
        h_t = \text{Mix}(h_{t-1}, x_t; \theta_{\text{RWKV}}) + \text{QVC}(x_t; \theta_q)
    \]

    \item \textbf{QASA \cite{chen2025quantum}:} A quantum attention variant of the Transformer, where the classical dot-product attention:
    \[
        \text{Attention}(Q, K, V) = \text{softmax}\left( \frac{Q K^\top}{\sqrt{d}} \right)V
    \]
    is replaced by quantum attention computed via a variational quantum circuit. Let $q_i, k_j \in \mathbb{R}^{d}$ be token queries and keys, the attention score is computed as:
    \[
        \alpha_{ij} = \text{QuantumAttention}(q_i, k_j; \theta_q) \in [0, 1]
    \]
    where the circuit encodes $(q_i, k_j)$ into quantum states and returns expectation values approximating a similarity measure. The value aggregation is:
    \[
        \text{QASA}(q_i, K, V) = \sum_j \alpha_{ij} v_j
    \]
    making the attention learnable in quantum Hilbert space, enhancing expressiveness with non-linear correlations between tokens.
\end{itemize}

