Formula \eqref{EQ:resilience_put_t} may also be obtained by differentiating in time the mean put value, which, in addition, proves its validity for any $t\in(0,T)$. 
First, for fixed $t\in(0,T)$, we explicitly compute the expectation of the quantity $V_t(X_2)$ with respect to the distribution of $S_t$, see equation~\eqref{EQ:put}, yielding:
\begin{align}
\label{EQ:integrand}
    \E[V_t(X_2)]
    =&\,\int_0^{+\infty}\left[K\mathcal N\big(-d_-(t,x)\big)-x\,\mathcal N\big(-d_+(t,x)\big)\right]p_{\ss{S_t}}(x)\d x,
\end{align}
where, for $x>0$,
\begin{equation}
    p_{\ss{S_t}}(x)
    :=\frac{1}{x\s\sqrt{2\pi t}}\exp{\left(-\frac{1}{2\s^2 t }\left[\ln\frac{x}{S_0}-\Big(\mu-\frac{\s^2}{2}\Big)t\right]^2\right)},
\end{equation}
is the probability density function of $S_t$.
If we denote the integrand in equation~\eqref{EQ:integrand} as $\Phi(t,x)$, then it is easy to verify that $\Phi\in C^{1,0}\big((0,T)\times(0+\infty)\big)$.
Therefore, for any ${\eps\in(0,T/2)}$, an integrable function $\theta_\eps:(0,+\infty)\to[0,T]$ exists such that ${|\partial_t\Phi(t,x)|\leq \theta_\eps(x)}$ for any $x>0$ and any $t\in[\eps,T-\eps]$.
This allows us to differentiate under the integral sign, see \cite[Theorem~2.27]{F99}, and infer that $[\eps,T-\eps]\ni t\mapsto \E[V_t(X_2)]$ is differentiable and that, for $t\in[\eps,T-\eps]$:
\[
    \bm\dot V_t(X_2)
    =\frac{\d}{\d t}\E[V_t(X_2)]
    =\int_0^{+\infty}\partial_t\Phi(t,x)\d x 
    =-\mu\,\E\big[S_t\mathcal N\big(-d_+(t,S_t)\big)\big].
\]
By the arbitrariness of $\eps\in(0,T/2)$, we conclude that $(0,T)\ni t\mapsto \E[V_t(X_2)]$ is everywhere differentiable and that the above formula holds for any $t\in(0,T)$.
\end{example}

\begin{example}[Zero-coupon bond price]
Let us consider a stochastic interest rate driven by the following SDE:
\begin{equation}
    r_t=r_0+\int_0^t a(b-r_s)\d s+\s W_t,
\end{equation}
i.e., a standard Vasicek model with speed of reversion $a> 0$, long-term mean level $b\geq 0$, instantaneous  volatility $\s\geq 0$, and starting value $r_0>-1$, see \cite[Section~31.2]{H21}.

The closed-form solution is given by:
\begin{equation}
\label{EQ:vasicek}
    r_t=r_0e^{-at}+b(1-e^{-at})+\sigma e^{-at}\int_0^te^{as}\d W_s, \qquad \forall\, t\geq 0.
\end{equation}
In particular, $r_t$ is normally distributed at each $t\in[0,T]$, with parameters:
\begin{align}
&\mu_t:=\mathbb{E}[r_t]= r_0e^{-at}+b(1-e^{-at}),\\
&\Sigma^2_t:=\mathbb{E}\big[(r_t-\mu_t)^2\big]=\frac{\sigma^2}{2a}(1-e^{-2at}).
\end{align}

If there is a zero-coupon bond available in the market, with maturity $T>0$, then its price under no-arbitrage assumptions is given by the following formula:
\begin{equation}
\label{EQ:vasicek_bond_price}
    P_t
    =\E\left[\left.\exp\bigg(-\int_t^Tr_s\d s\bigg)\right|\mathcal{F}_t\right]
    =\exp\big(A_t-B_tr_t\big), \qquad \forall\, t\in[0,T],
\end{equation}
where:
\begin{align}
    B_t&:=\frac{1-e^{-a(T-t)}}{a},\\
    A_t&:=\left(b-\frac{\sigma^2}{2a^2}\right)\big[B_t-(T-t)\big]-\frac{\sigma^2}{4a}B^2_t\\
    &=-\frac{\s^2}{4a^2}\big[aB^2_t+2B_t-2(T-t)\big]+b\big[B_t-(T-t)\big].
\end{align}
It is a simple exercise to show that $\big[aB^2_t+2B_t-2(T-t)\big]\leq 0$ for $t\leq T$, hence $A_t$ is increasing in $\s$.
It is possible to characterize $(P_t)_{t\in[0,T]}$ as the solution of the linear Brownian BSDE:
$$P_t=1-\int_t^Tr_sP_s\d s-\int_t^TZ_s\d W_s.$$ 

Theorem~\ref{TH:resilience_jumps}, which can be applied thanks to Remark~\ref{REM:verification_brownian}, yields the resilience rate of the zero-coupon bond price, as follows:
\begin{equation}
\label{EQ:vasicek_resilience_rate}
    \bm\dot P_\t =\E\left[r_\t P_\t |\tau<T\right]=\E\left[r_\t \exp\left(A_\t -B_\t r_\t \right)|\tau<T\right], \qquad \t\in\mathcal T_T.
\end{equation}

Since for deterministic times $t\in[0,T]$, $r_t$ follows a Gaussian distribution with mean $\mu_t$ and variance $\Sigma^2_t$, after some algebra, we obtain the explicit formula:
\begin{equation}
\label{EQ:vasicek_dot_Pt}
    \bm\dot P_t=
    \left(\mu_t-B_t\Sigma^2_t\right)\exp\left(A_t+\frac{\Sigma_t^2B^2_t}{2}-\mu_tB_t\right).
\end{equation}
\begin{figure}[t]
    \hspace{-1.4cm}
    \includegraphics[width=1.2\textwidth]{Vasicek_high_reversion_upper_rate.png}
    \caption{\footnotesize{We numerically simulated $10^6$ random trajectories for a risk-free interest rate $r$ that follows equation~\eqref{EQ:vasicek}, namely a standard Vasicek model, with speed of reversion $a=1.0 \,y^{-1}$, long-term mean level $b=2\% \,y^{-1}$, initial value $r_0 = 2\% \,y^{-1}$ and instantaneous volatility $\s = 0.01 \, y^{-3/2}$.
    The time step was set to ${\d t=y/365}$.
    Based on these simulations, we used equation~\eqref{EQ:vasicek_bond_price} to calculate the price $P$ of a zero-coupon bond available in the market.
    The colored solid lines in the graph represent a selection of put option price trajectories.
    The black dotted line depicts the expected time evolution of the bond price, namely $[0,T]\ni t\mapsto \E[P_t]$, numerically computed by averaging over the $10^6$ trajectories of $P$. 
    The red dashed line is the time evolution of the resilience rate, i.e., $(0,T)\ni t\mapsto \bm\dot P_t$, see equation~\eqref{EQ:vasicek_dot_Pt}.
    Using equation~\eqref{EQ:vasicek_resilience_rate}, we computed the resilience rate $\bm\dot P_\tau\approx0.05\, \text{\euro}y^{-1}$ at the stopping time $\tau:=T\wedge \inf\{t\in[0,T] \ :\ r_t\geq 5\%\,y^{-1}\}$, where the expectation was numerically estimated by averaging over the $10^6$ trajectories.
    In the graph, the bond price trajectories for which the underlying risk-free interest rate breached the $5\%\,y^{-1}$ barrier, were truncated at the breaching time. 
    At each truncation point, the resilience rate $\bm\dot P_\tau$ is represented as the slope of an incident line.
    }}
\label{FIG:vas_rate}
\end{figure}

Recalling that $P_t$ represents the price of a zero-coupon bond at time $t \in [0,T]$ with maturity $T$, the previous formula aligns with financial intuition.
Indeed, let us notice that both $\Sigma^2_t$ and $A_t$ are increasing in $\s$, hence a high instantaneous volatility in the underlying stochastic interest rate results in a more negative resilience rate, meaning the price of the zero-coupon bond is expected to decrease in the near future.
{Close to maturity, i.e., in the limit as $t\to T^-$, the resilience rate tends to the mean interest rate $\mu_T$.}
For small values of the interest rate $r_t$, the resilience rate $\bm\dot P_t$ is negative, indicating that the price of the zero-coupon bond is expected to decline as a result of the fluctuations in the interest rate.
However, if $r_t$ increases, so does $\bm\dot P_t$, which means that the coupon is less responsive to fluctuations in the interest rate, if the interest rate is high.
Eventually, the resilience rate at positive times is increasing (in absolute value) with the speed of reversion $a$, keeping any other parameter fixed: the faster the interest rate reverts to its long-term mean, the higher the recovery rate for the bond price.

\end{example}
\begin{example}[Ambiguous interest rates]
The previous example assumed the existence of a stochastic, yet non-ambiguous, interest rate. 
However, in reality, a certain degree of ambiguity regarding the interest rate can exist, which may influence the decisions of a risk-averse agent. 
The present example, inspired by \cite[Example~7.2]{ELKR09}, allows us to interpret the resilience rate of an asset when the interest rate exhibits a certain level of ambiguity, specifically, when it fluctuates between an upper and a lower bound depending on the beliefs of the agent.

Assume that $(r_t)_{t\in[0,T]}$ and $(R_t)_{t\in[0,T]}$ are adapted, bounded, continuous and non-negative processes, which represent the inferior and superior bounds, respectively, for the ambiguous discount rate.
Let us consider the Brownian BSDE
    \begin{equation}
        \r_t (X)=X-\int_t^T\big(r_s\r^+_s-R_s\r^-_s\big)\d s -\int_t^T Z_s\d W_s,
    \end{equation}
    where $x^\pm:=0\vee (\pm x)$, for $x\in\R$.
    For $\om\in\Om$, $t\in[0,T]$ and $y\in\R$, the driver can be rewritten as
     \[
        g(\om,t,y)
        :=R_t(\omega)y^--r_t(\omega)y^+
        =\sup_{\b \in[r,R]}\big(-\b_t(\om) y\big)
    \]
    where the supremum is taken over all adapted stochastic processes $(\b_t)_{t\in[0,T]}$ such that $\P(r_t\leq \beta_t\leq R_t)=1$ for all $t\in[0,T]$.
    Since the driver is convex, Lipschitz continuous in $y$ and continuous in $t$, the BSDE has a unique solution with continuous paths.

    We see, by direct inspection, that for any $t\in[0,T]$
    \[
        g(t, \rho_t)
        =\sup_{\b \in[r,R]}\left(-\b_t \rho_t\right)
        =-\left(r_t\1_{\{\rho_t\geq 0\}}+R_t\1_{\{\rho_t<0\}}\right)\rho_t
        =:-\bar \b_t\rho_t, \qquad \P\text{-a.s.},
    \]
    where we introduced the compact notation $\bar\b_t$ to rewrite the driver as $g(\om,t,y)=\bar\b_t(\om) y$.

 \noindent As proved in \cite{ELKR09}, $\rho_t(X)$ admits the following representation:
     \[   \rho_t (X)
        =\E\left[\left.e^{-\int_t^T\bar\b_s\d s }X\right|\F_t\right],
        \qquad \P\text{-a.s.}.
    \]

\noindent   If we assume that $r$ and $R$ are induced by forward SDEs, by a straightforward application of Theorem~\ref{TH:resilience_jumps}, we see that, for any $\tau\in\mathcal{T}_{T}$, 
    \[
        \bm\dot\rho_{\tau}(X)=-\E[g(\tau,\r_\tau)|\tau<T]
        =\E[r_\tau\r_\tau^+-R_\tau\r^-_\tau|\tau<T],
    \]
which can be evaluated employing numerical simulations (see \cite{ARR24}, where this example has been extensively examined from a computational point of view). 
If we consider the case of a deterministic time $t\in[0,T]$, we can find explicit formulas. 
It is straightforward to verify that, by uniqueness of the solution to Lipschitz BSDEs
\begin{align}
    &\rho_t^{+} (X)=X^{+}-\int_t^Tr_s\rho_t^{+}\d s-\int_t^TZ_s^+\d W_s,\\
    &\rho_t^{-} (X)=X^{-}-\int_t^TR_s\rho_t^{-}\d s-\int_t^TZ_s^-\d W_s.
\end{align}
Thus, $(\rho^{\pm}_t)_{t\in[0,T]}$ are driven by linear BSDEs and we have:
\begin{align}
    \bm\dot\r_t (X)
    &=\E\left[r_t\r^+_t-R_t\r^-_t\right]  \\
    &=\E\left[r_t\E\left[\left.e^{-\int_t^Tr_s\d s }X^+\right|\F_t\right]-R_t\E\left[\left.e^{-\int_t^TR_s\d s }X^-\right|\F_t\right]\right]\\
    &=\E\left[\E\left[\left.r_te^{-\int_t^Tr_s\d s }X^+-R_te^{-\int_t^TR_s\d s }X^-\right|\F_t\right]\right]\\
    &=\E\left[r_te^{-\int_t^Tr_s\d s }X^+-R_te^{-\int_t^TR_s\d s }X^-\right].
\end{align}
If we now suppose that $r$ and $R$ are deterministic functions, then 
\begin{align}
    \bm\dot\rho_t (X)
    &=r_te^{-\int_t^Tr_s\d s}\E\left[X^+\right]-R_te^{-\int_t^TR_s\d s }\E\left[X^-\right].
\end{align}
Let us note that the right-hand side of the previous equation can be either negative or positive at different times, depending on the functions $R$ and $r$ and the terminal condition $X$.
 \end{example} 
\begin{example}[Entropic risk measure]
The entropic risk measure is intimately connected to the Kullback-Leibler divergence; see \cite{C75,BT86,BT87,LS13,FS16}.
It is used by \cite{HS01} to obtain robustness in macroeconomic models.
It is well-known that the dynamic entropic risk measure  $(e^{\gamma}_t)_{t\in[0,T]}$, with parameter $\gamma>0$, follows the quadratic Brownian BSDE
$$e^{\gamma}_t(X)=X+\int_t^T\frac{\gamma}{2}|Z^e_s|^2\d s-\int_t^TZ_s^e\d W_s,$$
which admits a unique solution for any terminal condition $X$ such that $\mathbb{E}[\exp(pX)]<+\infty$ for any $p>0$.
In particular, the solution to this BSDE is explicitly given by (see \cite[Example~5.1]{KO14}):
\begin{align}
&e^{\gamma}_t(X)=\frac{1}{\gamma}\ln\mathbb{E}\left[\left.\exp(\gamma X)\right|\mathcal{F}_t\right], \quad
Z^e_t=\frac{\mathbb{E}\left[\left.\exp\left(\frac{1}{\gamma }X\right) D_tX\right|\mathcal{F}_t\right]}{\mathbb{E}\left[\left.\exp\left(\frac{1}{\gamma }X\right)\right|\mathcal{F}_t\right]},
\end{align}
where $D_t$ is the Malliavin derivative operator at time $t$.
Let us consider $X= W_T$. 
By the first thesis in Theorem~\ref{TH:resilience_jumps}, we have:
$$\bm\dot e^{\gamma}_t(X)=-\mathbb{E}\left[\frac{\gamma}{2}|Z_t^e|^2\right]=-\frac{\gamma}{2}\mathbb{E}\left[\left|\frac{\mathbb{E}\left[\left.\exp\left(\frac{1}{\gamma }W_T\right) D_t W_T\right|\mathcal{F}_t\right]}{\mathbb{E}\left[\left.\exp\left(\frac{1}{\gamma } W_T\right)\right|\mathcal{F}_t\right]}\right|^2\right]=-\frac{\gamma}{2},$$
where the last equality is due to $D_t W_u=\1_{\{t \leq u\}}$.
Recalling the interpretation of $\gamma$ as the risk-tolerance coefficient, it is clear from the previous expression that the greater an agent's tolerance for risk, the higher the financial resilience rate of $e^{\gamma}_t$.
\end{example}

\subsection{Brownian-Poissonian filtration}

\begin{example}[Conditional expectation, $g\equiv 0$]
As shown in \cite[Example~2.3]{LS14}, the simplest case of a BSDE is induced by the martingale representation theorem. 
Let us assume ${X\in L^2(\mathcal{F}_T)}$ and consider the BSDE
\[
    \rho_t(X)=X-\int_t^TZ_s\cdot\d W_s-\int_{(t,T]\times\R^d_\ast}U_s(x)\d \tilde N(s,x),
\]
whose unique solution has first component given by $\rho_t(X)=\mathbb{E}\left[\left.X\right|\mathcal{F}_t\right]$. 
In this case, $g\equiv0$ and Theorem~\ref{TH:resilience_jumps} yields $\bm\dot\rho_{\tau}(X)=0=\bm\dot\rho_{\tau|\tau}(X)$ for any choice of $\t\in\mathcal T_T$.
Thus, the conditional expectation is \textit{resilience-neutral}, i.e., once a certain level of risk is reached, there is no trend to bounce back and recover. 
\end{example}

\begin{example}[Pricing in incomplete market]

As in Example~\ref{EX:black_scholes}, let us consider a financial market with a free-risk asset with null interest rate, and a risky asset $S$. 
We now suppose that the risky asset evolves according to the linear SDE with jumps
\begin{equation}
    S_t=S_0+\int_0^t\mu_sS_s\d s+\int_0^t\sigma_sS_s\d W_s+\int_{[0,t]\times\R_\ast}\gamma_s(x)S_s\d \tilde N(s,x),
\end{equation}
where $S_0>0$ is deterministic, while $\mu, \s:\Om\times[0,T]\to\R$ and $\g:\Om\times[0,T]\to \Lambda^2$ are $\P$-a.s. continuous $\bm\F$-adapted stochastic processes.
We suppose that $\mu$ is $\P$-a.s. bounded and that $\s$ is $\P$-a.s. positive and bounded away from $0$.
Further assume that the jump measure $\nu$ is finite, so that $N_t:=N\big([0,t]\times\R_\ast\big)$, for $t\geq 0$, is a standard Poisson process with rate $\nu(\R_\ast)$.

In general, this market will not be complete, see, for instance, \cite[Theorem~2.12]{OS19}.
However, for a claim $X$, \textit{i.e.,} an $\F_T$-measurable random variable, we can define an arbitrage-free price $P_t(X)$ at time $t\in[0,T]$ by 
\[
    P_t(X)=\E^\Q[X|\F_t],
\]
see \cite[Theorem~2.14]{OS19}, where $\E^\Q$ denotes the expectation calculated with respect to an equivalent martingale measure $\Q$.

Suppose that
\begin{align}
    \mathcal E_t
    :=\exp\left(-\int_0^t\frac{\mu_s}{\s_s}\d W_s-\frac12\int_0^t\left(\frac{\mu_s}{\s_s}\right)^2\d s \right)
\end{align}
exists for $t\in[0,T)$ and satisfies $\E[\mathcal E_T]=1$. 
If we define the probability measure $\Q$ on $(\Om,\F_T)$ whose density with respect to $\P$ is ${\mathcal{E}_T}$, then $\P$ and $\Q$ are equivalent probability measures.
By the version of Girsanov's theorem in \cite[Theorem~1.31]{OS19}, and since $\mu/\s$ is $\P$-a.s. bounded, we know that $\Q$ is an equivalent martingale measure.
Moreover, if we let for all $t\geq 0$
\[
    W^\Q_t := \frac{\mu_t}{\s_t}+W_t,\qquad \Q\text{-a.s.},
\]
then, see \cite[Theorem~1.33]{OS19}, $W^\Q$ is a $\Q$-Wiener process, while 
$\tilde N$ remains a compensated Poisson random measure of $N$ with respect to $\Q$, in the sense that, for all $t\in[0,T]$ and all $B\in\mathscr B(\R_\ast)$ such that $\nu(B)<+\infty$, the process $\tilde N([0,t]\times B)$ is a $\Q$-martingale.

It is simple to show by \cite[Theorem~4.8]{OS19} that there exists $(Z,U)\in\mathcal L^2(W)\times\mathcal L^2(\tilde N)$ such that $\big(P(X),Z,U\big)$ is the solution of the linear BSDE
\begin{align}
    P_t(X)
    &=X-\int_t^T\frac{\mu_s}{\s_s}Z_s\d s -\int_t^TZ_s\d W_s - \int_{(t,T]\times\R_\ast}U_s(x)\d\tilde N(s,x)\\
    &=X-\int_t^TZ_s\d W^\Q_s - \int_{(t,T]\times\R_\ast}U_s(x)\d\tilde N(s,x),
\end{align}
hence $P(X)$ can be seen as a risk measure on $L^\infty(\F_T)$, see Remark~\ref{REM:induced_dyn_risk_meas}.
We now resort to the version of the Clark-Ocone formula in \cite[Theorem~12.22]{DNOP09} applied to $X$, to get, for $s\in[0,T]$:
\begin{align}
    Z_s
    &= \E^\Q\left[\left.D_sX-X\int_s^TD_s\frac{\mu_r}{\s_r}\d W^\Q_r\right|\F_s\right], \qquad\Q\text{-a.s.},
\end{align}
where $D_s$, $s\geq 0$, is the Malliavin derivative with respect to $W^\Q$.
We recall that the following property holds for any $Y\in L^1(\F)$:
\begin{equation}
    \E^\Q [Y|\F_t]=\mathcal E^{-1}_t\E[Y\mathcal E_T|\F_t], \qquad \forall\, t\in[0,T].
\end{equation}
Therefore, for almost any $t\in[0,T)$ we have by Theorem~\ref{TH:resilience_jumps}\itemref{IT:th:resilience_jumps:deterministic}
\begin{align}
    \bm\dot P_t(X)
    &=-\E\left[-\frac{\mu_t}{\s_t}Z_t\right]\\
    &=\E\left[\frac{\mu_t}{\s_t}\E^\Q\bigg[D_tX-X\int_t^TD_t\frac{\mu_s}{\s_s}\d W^\Q_s\bigg|\F_t\bigg]\right]\\
    &=\E\left[\frac{\mathcal E_T}{\mathcal E_t}\frac{\mu_t}{\s_t}\bigg(D_tX-X\int_t^TD_t\frac{\mu_s}{\s_s}\d W^\Q_s\bigg)\right].
\end{align}
The formula significantly simplifies if $\mu$ and $\s$ are supposed to be deterministic.
Were this the case, we would have
\[
    \bm\dot P_t(X)=\E\left[\frac{\mathcal E_T}{\mathcal E_t}\frac{\mu_t}{\s_t}D_tX\right], \qquad \ell_1\text{-a.e. } t\in[0,T).
\]

Let us give an explicit computation for a European plain vanilla call option, where $X=(S_T-K)^+$ for some $K>0$, and with the additional assumption of $\mu,\s,\g$ being constants, with $\g>-1$.
By the chain rule for the Malliavin derivative, we know that 
\begin{align}
    D_{t}X = D_t (S_T-K)^+=\s S_T\1_{[K,+\infty)}(S_T).
\end{align}
Moreover, by direct inspection
\[
    \frac{\mathcal E_T}{\mathcal E_t} = \exp\left(-\frac\mu\s(W_T-W_t)-\frac12\left(\frac\mu\s\right)^2(T-t)\right).
\]
Therefore, for a.e. $t\in[0,T)$ we have
\begin{equation}
\label{EQ:formula}
    \bm\dot P_t(X)
    =\mu \exp\left(-\frac12\left(\frac\mu\s\right)^2(T-t)\right)\E\left[\exp\bigg(-\frac\mu\s(W_T-W_t)\bigg)S_T\1_{[K,+\infty)}(S_T)\right].
\end{equation}
We recall that
\[
    S_T = S_0\exp\left(\Big(\mu -\frac12\s^2\Big)T+\s W_T\right)(1+\g)^{N_T},    
\]
and that $N_T \sim N_{T-t}+N_t$, $W_T \sim W_{T-t}+W_t$, and $W_T-W_t\sim W_{T-t}$, where $W_{T-t}$, $W_t$, $N_t$, $N_{T-t}$ are independent random variables. 
Thus, the expectation in equation~\eqref{EQ:formula} can be analytically computed in terms of the distributions of the Wiener and standard Poisson processes.
The result will be expressed in terms of numerical series and Gaussian integrals, which can be numerically simulated for practical purposes.
\end{example}

\subsection{Financial Interpretation}
After establishing the main mathematical framework, we want to carefully revisit the financial meaning of the resilience rate and the implications of having an explicit expression for it. 
Let us consider a risk measure (or, equivalently, a pricing functional) $\rho$ induced via BSDEs.
If we have a risky asset $X$, it would be interesting to understand what the average risk/price of $X$ is under the real-world probability.
Indeed, by design, BSDE-based risk measures are intended to reflect the real preferences of an agent, hence the necessity of working with the real-world probability $\P$, under which the agent's expectations are formed.
By our theoretical results (see Corollary~\ref{COR:resil_brownian}) we know that—under suitable assumptions—
\begin{align}
    \mathbb{E}[\rho_t(X)] 
    &=\mathbb{E}[\rho_0(X)]+t\cdot\frac{\d }{\d t}\bigg|_{t=0}{\mathbb{E}}[\rho_t(X)] +O(t^2)\\
    &= \rho_0(X)+\bm\dot\rho_0(X)\cdot t + O(t^2)\\
    &=\rho_0(X)-g\big(0,\rho_0(X),Z_0\big)\cdot t+O(t^2), \qquad \text{as }t\to 0^+.\label{EQ:approx}
\end{align}
We can assume that the previous is a good proxy for $\mathbb{E}[\rho_t(X)]$ for $t$ sufficiently close to $0$. 
From the previous formula, it is clear that $g$ reflects the preferences of the investor about future realizations of the risk/price of $X$.

Generally speaking, $\bm\dot\rho$ further clarifies the meaning of $g$ as an infinitesimal generator. Indeed, as already observed in \cite{BEK05}, $g$ reflects the infinitesimal expectation of a market participant.
The resilience rate completes the picture: the driver $g$ represents, through its expectation, the sensitivity of the risk/price functional to time fluctuations under the real-world measure $\P$. In particular, $g$ can be chosen, for instance, to obtain a pre-determined average, by adding or removing some drift. Note, however, that this choice has many degrees of freedom: there are infinitely many drivers $g$ that generate the same price/risk expectation.

In this regard, we would like to remark that - as currently happens for capital requirements - regulators might impose a threshold under which the resilience rate, i.e. the exposure to time fluctuations of the risk, must stay. In this sense, it would be reasonably easy to adjust the risk model to satisfy such constraints, by varying the drift to be compliant with the threshold. 
Financially speaking, changing the driver will correspond to a change of the preference in the financial position/portfolio choice, to make it acceptable under the regulator's framework.
\subsubsection{Black and Scholes paradigm}
To shed further light on this, let us consider a financial market with a free-risk asset with null interest rate ($r=0$), and a risky asset $S$ that follows a geometric Brownian motion with constant drift $\mu$ and constant volatility $\s$. 
In the setting of the Black and Scholes model, the price $P$ of a plain vanilla put option is the first component of the solution of a BSDE, where the driver satisfies $g(t, P_t,Z_t)=\mu Z_t/\s=\mu \pi_tS_t$ for $t\in[0,T]$, where $\pi_t\in(0,1)$ denotes the optimal fraction of a financial portfolio invested in the risky asset $S$ at time $t$.
See Example~\ref{EX:black_scholes} for more insights.
In this framework, the expected future price becomes:
\begin{equation}
    \mathbb{E}[P_t] \sim P_0 + \mu S_0 \pi_0\cdot t = P_0 + \mu S_0 \Delta_0\cdot t, \qquad \text{ as } t\to 0^+,
\label{eq:TaylorRes}
\end{equation}
recalling that the Greek $\Delta$ coincides with the strategy $\pi$.
As expected, the previous expression reflects the investor's preferences (through the presence of $\mu$).
In particular, the previous equation is:
\begin{itemize} 
    \item Increasing in time, if $\mu > 0$, and decreasing if $\mu < 0$. 
    \item Easy to evaluate: all the quantities in the formula are available in almost every pricing engine. 
    \item A good proxy for $\mathbb{E}[P_t]$ even for times close to maturity (see Figure~\ref{FIG:ideal} in Example~\ref{EX:black_scholes}). 
\end{itemize}

Let us remark that, if we would like to have a constant average price under $\P$, i.e., $\E[P_t] = P_0$ (recalling that $r = 0$), then we would need
\[
    0=\E[P_t]-P_0\sim\mu S_0\Delta_0 \cdot t \ \implies \Delta_0 = 0.
\]

More in general, at portfolio level, delta-hedging means holding an asset evolving (locally) risk free. In this case, if an agent deals with an option with price $P$ and with delta-greek $\Delta$, then static $\Delta$-hedging means choosing 
$\Pi_t:=P_t - \Delta_0S_t$ as portfolio. 
Then, the dynamics for $\Pi$ are given by:
\[
    \begin{cases} 
        d\Pi_t &= \d P_t-\Delta_0\d S_t = (\pi_t-\Delta_0)\mu S_t\d t + (\pi_t-\Delta_0)\sigma S_t\d W_t, \\
        \Pi_T &= P_T - \Delta_0 S_T,
    \end{cases}
\]
which can be rewritten as:
\begin{equation}
    \Pi_t = P_T +\int_t^T g(s,Z^{\Pi}_s)\d s-\int_t^TZ^{\Pi}_s\d W_s,
\end{equation}
where we defined $Z^{\Pi}:= (\pi-\Delta_0)\sigma S$ and $g(t,z):=-\frac{\mu}{\sigma}z.$ Note that by construction $\pi_0=\Delta_0$. 
Thus, by direct application of equation~\eqref{EQ:approx}, we observe that the first-order term in the Taylor expansion of $\E[\Pi_t]$ vanishes:
\[
    \mathbb{E}\left[\Pi_t\right] = \Pi_0 + \mu(\pi_0-\Delta_0)S_0\cdot t +O(t^2)= \Pi_0+O(t^2), \qquad \text{as }t\to 0^+.
\]
This means that static $\Delta$-hedged portfolios are less exposed to fluctuations of the underlying asset, as their expected rate of return is constant in time, up to second order expansion.
Note that this is different from the Black and Scholes risk-neutral perspective: under $\Q$, it is known that $\E^\Q[P_t]$ is automatically constant since it is a $\Q$-martingale. 
Nevertheless, under the real-world measure $\P$, we need to be $\Delta$-hedged to obtain locally constant average prices.

\subsubsection{Incomplete market}
We presented our theory under the Black and Scholes framework to make it intuitive. Nevertheless, what we developed remains valid in full generality even considering more complicated pricing models. For instance, it is possible to deal with incomplete markets to price European derivatives. In this scenario, a complex model such as a stochastic volatility model (e.g., Heston or SABR models) can be embedded in our setting. The price of the derivative will be given by a FBSDEs system, the forward part to model the volatility and the backward part to model the price (for a thorough discussion on this topic, see \cite{HIM05,FT12} and references therein). 
Using the results of Section~\ref{subsec:VT} and the above logic, we can once again find the conditions under which the expected price of this (complex) derivative is less exposed to fluctuations. 

To be more precise, let us briefly illustrate what happens in these more sophisticated scenarios. Let $\pi$ a strategy, $X^{\pi}$ be the associated wealth process, and $F$ a European payoff. Then, an investor dealing with an incomplete market and interested in (partially) hedging the risk of $F$ will face with an utility maximization problem, in order to find the indifference price $(P_t)_{t\in[0,T]}$ given by the following condition (cf.\ \cite[Section~1]{MS05}):
\[
    \esssup_{\pi\in\mathcal{A}}\E\left[\left.\mathcal U(X^{\pi}_T)\right|\F_t\right] =\esssup_{\pi\in\mathcal{A}}\E\left[\left.\mathcal U(X^{\pi}_T+F-P_t)\right|\F_t\right].
\]

Let us consider 
an exponential utility function $\mathcal U(x;\alpha):=-\exp(-\alpha x)$  with $\alpha>0$\footnote{Note that we can reach the same conclusions for all utility function maximization problems that can be solved through FBSDEs, see \cite{HHIRZ14} for a general discussion}. 
By \cite[Proposition~2]{MS05} and  \cite[Proposition~9]{HIM05}, we know that the indifference price can be written as:
\[
    P_t = Y_t^{F}-Y_t^0,
\]
where $Y^{H}$, $H\in\{F,0\}$, is the unique solution to the following BSDE:
\[
    Y^H_t = H -\int_t^Tf(s,Z_s^H)ds-\int_t^TZ_s^HdW_s.
\]
Here $-f$ is a suitable driver satisfying quadratic assumptions explicitly \textit{depending on the risk preferences} of the agent, i.e., on the parameter $\alpha$. In detail, it is clear that also $P$ follows a BSDE, given by:
\begin{equation}
    P_t = F + \int_t^Tg(s,Z_s^P)ds-\int_t^TZ_s^PdW_s,
\label{eq:BSDEpar}
\end{equation}
where $Z^P:=Z^F-Z^0$ and $g(\, \cdot\, ,z):= -f(\,\cdot\,,Z^F)+f(\,\cdot\,,Z^F-z)$.
Thus, $(P,Z^P)\equiv (Y^F-Y^0,Z^F-Z^0)$ is a solution to the BSDE~\eqref{eq:BSDEpar}, and $g(\,\cdot\,,Z^P)$ shares the same integrability properties of $f(\,\cdot\,,Z^H)$ for $H\in\{F,0\}.$
Hence, Corollary~\ref{COR:resil_brownian} can be applied to the process $P$.
Thus, making use of equation~\eqref{EQ:approx}, we can find the expression of $\E[P_t]$ in terms of $P_0$ and $\bm\dot P_0$, for $t$ small enough. This allows us to tailor the portfolio's risk profile according to the regulator's demands, even in this much more complicated setting. In particular, this shows that our definition of resilience rate is very natural, and that a wide variety of financial situations can be analyzed through this paradigm.

