\section{SRG renormalization for complex qs$GW$}
\label{app:srg}
%%%%%%%%%%%%%%%%%%%%%%%%

We extended the SRG renormalization method\cite{Marie_2023} for complex-valued energies, which yields the following matrix elements of the self-energy
\begin{equation} \label{eq:SRG-self-energy}
	\begin{split}
		[\tilde{\Sigma}_\text{c}]_{pq}
		& = \sum_{i\nu} \frac{(\tilde{\epsilon}_{pi\nu} + \tilde{\epsilon}_{qi\nu})N_{pqi\nu}}{\tilde{\epsilon}_{pi\nu}^2 + \tilde{\epsilon}_{qi\nu}^2 + \tilde{\kappa}_{pi\nu}^2 + \tilde{\kappa}_{qi\nu}^2} 
		\\
		& + \sum_{a\nu} \frac{(\tilde{\epsilon}_{pa\nu} + \tilde{\epsilon}_{qa\nu})N_{pqa\nu}}{\tilde{\epsilon}_{pa\nu}^2 + \tilde{\epsilon}_{qa\nu}^2 + \tilde{\kappa}_{pa\nu}^2 + \tilde{\kappa}_{qa\nu}^2}
		\\
		&+ \ii \sum_{i\nu} \frac{(\tilde{\kappa}_{pi\nu} + \tilde{\kappa}_{qi\nu})N_{pqi\nu}}{\tilde{\epsilon}_{pi\nu}^2 + \tilde{\epsilon}_{qi\nu}^2 + \tilde{\kappa}_{pi\nu}^2 + \tilde{\kappa}_{qi\nu}^2}
		\\
		&- \ii \sum_{a\nu} \frac{(\tilde{\kappa}_{pa\nu} + \tilde{\kappa}_{qa\nu})N_{pqa\nu}}{\tilde{\epsilon}_{pa\nu}^2 + \tilde{\epsilon}_{qa\nu}^2 + \tilde{\kappa}_{pa\nu}^2 + \tilde{\kappa}_{qa\nu}^2}
	\end{split}
\end{equation}
with the real and imaginary parts of the denominator in Eq.~\eqref{eq:self_energy}
\begin{subequations}
	\begin{align}
		\tilde{\epsilon}_{pq\nu} & = \Re{ \epsilon_p - \epsilon_q - \sgn[\Re(\epsilon_q - \mu)] \Omega_\nu } 
		\\
		\tilde{\kappa}_{pq\nu} & = \kappa + \Im{ \sgn[\Re(\epsilon_q - \mu)] (\epsilon_p - \epsilon_q) - \Omega_\nu }
	\end{align}
\end{subequations}
(where $\mu$ is the chemical potential) and the renormalized elements
\begin{equation}
	N_{pqr\nu} = M_{pr,\nu}M_{qr,\nu}
	\qty[1- e^{-s\qty(\tilde{\epsilon}_{pr\nu}^2 + \tilde{\epsilon}_{qr\nu}^2+\tilde{\kappa}_{pr\nu}^2 + \tilde{\kappa}_{q r\nu}^2)}]
\end{equation}
The exponential term in the renormalized density ensures that the numerator tends faster to zero when both the real and imaginary parts of the denominator tend to zero. 

