% \end{equation}
% \noindent where $\mathcal{M}=\begin{pmatrix} 1 & 0 \\ 0 & 0 \end{pmatrix}$, $\mathcal{N}$ is the non-linear N-S operator including the non-linear convection, pressure gradient, viscous diffusion and incompressibility terms and $\mathcal{P}=\begin{pmatrix} 1 \\ 0 \end{pmatrix}$.

