\begin{equation}
    \mathsfbi{M} \partial_t \boldsymbol{w} + \mathsfbi{L}\boldsymbol{w} + \mathsfbi{N}(\boldsymbol{w},\boldsymbol{w})/2= A \mathsfbi{M}\mathsfbi{P} \boldsymbol{f}'(z,t),
    \label{eq:semi-discrete NS}
\end{equation}}
% We now treat $x$ and $y$ as discrete spatial directions, while the $z$ spatial direction and time $t$ as continuous. After discretising \eqref{eq:NS state-space} on a 2D $x$-$y$ computational mesh, we arrive at the semi-discrete N-S equations,
% \begin{equation}
