\title[Regularity of profinite isomorphisms and the A-polynomial]{On regularity of profinite isomorphisms between cusped hyperbolic 3-manifolds and the A-polynomial}


\begin{document}
\begin{sloppypar}
\maketitle
\begin{abstract}
We prove that any isomorphism between the profinite completions of the fundamental groups of two cusped finite-volume hyperbolic 3-manifolds is regular and peripheral regular. As an application, we show that the $A$-polynomial of prime knots in $S^3$ is a profinite invariant, up to possible mirror image. 
\end{abstract}
\setcounter{tocdepth}{1}
\tableofcontents %tabel of contents
\section{Introduction}
Profinite rigidity questions to which extent a finitely generated, residually finite group is determined by its finite quotient groups. These data are equivalently encoded in an algebraic  construction named profinite completion according to \cite{DFPR82}.
\begin{definition}\label{DEF: profinite completion}
Let $G$ be a group, the {\em profinite completion} of $G$ is defined as 
\begin{equation*}
\widehat{G}=\limi\,\quo{G}{N}
\end{equation*}
where $N$ ranges over all finite-index normal subgroups of $G$.%, partially ordered by inclusion. 
\end{definition}

The question becomes more accessible when we restrict ourselves to 3-manifold groups. Since 3-manifolds are largely determined by their fundamental groups, it is natural to ask which topological or geometrical properties of a compact 3-manifold $M$ is determined by the isomorphism type of $\widehat{\pi_1M}$.

\begin{convention*}
In this article, all 3-manifolds are orientable unless otherwise stated. 
\end{convention*}

\setcounter{footnote}{1}

Proven in a series of works by Wilton--Zalesskii \cite{WZ17, WZ17b, WZ19}, as well as the works of Wilkes \cite{WilkesJSJ,Wil19} for the bounded case, the profinite completion of the fundamental group determines whether a compact 3-manifold $M$ is geometric (in the sense of Thurston); it determines the geometry type in the geometric case, and determines the prime decomposition and the JSJ-decomposition in the non-geometric case. Many examples of 3-manifolds are proven to be profinitely rigid, that is, uniquely distinguished among compact 3-manifolds by the profinite completion of its fundamental group, see \cite{BMRS20, Cw24, Wil17, Wil18, Xu24b}. However, the general question for profinite rigidity in 3-manifolds is still widely open. In \cite{Xu24a}, the author proved that the the profinite completion of the fundamental group determines the homeomorphism type of a compact 3-manifold $M$ with empty or toral boundary up to finitely many possibilities, which we refer to as the `profinite almost rigidity', and the remaining challenging part is the case of hyperbolic 3-manifolds (including closed and cusped manifolds). 

\subsection{Regularity and peripheral regularity}
The first part of this paper characterizes a useful feature of isomorphisms between the profinite completion of the fundamental groups of hyperbolic 3-manifolds. 
The notion of regularity for a profinite isomorphism was first introduced by Boileau--Friedl \cite{BF19}.
\begin{definition}\label{introdef: Zx regular}
Let $G$ and $H$ be two groups. An isomorphism $f:\widehat{G}\to \widehat{H}$ is called {\em regular} if the induced isomorphism $\widehat{\ab{G}}\to \widehat{\ab{H}}$ is the profinite completion of an isomorphism $\ab{G}\to \ab{H}$, where `$\mathrm{ab}$' denotes the abelianization.  
\end{definition}

In the study of profinite rigidity among 3-manifold groups, peripheral subgroups in 3-manifold groups plays an important role. A related notion named peripheral regularity was introduced by the author in \cite{Xu24a,Xu24b}. 
\begin{definition}\label{introdef: peripheral Zx regular}
Let $M$ and $N$ be compact 3-manifolds with incompressible toral boundaries, and let $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ be an isomorphism. 
\iffalse An isomorphism $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is called {\em peripheral regular} if 
\begin{enumerate}[leftmargin=*]
\item there is a one-to-one correspondence between the boundary components of $M$ and $N$, denoted by $\partial_iM\longleftrightarrow \partial_iN$, such that  $f(\overline{\pi_1\partial_iM})=g_i^{-1}\cdot \overline{\pi_1\partial_iN} \cdot g_i$  for some $g_i\in \widehat{\pi_1M}$; and
\item\label{(2)} for each $i$, the isomorphism $C_{g_i}\circ f|_{\overline{\pi_1\partial_iM}}:\widehat{\pi_1\partial_iM}\cong \overline{\pi_1\partial_iM}\tto \overline{\pi_1\partial_iN}\cong\widehat{\pi_1\partial_iN}$ is regular.
\end{enumerate}
\fi
\begin{enumerate}[leftmargin=*]
\item\label{(1)} We say that $f$ {\em respects the peripheral structure} if there is a one-to-one correspondence between the boundary components of $M$ and $N$, denoted by $\partial_iM\longleftrightarrow \partial_iN$, such that  $f(\overline{\pi_1\partial_iM})=g_i^{-1}\cdot \overline{\pi_1\partial_iN} \cdot g_i$  for some $g_i\in \widehat{\pi_1N}$, where $\pi_1\partial_iM\le \pi_1M$ and $\pi_1\partial_iN\le \pi_1N$ are conjugacy representatives of the peripheral subgroups.
\item We say that $f$ is {\em peripheral regular} if $f$ respects the peripheral structure (so we follow the notation in (\ref{(1)})), and for each $i$, the isomorphism $C_{g_i}\circ f|_{\overline{\pi_1\partial_iM}}:\widehat{\pi_1\partial_iM}\cong \overline{\pi_1\partial_iM}\tto \overline{\pi_1\partial_iN}\cong\widehat{\pi_1\partial_iN}$ is regular, where $C_{g_i}(x)=g_ixg_i^{-1}$ denotes the conjugation.  
\end{enumerate}
%
%Here, $\pi_1\partial_iM\le \pi_1M$ and $\pi_1\partial_iN\le \pi_1N$ are conjugacy representatives of the peripheral subgroups, and $C_{g_i}(x)=g_ixg_i^{-1}$ denotes the conjugation.  
\end{definition}

The main result of this article is the following theorem. 

\begin{theorem}\label{mainthm: regular}
Suppose $M$ and $N$ are cusped hyperbolic 3-manifolds and $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is an isomorphism. Then $f$ is regular and peripheral regular.
\end{theorem}

We remark that in general, a profinite isomorphism between 3-manifold groups may not be regular. This is demonstrated by the example of Hempel pairs \cite{Hem14}, as well as easily constructable examples for the 3-torus $T^3$ or the product of the once-punctured torus with $S^1$. Thus, \autoref{mainthm: regular} is particularly special for hyperbolic 3-manifolds. 

Weaker versions of \autoref{mainthm: regular} have been proven. Liu \cite{Liu23} proved that any isomorphism between the profinite completion of the fundamental groups of finite-volume hyperbolic 3-manifolds (including closed and cusped) is $\Zx$-regular, that is, the induced isomorphism $\widehat{H_1(M;\Z)}\to \widehat{H_1(N;\Z)}$ is the profinite completion of an isomorphism $H_1(M;\Z)\to H_1(N;\Z)$ composed with a scalar multiplication by some element $\lambda\in \Zx$, see \autoref{THM: Zx regular}. The author  proved in \cite{Xu24a} that any isomorphism between the profinite completion of the fundamental groups of cusped hyperbolic 3-manifolds is peripheral $\Zx$-regular, that is, replacing `regular' in \iffalse item (\ref{(2)}) of\fi \autoref{introdef: peripheral Zx regular} with `$\Zx$-regular', see \autoref{THM: peripheral Zx regular}. 

The proof of \autoref{mainthm: regular} is an improvement of these two weaker results. The key technique we utilize is the relative cohomology theory for profinite groups introduced by Wilkes \cite{Wil19}. In fact, for an isomorphism $f$ between the profinite completion of the fundamental groups of finite-volume hyperbolic 3-manifolds, we can define a profinite mapping degree $\deg(f)\in \Zx$ witnessed in the third relative homology groups. The coefficient $\lambda\in\Zx$ that appears in the $\Zx$-regularity statement is denoted by $\coef(f)$. We establish two relations between $\coef(f)$ and $\deg(f)$. On one hand, through passing onto the peripheral subgroups, we prove that $\coef(f)^2=\pm\deg(f)$. On the other hand, using the techinque of Dehn filling introduced in \cite{Xu24b}, we can also pass these invariants to a profinite isomorphism between closed hyperbolic 3-manifolds and prove that $\coef(f)^3=\pm \deg(f)$ based on a formula of Liu \cite[Lemma 5.3]{Liu25}. These two methods demonstrate a dimension shift, which in turn implies that $\coef(f)=\pm1$. 

\begin{remark}
When $M$ and $N$ are closed hyperbolic 3-manifolds and $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is an isomorphism, Liu \cite[Lemma 7.1]{Liu25} showed that $\coef(f)^2=1$. This is currently the closest result towards regularity in the closed case. Our proof for the cusped case relies on the boundary structure, and it cannot be extended directly to the closed case. 
\end{remark}

\subsection{The $A$-polynomial}

Knot complements in $S^3$ provide a delightful testing ground for profinite rigidity in 3-manifolds. For instance, Ueki \cite{Ueki} proved that knots in $S^3$ with profinitely isomorphic knot groups have identical Alexander polynomials. 
%Boileau--Friedl \cite{BF19} proved that torus knot complements are profinitely rigid among all knot complements in $S^3$, and Wilkes \cite{WilkesKnot} proved the profinite rigidity of prime graph knots among knot complements in $S^3$. 
Torus knot complements and prime graph knot complements are profinitely rigid among all knot complements in $S^3$, according to Boileau--Friedl \cite{BF19} and Wilkes \cite{WilkesKnot} respectively.  
In \cite[Theorem C]{Xu24b}, the author proved that the complement of hyperbolic knots or hyperbolic-type satellite knots in $S^3$ are distinguished from compact orientable 3-manifolds by the profinite completion of their fundamental groups. In addition, in \cite{Xu24b}, the author also showed the profinite rigidity of many hyperbolic knot complements, such as the complement of full twist knots, including a new proof for the figure-eight knot \cite{BR20}. 

The $A$-polynomial of a knot $K$ is a two-variable polynomial $A_K(M,L)$  defined by Cooper, Culler, Gillet, Long, and Shalen in \cite{CCGLS94}. This is a knot invariant related to the $\SL(2,\C)$-representations of 3-manifold groups. An enhanced version of the $A$-polynomial is also defined and used in many literatures  containing slightly more information than the $A$-polynomial, which we denote as $\widetilde{A}_K(M,L)$, see \autoref{subsec: A-poly} for complete definition. 
Briefly speaking, when defining the enhanced version, the component in the character variety of the knot complement given by reducible representations is excluded.
The relation between these two versions is simple. In fact,
$
A_K(M,L)=\mathrm{Red}((L-1)\widetilde{A}_K(M,L))
$, 
where `$\mathrm{Red}$' means reducing repeating factors. In particular, the enhanced $A$-polynomial completely determines the $A$-polynomial. 


For a knot $K$ in $S^3$, we denote $X(K)=S^3-\text{int}(N(K))$ as the exterior of $K$. An application of \autoref{mainthm: regular} is the following theorem.

\begin{theorem}\label{mainthm: A-polynomial general}
\iffalse
Let $J$ and $K$ be (nontrivial) knots in $S^3$. Suppose there is an isomorphism $\widehat{\pi_1(X(J))}\cong \widehat{\pi_1(X(K))}$ that respects the peripheral structure (see \autoref{introdef: peripheral Zx regular}). Then, up to possibly replacing $K$ with its mirror image, the $A$-polynomials of $J$ and $K$ coincide: $A_J(M,L)\doteq A_K(M,L)$.
\fi
Suppose $J$ and $K$ are knots in $S^3$, and $f: \widehat{\pi_1(X(J))}\to \widehat{\pi_1(X(K))}$ is an isomorphism. Suppose either $f$ respects the peripheral structure\footnote{assuming $J$ and $K$ are non-trivial.}, or one of $J$ and $K$ is a prime knot. Then, up to possibly replacing $K$ with its mirror image, the enhanced $A$-polynomials of $J$ and $K$ are identical: $\widetilde{A}_J(M,L)\doteq \widetilde{A}_K(M,L)$, and consequently their $A$ polynomials are also identical.
\end{theorem}

The assumption that either the isomorphism respects the peripheral structure, or one of the knots is a prime knot is analogous to the condition in distinguishing knots in $S^3$ through the fundmental group of their exteriors. In fact, given knots $J$ and $K$ in $S^3$, suppose $f: \pi_1(X(J))\to \pi_1(X(K))$ is an isomorphism; then, $J$ and $K$ are equivalent (including mirror image) if either $f$ respects the peripheral structure \cite{Wal68} or one of $J$ and $K$ is prime \cite{GL89}. Moreover, this assumption is necessary in \autoref{mainthm: A-polynomial general}. For non-prime knots $J=K_1\#K_2$ and $K=K_1\#\overline{K_2}$, where $\overline{K_2}$ denotes the mirror image of $K_2$, we always have $\pi_1(X(J))\cong \pi_1(X(K))$. However, in this case $A_J(M,L)$ and $A_K(M,L)$ may not coincide, see \cite{CL96} for the example of reef knot and granny knot. 



The core behind \autoref{mainthm: A-polynomial general} can be stated in the fashion of character varieties. For a compact connected manifold $Y$, let $\mathscr X_n(Y)$ denote the $\SL(n,\C)$-character variety of $\pi_1Y$, where $n\in \mathbb{N}$. For a compact disconnected manifold $Z$ consisting of components $Z_1,\cdots, Z_k$, we denote $\mathscr X_n(Z)=\mathscr{X}_n(Z_1)\times \cdots \times \mathscr{X}_n (Z_k)$. 
\begin{theorem}\label{mainthm: character variety}
%\iffalse
Suppose $M$ and $N$ are cusped hyperbolic 3-manifolds, and $\widehat{\pi_1M}\cong \widehat{\pi_1N}$. Then there exists a homeomorphism $\Psi:\partial M\to \partial N$ \iffalse, which is either orientation-preserving on all components or orientation-reversing on all components,\fi such that the images of the restriction maps $\mathscr{X}_n(M)\to \mathscr{X}_n(\partial M)$ and $\mathscr{X}_n(N)\to \mathscr{X}_n(\partial N)$ are identical through $\Psi$.  In addition, $\Psi$ is either orientation-preserving on all components or orientation-reversing on all components.
%\fi
\iffalse
Suppose $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is a peripheral regular isomorphism. Then, there exists a homeomorphism $\Psi:\partial M\to \partial N$ such that the images of the restriction maps $\mathscr{X}_n(M)\to \mathscr{X}_n(\partial M)$ and $\mathscr{X}_n(N)\to \mathscr{X}_n(\partial N)$ are identical through $\Psi$.
\fi
\end{theorem}
\iffalse
The condition that the profinite isomorphism respects the peripheral structure can be dropped when one of these knots is known to be a prime knot. 

\begin{theorem}
