\section{Preliminaries on profinite groups}\label{sec:2}
\subsection{Profinite groups}
A {\em profinite group} is an inverse limit of finite groups indexed over a directed partially ordered set, equipped with the subspace topology inherited from the product topology. A direct characterisation for profinite groups is shown by the following proposition.
\begin{proposition}[{\cite[Theorem 2.1.3]{RZ10}}]\label{PROP: Top}
A topological group $\Pi$ is a profinite group if and only if $\Pi$ is compact, Hausdorff, and totally disconnected.
\end{proposition}

The profinite completion of an abstract group $G$, defined as $\widehat{G}=\limi_{N\lhd_{f.i.}G} G/N$ in \autoref{DEF: profinite completion}, is thus a profinite group. 

\subsection{Residual finiteness}
There is a canonical homomorphism.
$$\begin{aligned}
\iota_G: \; G&\longrightarrow \widehat{G}\\
g&\longmapsto (gN)_{N\lhd_{f.i.} G}
\end{aligned}
$$
It is easy to see that $\iota_G$ is injective if and only if $G$ is residually finite. Thus, in the following context, when $G$ is residually finite, we always identify $G$ as its image in $\widehat{G}$, and elements in $G$ are also viewed as elements in $\widehat{G}$. 

Hempel's theorem for residual finiteness \cite{Hem87}, together with the virtual Haken theorem \cite{Ago13}, yields the following result.

\begin{proposition}\label{PROP: RF}
The fundamental group of any compact 3-manifold is residually finite.
\end{proposition}

\subsection{The completion fuctor}
The profinite completion is functorial. Any homomorphism of abstract group $f: G_1\to G_2$ induces a continuous homomorphism  $\widehat{f}:\widehat{G_1}\to \widehat{G_2}$ so that the following diagram commutes.
%
\begin{equation*}
\begin{tikzcd}
G_1 \arrow[r, "f"] \arrow[d,"\iota_{G_1}"'] & G_2 \arrow[d,"\iota_{G_2}"] \\
\widehat{G_1} \arrow[r, "\widehat{f}"]   & \widehat{G_2}           
\end{tikzcd}
\end{equation*}

For any two finitely generated groups $G_1$ and $G_2$, the theorem of Nikolov-Segal \cite{NS03} implies that any isomorphism between $\widehat{G_1}$ and $\widehat{G_2}$ as abstract groups is indeed an isomorphism as profinte groups, that is, additionally a homeomorphism. Thus, we shall not emphasize on the continuity of isomorphisms between profinite completions of finitely generated groups in the following context.%, as we are mainly concerning finitely generated groups. 

The completion functor is right exact.
\begin{proposition}[{\cite[Proposition 3.2.5]{RZ10}}]\label{PROP: Completion Exact}
%\begin{enumerate}
%\item 
Given a short exact sequence of abstract groups
\begin{equation*}
\centering
\begin{tikzcd}
1 \arrow[r] & K \arrow[r, "\varphi"] & G \arrow[r, "\psi"] & L \arrow[r] & 1,
\end{tikzcd}
\end{equation*}
there is an exact sequence of profinite groups
\begin{equation*}
\centering
\begin{tikzcd}
\widehat K \arrow[r, "\widehat \varphi"] & \widehat G \arrow[r, "\widehat \psi"] & \widehat L \arrow[r] & 1.
\end{tikzcd}
\end{equation*}
\end{proposition}

However, the profinite completion may not preserve injectiveness.

\begin{proposition}[{\cite[Lemma 3.2.6]{RZ10}}]\label{PROP: Left exact}
%\item\label{mono2} 
Suppose $f:H\to G$ is an injective homomorphism of abstract groups. Then $\widehat{f}:\widehat{H}\to \widehat{G}$ is injective if and only if \textit{the profinite topology on $G$ induces the full profinite topology on $H$}, that is, for any finite-index subgroup $M\le H$, there exists a finite-index subgroup $N\le G$ such that $f^{-1}(N)\subseteq M$.
%\end{enumerate}
\end{proposition}

