For a discrete group $G$, let $\ab{G}=G/[G,G]$ denote its abelianization; and for a profinite group $\Pi$, let $\Ab{\Pi}=\Pi/\overline{[\Pi,\Pi]}$ denote its profinite abelianization. When $G$ is finitely generated, the profinite abelianization of $\widehat{G}$ is related to the abelianization of $G$ by the following proposition.

\begin{proposition}[{\cite[Proposition 2.11]{Xu24a}}]\label{PROP: abelianization}
Let $G$ be a finitely generated group, then there are natural isomorphisms $\tensor \ab{G} \cong \widehat{\ab{G}}\cong \Ab{\widehat{G}}$ such that the following diagram commutes.
\begin{equation*}
\begin{tikzcd}
G \arrow[r, two heads] \arrow[d, "\iota_G"'] & \ab{G} \arrow[r, hook] & \tensor \ab{G} \arrow[d, "\cong"]    \\
\widehat{G} \arrow[r, two heads]             & \Ab{\widehat{G}}       & \widehat{\ab{G}} \arrow[l, "\cong"']
\end{tikzcd}
\end{equation*}
\end{proposition}

\begin{corollary}\label{COR: abelianization}
Let $G$ and $H$ be finitely generated groups, and let $f:\widehat{G}\to \widehat{H}$ be a continuous homomorphism. Then $f$ induces a homomorphism of $\widehat{\Z}$-modules
$$
f_\ast: \;\tensor \ab{G}\cong \Ab{\widehat{G}}\tto \Ab{\widehat{H}}\cong \tensor \ab{H}.
$$
\end{corollary}

\begin{corollary}[{\cite[Remark 3.2]{Reid:2018}}]\label{COR: b1}
Suppose $G$ and $H$ are finitely generated groups and $\widehat{G}\cong \widehat{H}$. Then $\ab{G}\cong \ab{H}$, and in particular, $b_1(G)=b_1(H)$. 
\end{corollary}


Liu \cite{Liu23} first introduced and proved the notion of $\Zx$-regularity, an intermediate towards regularity, in profinite isomorphisms between finite-volume hyperbolic 3-manifolds, including both closed and cusped cases.

\begin{definition}\label{DEF: Zx-regular}
Let $G$ and $H$ be finitely generated groups\iffalse such that $b_1(G)=b_1(H)>0$\fi. Suppose $f:\widehat{G}\to\widehat{H}$ is a continuous homomorphism. We say that $f$ is {\em $\Zx$-regular} if the induced map
$$
f_\ast: \;\tensor \ab{G} \cong \Ab{\widehat{G}}\tto \Ab{\widehat{H}}\cong \tensor \ab{H}
$$
splits as $\lambda\otimes \phi$, where $\lambda\in \Zx$ and $\phi: \ab{G}\to \ab{H}$ is a homomorphism of abelian groups.  To specify the coefficient in $\Zx$, we say that in this case $f$ is {\em $\lambda$-regular}. 
\end{definition}

%Comparing definition \com{tba} with \autoref{DEF: Zx-regular}, 
Comparing the definitions, $f$ is regular (in the sense of \autoref{introdef: Zx regular}) is equivalent to say $f$ is $1$-regular (in the sense of \autoref{DEF: Zx-regular}). 


For an abstract abelian group $A$, let $A_{\mathrm{tor}}$ denote its torsion subgroup, and let $A_{\mathrm{free}}=A/A_{\mathrm{tor}}$. According to \cite[Lemma 2.9]{Xu24a}, for a finitely generated abelian group $A$, $(\widehat{A})_{\mathrm{tor}}\cong \tensor A_{\mathrm{tor}}\cong A_{\mathrm{tor}}$ within the canonical isomorphism in  \autoref{PROP: abelianization}. Thus, the homomorphism $f_\ast: \tensor \ab{G}\to \tensor \ab{H}$ in \autoref{COR: abelianization} descends to the free part
$$
{(f_\ast)}_{\mathrm{free}}:\; \tensor \ab{G}_{\mathrm{free}}\tto \tensor \ab{H}_{\mathrm{free}}.
$$

We point out that the $\Zx$-regularity of $f$ only depends on the free part of the abelianizations.
\begin{lemma}\label{LEM: free part}
For finitely generated groups $G$ and $H$, a continuous homomorphism $f:\widehat{G}\to\widehat{H}$ is $\lambda$-regular if and only if the induced map
$$
{(f_\ast)}_{\mathrm{free}}:\; \tensor \ab{G}_{\mathrm{free}}\tto \tensor \ab{H}_{\mathrm{free}}
$$
splits as $\lambda\otimes \phi_{\mathrm{free}}$ for some homomorphism $\phi_{\mathrm{free}}: \ab{G}_{\mathrm{free}}\to \ab{H}_{\mathrm{free}}$.
\end{lemma}
\begin{proof}
The ``only if'' part is clear. In fact, if $f_\ast: \tensor \ab{G} \to \tensor \ab{H}$ splits as $\lambda \otimes \phi$, then $\phi:\ab{G}\to \ab{H}$ naturally descends to $\phi_{\mathrm{free}}: \ab{G}_{\mathrm{free}}\to \ab{H}_{\mathrm{free}}$, and $(f_\ast)_{\mathrm{free}}= \lambda\otimes \phi_{\mathrm{free}}$.

We now prove the ``if'' part. Suppose $(f_\ast)_{\mathrm{free}}=\lambda\otimes \phi_{\mathrm{free}}$. Then there is the following commutative diagram 
\begin{equation*}
\begin{tikzcd}
                                                                            & \tensor \ab{G} \arrow[dd, "p", two heads] \arrow[rrr, "\lambda^{-1}\circ f_\ast"]                                        &  &                                         & \tensor \ab{H} \arrow[dd, "q", two heads] \\
\ab{G} \arrow[dd, two heads] \arrow[ru, hook]                               &                                                                                                                          &  &                                         &                                           \\
                                                                            & \tensor \ab{G}_{\mathrm{free}} \arrow[rrr, "\lambda^{-1}\circ (f_{\ast})_{\mathrm{free}}=1\otimes \phi_{\mathrm{free}}"] &  &                                         & \tensor \ab{H}_{\mathrm{free}}            \\
\ab{G}_{\mathrm{free}} \arrow[ru, hook] \arrow[rrr, "\phi_{\mathrm{free}}"] &                                                                                                                          &  & \ab{H}_{\mathrm{free}} \arrow[ru, hook] &                                          
\end{tikzcd}
\end{equation*}
where $\lambda^{-1}$ denotes the scalar multiplication by $\lambda^{-1}$ in $\tensor \ab{H}$ or $\tensor \ab{H}_{\mathrm{free}}$.

Consequently, $(\lambda^{-1}\circ f_\ast)(\ab{G})\subseteq q^{-1}(\ab{H}_{\mathrm{free}})$. $\ab{H}$ injects into $\tensor \ab{H}$ as an abelian subgroup. We claim that $q^{-1}(\ab{H}_{\mathrm{free}})= \ab{H}$. On one hand, it is clear that $q(\ab{H})= \ab{H}_{\mathrm{free}}$. On the other hand, since $\widehat{\Z}$ is torsion-free, $\widehat{\Z}$ is a flat $\Z$-module, and  $\ker(q)=\tensor \ab{H}_{\mathrm{tor}}=\ab{H}_{\mathrm{tor}}$. Thus, $\ker(q)\subseteq \ab{H}$. Therefore, $q^{-1}(\ab{H}_{\mathrm{free}})= \ab{H}$, so $(\lambda^{-1}\circ f_\ast)(\ab{G})\subseteq \ab{H}$. We rename this map as $\phi=\lambda^{-1}\circ f_\ast : \ab{G}\to \ab{H}$, which is a homomorphism of abelian groups. Then, $f_\ast=\lambda\otimes\phi$ and $f$ is $\lambda$-regular. 
\end{proof}

