For brevity of notation, we abbreviate the results of \autoref{THM: Zx regular}, \autoref{PROP: respect peripheral structure}, \autoref{THM: peripheral Zx regular} and \autoref{samecoef} into the following setting, and conventionally fix the use of the letters therein from \autoref{sec:4} through \autoref{SEC: Dehn filling}.
\begin{convention}\label{conv+}
A {\em cusped hyperbolic setting of profinite isomorphism} $(M,N,f,\lambda,\Psi)$ consists of the following ingredients.
\begin{enumerate}[leftmargin=*]
\item $M$ and $N$ are finite-volume hyperbolic 3-manifolds with $n>0$ cusps denoted as $\partial_1M,\cdots,\partial_nM$ and $\partial_1N,\cdots,\partial_nM$ respectively.
\item $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is an isomorphism which is $\lambda$-regular.
\item $P_1,\cdots, P_n$ are peripheral subgroups of $\pi_1M$ and $Q_1,\cdots, Q_n$ are peripheral subgroups of $\pi_1N$, such that $f(\overline{P_i})=\overline{Q_i}^{g_i}$ for certain fixed elements $g_1,\cdots, g_n\in \widehat{\pi_1N}$.
\item For $1\le i \le n$, denote $\partial f_i= C_{g_i}\circ f|_{\overline{P_i}}: \widehat{P_i}\to \widehat{Q_i}$, which uniquely decomposes as $\partial f_i=\lambda \otimes \psi_i$ for some isomorphism $\psi_i: P_i\to Q_i$.
\item Let $\Psi:\partial M\to \partial N$ be the unqiue homeomorphism up to isotopy that induces $\psi_1,\cdots,\psi_n$. In other words, $\Psi(\partial_iM)=\partial_iN$ and $(\Psi|_{\partial_iM})_\ast=\psi_i:P_i\cong \pi_1\partial_iM\to \pi_1\partial_iN\cong Q_i$.
\end{enumerate}
\end{convention}

