\subsection{The profinite completion}
The relative (co)homology of a discrete group pair and the relative profinite (co)homology of its profinite completion can be  related by the following proposition.
\begin{proposition}\label{PROP: completion induce LES}
Let $(G,\mathcal{H}=\{H_i\}_{i=1}^{n})$ be a discrete group pair. Let $\overline{H_i}$ be the closure of the image of $H_i$ in $\widehat{G}$ through the canonical homomorphism $\iota:G\to \widehat{G}$, and let $\overline{\mathcal{H}}=\{\overline{H_i}\}_{i=1}^{n}$. Then $(\widehat{G},\overline{\mathcal{H}})$ is a profinite group pair. 
\begin{enumerate}[leftmargin=*]
\item\label{ciLES1} For $M\in\mathfrak{C}(\widehat{G})=\mathfrak{C}(\widehat{\Z}\szkh{\widehat{G}})$, $M$ can be viewed as a $\widehat{\Z}[G]$-module, and there is a natural homomorphism $H_\ast(G,\mathcal{H};M)\to \H_\ast(\widehat{G},\overline{\mathcal{H}};M)$ of $\widehat{\Z}$-modules induced by $\iota$ such that the following diagram commutes. 
\begin{equation*}
\begin{tikzcd}[column sep=0.3cm]
\cdots \arrow[r] & {H_{k+1}(G,\mathcal{H};M)} \arrow[d, "\iota_\ast"] \arrow[r, "\partial"] & \mathop{\oplus}\limits_{i=1}^{n} H_k(H_i;M) \arrow[r] \arrow[d, "(\iota|_{H_i})_\ast"] & H_k(G;M) \arrow[r] \arrow[d, "\iota_\ast"] & {H_{k}(G,\mathcal{H};M)} \arrow[r, "\partial"] \arrow[d, "\iota_\ast"] & \cdots \\
\cdots \arrow[r] & {\H_{k+1}(\widehat{G},\overline{\mathcal{H}};M)} \arrow[r, "\partial"]   & \mathop{\oplus}\limits_{i=1}^{n} \H_k(\overline{H_i};M) \arrow[r]                      & \H_k(\widehat{G};M) \arrow[r]              & {\H_{k}(\widehat{G},\overline{\mathcal{H}};M)} \arrow[r, "\partial"]   & \cdots
\end{tikzcd}
\end{equation*}
\item For   $A\in \mathfrak{D}(\widehat{\Z}\szkh{\widehat{G}})$, $A$ can be viewed as a $\widehat{\Z}[G]$-module, and there is a natural homomorphism $\H^\ast(\widehat{G},\overline{\mathcal{H}};A)\to H^\ast(G,\mathcal{H};A)$ of $\widehat{\Z}$-modules induced by $\iota$ such that the following diagram commutes. 
\begin{equation*}
\begin{tikzcd}[column sep=0.33cm]
\cdots \arrow[r] & {\H^{k}(\widehat{G},\overline{\mathcal{H}};A)} \arrow[r] \arrow[d, "\iota^\ast"] & \H^k(\widehat{G};A) \arrow[r] \arrow[d, "\iota^\ast"] & \mathop{\oplus}\limits_{i=1}^{n} \H^k(\overline{H_i};A) \arrow[r] \arrow[d, "(\iota|_{H_i})^\ast"] & {\H^{k+1}(\widehat{G},\overline{\mathcal{H}};A)} \arrow[d, "\iota^\ast"] \arrow[r] & \cdots \\
\cdots \arrow[r] & {H^{k}(G,\mathcal{H};A)} \arrow[r]                                               & H^k(G;A) \arrow[r]                                    & \mathop{\oplus}\limits_{i=1}^{n} H^k(H_i;A) \arrow[r]                                              & {H^{k+1}(G,\mathcal{H};A)} \arrow[r]                                               & \cdots
\end{tikzcd}
\end{equation*}
\end{enumerate}
\end{proposition}
\begin{proof}
These are induced by the following commutative diagram of short exact sequences of $G$-modules, see \cite[Section 6.1]{Wil19}.
\begin{equation*}
\begin{tikzcd}
0 \arrow[r] & {\Delta_{G,\mathcal{H}}} \arrow[d, "\iota_\ast"] \arrow[r] & {\mathop{\oplus}\limits_{i=1}^{n}\Z[{G/H_i}]} \arrow[d, "\iota_\ast"] \arrow[r]      & {\Z} \arrow[d,hook] \arrow[r] & 0 \\
0 \arrow[r] & {\DELTA_{\widehat{G},\overline{\mathcal{H}}}} \arrow[r]    & \mathop{\oplus}\limits_{i=1}^{n}\widehat{\Z}\szkh{\widehat{G}/\overline{H_i}} \arrow[r] & \widehat{\Z} \arrow[r]                 & 0       
\end{tikzcd}%\qedhere
\end{equation*}
\end{proof}

The homomorphism $\iota_\ast$ in \autoref{PROP: completion induce LES}~(\ref{ciLES1}) is also natural with respect to the group pairs, as shown by the following proposition.
\begin{proposition}\label{PROP: completion induce natural}
Let  $(G,\mathcal{H}=\{H_i\}_{i=1}^{n})$ and $(G',\mathcal{H}'=\{H_i'\}_{i=1}^{n})$ be  discrete group pairs. Suppose $\varphi: (G,\mathcal{H}) \to (G',\mathcal{H}')$ is a map of discrete group pairs, that is, $\varphi:G\to G'$ is a group homomorphism such that $\varphi(H_i)\subseteq H_i'$. Then $\widehat{\varphi} : (\widehat{G},\overline{\mathcal{H}})\to (\widehat{G'},\overline{\mathcal{H}'})$ is a map of profinite group pairs, and for any $M\in \mathfrak{C}(\widehat{G'})$, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}
{H_\ast(G,\mathcal{H};M)} \arrow[r, "\varphi_\ast"] \arrow[d, "\iota_\ast"]         & {H_\ast(G',\mathcal{H}';M)} \arrow[d, "\iota'_\ast"] \\
{\H_\ast(\widehat{G},\overline{\mathcal{H}};M)} \arrow[r, "\widehat{\varphi}_\ast"] & {\H_\ast(\widehat{G'},\overline{\mathcal{H}'};M)}   
\end{tikzcd}
\end{equation*}
\end{proposition}
\begin{proof}
This follows from the commutative diagram 
\begin{equation*}
\begin{tikzcd}[column sep=small, row sep=small]
{\Delta_{G,\mathcal{H}}} \arrow[dd, "\iota_\ast"] \arrow[rr, hook] \arrow[rd, "\varphi_\ast"]       &                                                                       & {\mathop{\oplus}\limits_{i=1}^{n} \Z[G/H_i]} \arrow[dd, "\iota_\ast"{yshift=-1.5ex}] \arrow[rd, "\varphi_\ast"]                 &                                                                               \\
                                                                                                    & {\Delta_{G',\mathcal{H}'}} \arrow[dd, "\iota'_\ast"{yshift=-1.5ex}] \arrow[rr, hook] &                                                                                                                  & {\mathop{\oplus}\limits_{i=1}^{n} \Z[G'/H_i']} \arrow[dd, "\iota'_\ast"]      \\
{\DELTA_{\widehat{G},\overline{\mathcal{H}}}} \arrow[rr, hook] \arrow[rd, "\widehat{\varphi}_\ast"'] &                                                                       & \mathop{\oplus}\limits_{i=1}^{n} \widehat{\Z}\szkh{\widehat{G}/\overline{H_i}} \arrow[rd, "\widehat{\varphi}_\ast"'] &                                                                               \\
                                                                                                    & {\DELTA_{\widehat{G'},\overline{\mathcal{H}'}}} \arrow[rr, hook]      &                                                                                                                  & \mathop{\oplus}\limits_{i=1}^{n} \widehat{\Z}\szkh{\widehat{G'}/\overline{H_i'}}
\end{tikzcd}
\end{equation*}

In fact, $\varphi_\ast: H_\ast(G,\mathcal{H};M)\to H_\ast(G',\mathcal{H'};M)$ is induced by $\varphi_\ast: \Delta_{G,\mathcal{H}}\to \Delta_{G',\mathcal{H}'}$, and $\widehat{\varphi}_\ast$ is induced by $\widehat{\varphi}_\ast: \DELTA_{\widehat{G},\overline{\mathcal{H}}}\to \DELTA_{\widehat{G'},\overline{\mathcal{H}'}}$ according to \autoref{PROP: LES}.
\end{proof}

\subsection{Cohomological goodness}

Cohomological goodness was first defined by Serre in \cite{Ser01}, which can also be generalized to the relative version. 

For a discrete group $G$, let $\mathfrak{F}(G)$ denote the category of finite $G$-modules. It is easy to see that $\mathfrak{F}(G)=\mathfrak{F}(\widehat{G})$. 
\begin{definition}
\begin{enumerate}[leftmargin=*]
\item A discrete group $G$ is {\em cohomologically good}  (in the sense of Serre) \iffalse (or {\em cohomologically good} for short)\fi if for any $A\in \mathfrak{F}(G)=\mathfrak{F}(\widehat{G})$, the map $\iota^\ast: \H^\ast( \widehat{G};A)\to H^\ast(G;A)$ is an isomorphism. 
\item A discrete group pair $(G,\mathcal{H})$ is {\em cohomologically good} if for any $A\in \mathfrak{F}(G)=\mathfrak{F}(\widehat{G})$, the map  $\iota^\ast: \H^\ast( \widehat{G},\overline{\mathcal{H}};A)\to H^\ast(G,\mathcal{H};A)$ is an isomorphism.
\end{enumerate}
\end{definition}

\begin{example}\label{EX: good}
The following groups are cohomologically good.
\begin{enumerate}[leftmargin=*]
\item Finite groups.
\item Finitely generated abelian groups, \cite[p. 16, Exercise 2]{Ser01}.
\item Finitely generated free groups and surface groups, \cite[Proposition 3.6]{GJZ08}.
\item Finitely generated 3-manifold groups, \cite[Theorem 3.5.1 and Lemma 3.7.1]{Cav12}.
\end{enumerate}
\end{example}


%The cohomological goodness of a discrete group pair can be deduced from the cohomological goodness of the groups, according to the following proposition.
A combination of \autoref{PROP: Left exact} and \cite[Proposition 6.3]{Wil19} yields the following proposition, which passes the cohomological goodness from groups to a group pair.

\begin{proposition}\label{PROP: pair goodness}%[\com{cite Wilkes Proposition 6.3}]
Let $(G,\mathcal{H}=\{H_i\}_{i=1}^{n})$ be a discrete group pair. Suppose that $G$ is cohomologically good, each $H_i$ is cohomologically good, and the profinite topology on $G$ induces the   full profinite topology on each $H_i$. Then the discrete group pair $(G,\mathcal{H})$ is  cohomologically good.
\end{proposition}

The cohomological goodness can be transformed into the homological version by Pontryagin duality.

\begin{definition}
A discrete group $G$ is of {\em type $\text{FP}_{\infty}$} if the $G$-module $\Z$ is of type $\text{FP}_{\infty}$. A discrete group pair $(G,\mathcal{H})$ is of {\em type $\text{FP}_{\infty}$} if the $G$-module $\Delta_{G,\mathcal{H}}$ is of type $\text{FP}_{\infty}$.
\end{definition}

\begin{proposition}[{\cite[Proposition 6.2]{Wil19}}]\label{PROP: homology good}
\begin{enumerate}[leftmargin=*]
\item Suppose $G$ is a cohomologically good discrete group   of type $\text{FP}_{\infty}$. Then for any $M\in \mathfrak{F}(G)=\mathfrak{F}(\widehat{G})$, the map  $\iota_\ast: H_\ast(G ;M)\to \H_\ast (\widehat{G};M)$ is an isomorphism.
\item Suppose $(G,\mathcal{H})$ is a cohomologically good discrete group pair of type $\text{FP}_{\infty}$. Then for any $M\in \mathfrak{F}(G)=\mathfrak{F}(\widehat{G})$, the map  $\iota_\ast: H_\ast (G,\mathcal{H};M)\to \H_\ast(\widehat{G},\overline{\mathcal{H}};M)$ is an isomorphism.
\end{enumerate}
\end{proposition}

\begin{convention}
In the remaining part of this article, $\Z$ or $\widehat{\Z}$ appearing as coefficient modules of a certain (relative) (profinite) homology is assumed to have trivial action by the group unless otherwise stated. 
\end{convention}


\begin{proposition}\label{PROP: good tensor hatZ}
\begin{enumerate}[leftmargin=*]
\item\label{good tensor 1} Let $G$ be a cohomologically good discrete group of type $\text{FP}_{\infty}$\iffalse, and let $\widehat{\Z}$ be the $\widehat{G}$-module with trivial $\widehat{G}$-action\fi . Then, there are isomorphisms of $\widehat{\Z}$-modules $$\tensor H_\ast(G;\Z) \xrightarrow{\;\;\cong\;\;} H_\ast (G;\widehat{\Z}) \xrightarrow[\iota_\ast]{\;\;\cong\;\;} \H_\ast(\widehat{G};\widehat{\Z}).$$
\item\label{good tensor 2} Let $(G,\mathcal{H})$ be a cohomologically good discrete group pair of type $\text{FP}_{\infty}$\iffalse, and let $\widehat{\Z}$ be the $\widehat{G}$-module with trivial $\widehat{G}$-action\fi. Then, there are isomorphisms of $\widehat{\Z}$-modules $$\tensor H_\ast(G,\mathcal{H};\Z) \xrightarrow{\;\;\cong\;\;} H_\ast(G,\mathcal{H};\widehat{\Z})\xrightarrow[\iota_\ast]{\;\;\cong\;\;}  \H_\ast(\widehat{G},\overline{\mathcal{H}};\widehat{\Z}).$$
\end{enumerate}
\end{proposition}
\begin{proof}
We only prove part (\ref{good tensor 2}), and the proof for part (\ref{good tensor 1}) is similar. The first isomorphism follows from the universal coefficient theorem. Since $\widehat{\Z}$ has trivial $G$-action, there is a short exact sequence $$0\to \tensor H_\ast(G,\mathcal{H};\Z)  \to H_\ast(G,\mathcal{H};\widehat{\Z}) \to \mathrm{Tor}^{\Z}_1 ( \widehat{\Z}, H_{\ast-1}(G,\mathcal{H};\widehat{\Z}))\to 0,$$ see \cite[p. 60, Exercise 3]{Bro82}. $\widehat{\Z}$ is torsion-free, and is hence a flat $\Z$-module. Thus, $\mathrm{Tor}^{\Z}_1 ( \widehat{\Z}, H_{\ast-1}(G,\mathcal{H};\widehat{\Z}))=0$, which implies the first isomorphism. 

Moving on to the second isomorphism, we first deal with the profinite side. For $n\in \mathbb{N}$, let $\Z/n! $ be the finite $\widehat{G}$-module with trivial $\widehat{G}$-action, and the quotient maps $\Z/(n+1)! \to \Z/n! $ are also homomorphisms of $\widehat{G}$-modules. Then in $\mathfrak{C}(\widehat{G})$, we still have $\widehat{\Z}= \limi_n \Z/n! $. The functor $\Tor_\ast^{\widehat{G}}$ commutes with inverse limits \cite[Corollary 6.1.10]{RZ10}, so there is an isomorphism
\iffalse
\newsavebox{\torinverse}
\begin{lrbox}{\torinverse}
\(
\H_\ast(\widehat{G},\overline{\mathcal{H}};\widehat{\Z})=\Tor_{\ast-1}^{\widehat{G}}(\DELTA_{\widehat{G},\overline{\mathcal{H}}}^{\perp},\widehat{\Z})\xrightarrow{\;\cong\;}  \limi\limits_n \Tor_{\ast-1}^{\widehat{G}}(\DELTA_{\widehat{G},\overline{\mathcal{H}}}^{\perp},\Z/n!) =\limi\limits_n \H_\ast(\widehat{G},\overline{\mathcal{H}};\Z/n!).
\)
\end{lrbox}
\begin{center}
\scalebox{0.93}{\usebox{\torinverse}}
\end{center}
\fi
\begin{equation*}
\H_\ast(\widehat{G},\overline{\mathcal{H}};\widehat{\Z})=\Tor_{\ast-1}^{\widehat{G}}(\DELTA_{\widehat{G},\overline{\mathcal{H}}}^{\perp},\widehat{\Z})\xrightarrow{\;\cong\;}  \limi\limits_{n \to \infty} \Tor_{\ast-1}^{\widehat{G}}(\DELTA_{\widehat{G},\overline{\mathcal{H}}}^{\perp},\Z/n!) =\limi\limits_{n \to \infty} \H_\ast(\widehat{G},\overline{\mathcal{H}};\Z/n!).
\end{equation*}

As for the discrete side, the relative homology of a group pair may not, in general, commute with the inverse limit  taken in the coefficient modules. However, in this specific case, we show that 
\begin{equation}\label{tensor hatZ equ1}
H_\ast(G,\mathcal{H};\widehat{\Z})\tto \limi\limits_{n \to \infty} H_\ast(G,\mathcal{H};\Z/n!)
\end{equation}
is an isomorphism.

Since $(G,\mathcal{H})$ is of type $\text{FP}_\infty$, by \cite[Chapter VIII, Proposition 4.5]{Bro82}, we can take a free resolution $F_\bullet\to \Delta_{G,\mathcal{H}}^\perp \to 0$ of finite type in the category of right $\Z[G]$-modules. Let $C^n_\bullet=F_\bullet \otimes_{\Z[G]} \Z/n!$. Then,  $C^0_\bullet\leftarrow C^1_\bullet \leftarrow C^2_\bullet \leftarrow \cdots$ is a tower of chain complexes of abelian groups. 
%In particular, $C^n_k\cong (\Z/n!)^{\oplus r_k}$, where $F_k= \Z[G]^{\oplus r_k}$. 
Note that $\Z/(n+1)!\to \Z/n!$ is surjective and the tensor product $F_k\otimes_{\Z[G]} -$ is right exact, so $C^{n+1}_k \to C^n_k$ is surjective for any $n,k\in \mathbb{N}$. Consequently, the tower  $C^0_\bullet\leftarrow C^1_\bullet  \leftarrow \cdots$ satisfies degree-wise the Mittag-Leffler condition. Then, according to \cite[Theorem 3.5.8]{Wei94}, there is a short exact sequence 
$$
0\to {\limi\limits_n}^1 H_{\ast+1} (C^n_{\bullet})\to H_\ast (\limi\limits_n C^n_\bullet) \to \limi\limits_n H_\ast (C^n_\bullet)\to 0.
$$

%Let us examine each term in this short exact sequence. 
By construction $H_\ast (C^n_\bullet)= \mathrm{Tor}_{\ast}^G(\Delta^\perp_{G,\mathcal{H}}, \Z/n!)= H_{\ast+1}(G,\mathcal{H};\Z/n!)$. Note that $C^n_k\cong (\Z/n!)^{\oplus r_k}$, where $F_k= \Z[G]^{\oplus r_k}$. Thus, $\limi_n C^n_k\cong \widehat{\Z}^{\oplus r_k}\cong F_k\otimes_{\Z[G]} \widehat{\Z}$, and $H_\ast(\limi_n C^n_\bullet)\cong H_\ast(F_\bullet \otimes_{\Z[G]} \widehat{\Z})=\mathrm{Tor}_\ast^G(\Delta^\perp_{G,\mathcal{H}}, \widehat{\Z})= H_{\ast+1}(G,\mathcal{H};\widehat{\Z})$. Thus, we actually have a short exact sequence
$$
0\to {\limi\limits_n}^1 H_{\ast} (C^n_{\bullet})\to H_{\ast}(G,\mathcal{H};\widehat{\Z}) \xrightarrow{\;\phi\;} \limi\limits_n H_{\ast}(G,\mathcal{H};\Z/n!)\to 0.
$$
The map $\phi$ is exactly the one in (\ref{tensor hatZ equ1}), since it is induced by the maps between the coefficient modules $\widehat{\Z}\to \Z/n!$.

Note that for each $n,k\in \mathbb{N}$, $C^n_k\cong (\Z/n!)^{\oplus r_k}$ is finite, so $H_k(C^n_\bullet)$ is also finite. As a consequence, the tower of abelian groups $H_k(C^n_\bullet)$ satisfies the Mittag-Leffler condition, and $\limi^1_n H_k (C^n_\bullet)=0$ according to \cite[Proposition 3.5.7]{Wei94}. Therefore, the map $\phi$ is indeed an isomorphism. 

%Moreover, 
We can now relate the two sides. 
Since $(G,\mathcal{H})$ is cohomologically good and of type $\text{FP}_\infty$, \autoref{PROP: homology good} implies that for $n\in \mathbb{N}$, the map $\iota_\ast: H_\ast(G,\mathcal{H};\Z/n!) \to \H_\ast (\widehat{G},\overline{\mathcal{H}};\Z/n!)$ is an  isomorphism. In addition, these isomorphisms are natural with respect to the coefficient modules $\Z/n!$. Thus, we have a commutative diagram of abelian groups
\begin{equation*}
\begin{tikzcd}
{H_\ast(G,\mathcal{H};\widehat{\Z})} \arrow[d, "\cong"',"\phi"] \arrow[r, "\iota_\ast"] & {\H_\ast(\widehat{G},\overline{\mathcal{H}};\widehat{\Z})} \arrow[d, "\cong"] \\
{\limi\limits_n H_\ast(G,\mathcal{H};\Z/n!)} \arrow[r, "\cong"',"\iota_\ast"]                  & {\limi\limits_n \H_\ast(\widehat{G},\overline{\mathcal{H}};\Z/n!)}           
\end{tikzcd}
\end{equation*}
where the two vertical maps and the bottom map are all proven to be isomorphisms. Thus, $\iota_\ast: {H_\ast(G,\mathcal{H};\widehat{\Z})} \to  {\H_\ast(\widehat{G},\overline{\mathcal{H}};\widehat{\Z})}$  is also an isomorphism (of abelian groups). Note that $\iota_\ast$ is obviously a homomorphism of $\widehat{\Z}$-modules, so the proof completes.
\end{proof}


