\section{Calculation by Dehn filling}\label{SEC: Dehn filling}

In this section we prove the second relation between the profinite mapping degree and the homology coefficient for a profinite isomorphism between cusped hyperbolic 3-manifolds. The method is to apply the Dehn filling construction established in \cite{Xu24b} so as to pass the calculation to a profinite isomorphism between closed  hyperbolic manifolds, and then deduce  the relation according to \autoref{PROP: closed relation}.

\subsection{Dehn filling}
\def\R{\mathbb{R}}
Let us first specify our notions for Dehn fillings. Let $M$ be a compact   3-manifold with non-empty boundary consisting of tori $\partial_1M, \cdots, \partial_n M$. The {\em slopes} on $\partial_i M$ is denoted as 
\iffalse
$$
\slope(\partial_iM)=\left.\left\{\alpha \in \pi_1(\partial_iM)\left|\,\begin{gathered} \alpha \text{ is a non-zero primitive element in}\\ \text{the free abelian group }\pi_1(\partial_iM)\cong \Z^2\end{gathered}\right.\right\}\right /\alpha\sim -\alpha.
$$ 
\fi
$$
\slope(\partial_iM)= \{\text{free homotopy classes of  unoriented essential simple closed curves on }\partial_iM\cong T^2\}
$$
which is equipped with discrete topology. Indeed, an element in $\slope(\partial_iM)$ can be viewed as (a $\pm$-pair of) primitive integral points in $H_1(\partial_iM;\R)\cong \R^2$. The one-point compactification of $\slope(\partial_iM)$ is denoted as $\slp(\partial_iM)=\slope(\partial_iM)\cup\{\infty\}$. In fact, $\slp(\partial_iM)$ can be viewed as a subset of $\overline{\R^2}/(x\sim -x)\cong S^2/\sim\cong S^2$. For simplicity of notation, we denote $\slope(\partial M)=\slope(\partial_1M)\times \cdots \times \slope(\partial _nM)$ and $\slp(\partial M)= \slp(\partial_1M)\times \cdots \times \slp(\partial_nM)$. 

\def\c{\mathbf{c}}

\begin{definition}
Let $M$ be a compact   3-manifold with non-empty boundary consisting of $n$ tori. For $\c=(c_1,\cdots, c_n)\in \slp(\partial M)$, {\em the Dehn filling of $M$ along $\c$}, denoted by $M_{\c}$, is a compact 3-manifold constructed from $M$ as follows. For each $1\le i\le n$, if $c_i\neq \infty$, we glue a solid torus to the boundary component $\partial_i M$ so that the meridian of the solid torus is attached to $c_i$; if $c_i=\infty$, we do nothing and skip this boundary component. 
\end{definition}





The key result in \cite{Xu24b} is that a profinite isomorphic pair of orientable cusped hyperbolic 3-manifolds carries profinite isomorphisms between their  Dehn fillings. For the application in the following subsections, let us succinctly explain this result. We first introduce a notation. 

\def\ccc{\langle \!\langle \c\rangle\!\rangle}


\begin{definition}
Let $M$ be a compact 3-manifold with non-empty boundary consisting of $n$ tori. Let $\c=(c_1, \cdots, c_n)\in \slp(\partial M)$. For each $1\le i\le n$ such that $c_i\neq \infty$, we choose a conjugacy representative $\gamma_i\in \pi_1M$ that represents the free homotopy class $c_i$. We define a subgroup $\langle \!\langle \c\rangle\!\rangle \lhd \pi_1M$ to be the normal subgroup generated by the elements $\gamma_i$ for $1\le i\le n$ such that $c_i\neq \infty$. 
\end{definition}

\begin{lemma}[{\cite[Lemma 3.5]{Xu24b}}]\label{LEM: van Kampen}
Let $M$ be a compact 3-manifold with non-empty boundary consisting of tori, and let $\c\in \slp(\partial M)$. Let $p:\pi_1M \to \pi_1M_{\c}$ be the homomorphisms induced by inclusion.
\begin{enumerate}[leftmargin=*]
\item $p$ is surjective, and $\ker(p)=\ccc$.
\item $\widehat{p} : \pi_1M \to \pi_1M_{\c} $ is also surjective, and $\ker(\widehat{p})= \overline{\ccc}$. 
\end{enumerate}
\end{lemma}
\begin{proof}
(1) is a direct application of van-Kampen's theorem. Thus, we have a short exact sequence 
$$
1\to \ccc\hookrightarrow  \pi_1M\xrightarrow{p} \pi_1M_{\c}\to 1.
$$
Then, \autoref{PROP: Completion Exact} implies the following  exact sequence
$$
 \widehat{\ccc}\tto \widehat{\pi_1M}\xrightarrow{\;\,\widehat{p}\;\,} \widehat{\pi_1M_{\c}} \tto 1.
$$
In particular, $\widehat{p}$ is surjective, and the kernel of $\widehat{p}$ is the image of $ \widehat{\ccc}$ in $\widehat{\pi_1M}$, which is exactly $\overline{\ccc}$. This finishes the proof of (2). 
\end{proof}

\begin{theorem}[{\cite[Theorem A]{Xu24b}}]\label{THM: Dehn filling}
Let $(M,N,f, \lambda,\Psi)$ be a cusped hyperbolic setting of profinite isomorphisms (\autoref{conv+}). For any $\c\in \slp(\partial M)$, we have $\Psi(\c)\in \slp(\partial N)$. Let $p:\pi_1M \to \pi_1M_{\c}$ and $q:\pi_1N\to \pi_1N_{\c}$ be the homomorphisms induced by inclusions. Then there exists an isomorphism $\fdf{c}:\widehat{\pi_1M_{\c}}\to \widehat{\pi_1N_{\Psi(\c)}}$ such that the following diagram commutes.
\begin{equation}\label{dehnfillingequ}
\begin{tikzcd}[column sep=large]
\widehat{\pi_1M}\arrow[d,"\widehat{p}"',two heads] \arrow[r,"f","\cong"'] & \widehat{\pi_1N} \arrow[d,"\widehat{q}", two heads]\\
\widehat{\pi_1M_{\c}} \arrow[r,"\fdf{c}","\cong"'] & \widehat{\pi_1N_{\Psi({\c})}}
\end{tikzcd}
\end{equation}
\end{theorem}
\begin{proof}
By \autoref{LEM: van Kampen}, it suffices to show that $f(\ker(\widehat{p}))= \ker(\widehat{q})$, or in other words, $f(\overline{\ccc})=\overline{\langle \! \langle \Psi(c) \rangle \! \rangle }$. For $1\le i\le n$ such that $c_i\neq  \infty$, we pick a representative $\gamma_i \in P_i$ that represents $c_i$. Then, $\psi_i(\gamma_i)\in Q_i\le \pi_1N $ is a conjugacy representative that represents  $\Psi(c_i)$. Within \autoref{conv+}, we  have $f(\gamma_i)= g_i^{-1} \psi_i(\gamma_i)^\lambda g_i$. Therefore,
\begin{align*}
f(\overline{\ccc})&= f(\overline{\langle \! \langle \gamma_i : c_i\neq \infty \rangle \! \rangle}) = \overline{\langle \! \langle f(\gamma_i) : c_i\neq \infty \rangle \! \rangle} = \overline{\langle \! \langle g_i^{-1} \psi_i(\gamma_i)^\lambda g_i : c_i\neq \infty \rangle \! \rangle} \\ &=\overline{\langle \! \langle   \psi_i(\gamma_i)^\lambda   : c_i\neq \infty \rangle \! \rangle} =\overline{\langle \! \langle   \psi_i(\gamma_i)   : c_i\neq \infty \rangle \! \rangle} =\overline{\langle \! \langle \Psi(c) \rangle \! \rangle }
\end{align*}
since $\lambda\in \Zx$, which finishes the proof. 
\end{proof}




