Suppose $M$ and $N$ are compact, irreducible 3-manifolds with empty or incompressible toral boundary which are not closed $Sol$-manifolds. Let $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ be an isomomrphism. Then $f$ induces a {congruent isomorphism} between graphs of profinite groups
$$
f_{\bullet}\;: (\widehat{\mathcal{G}^M},\Gamma^M)\xrightarrow{\;\;\cong\;\;} (\widehat{\mathcal{G}^N},\Gamma^N)
$$
consisting of the following ingredients. 
\begin{enumerate}[leftmargin=*]
\item With $\Gamma^M$ and $\Gamma^N$ equipped with appropriate orientations, $\F:\Gamma^M\to \Gamma^N$ is an isomorphism of oriented graphs. 
\item For each $x\in \Gamma^M=V(\Gamma^M)\cup E(\Gamma^M)$, $f_x: \widehat{G^M_{x}}\to \widehat{G^N_{\F(x)}}$ is an isomorphism that fits into the following commutative diagram.
\begin{equation}\label{congruentdiag1}
\begin{tikzcd}
\widehat{G^M_x} \arrow[rr, hook] \arrow[d, "f_x"'] &                                       & \widehat{\pi_1M} \arrow[d, "f"] \\
\widehat{G^N_{\F(x)}} \arrow[r, hook]              & \widehat{\pi_1N} \arrow[r, "C_{g_x}","\cong"'] & \widehat{\pi_1N}               
\end{tikzcd}
\end{equation}
\item For each $e\in E(\Gamma^M)$ there is a coherence relation shown by the following commutative diagram
\begin{equation}\label{butterfly}
\scalebox{0.94}{\usebox{\butterfly}}
\end{equation}
where $\varphi_\pm$ and $\psi_{\pm}$ denote  the gluing maps.
\end{enumerate}
\end{theorem}  

Some useful properties within this congruent isomorphism are listed as follows. 

\begin{lemma}\label{LEM: JSJ}
Follow the setting of \autoref{THM: JSJ}.
\begin{enumerate}[leftmargin=*]
\item\label{lem1} For $v\in V(\Gamma^M)$, $M_v\cap \partial M=\varnothing$ if and only if $N_{\F(v)}\cap \partial N=\varnothing$.
\item\label{lem2} For $v\in V(\Gamma^M)$, $M_v$ is hyperbolic (resp. Seifert fibered) if and only if $N_{\F(v)}$ is hyperbolic (resp. Seifert fibered).
\item\label{lem3} Following the notation in the commutative diagram (\ref{butterfly}), $f_{\partial_-(e)}$ is peripheral $\lambda$-regular at $\partial_iM_{\partial_-(e)}$ if and only if $f_{\partial_+(e)}$ is peripheral $\lambda$-regular at $\partial_kM_{\partial_+(e)}$. Here, by $f_{\partial_-(e)}$ being peripheral $\lambda$-regular at $\partial_iM_{\partial_-(e)}$, we mean that $\partial f_{\partial_-(e)}$ is $\lambda$-regular. 
\item\label{lem4} $f$ respects the peripheral structure if and only if all $f_v$ ($v\in V(\Gamma^M)$) respect  the peripheral structure.
\end{enumerate}
\end{lemma}
\begin{proof}
(\ref{lem2}) is proven by \cite{WZ17,WZ17b}, see also \cite[Theorem 4.18 and 4.20]{Reid:2018}. (\ref{lem3}) is proven in \cite[Lemma 6.11]{Xu24a}, and (\ref{lem4}) is proven in \cite[Theorem 5.6 (2)]{Xu24a}.

We now prove (\ref{lem1}). For each $v\in V(\Gamma^M)$, let $\partial^{\mathcal{T}}M_v=\partial^{\mathcal{T}}_1M_v\cups \partial^{\mathcal{T}}_kM_v$ be the boundary components given by the JSJ-tori, where $k$ is the degree of $v$ in $\Gamma^M$.  Similarly, let $\partial^{\mathcal{T}}N_{\F(v)}=\partial^{\mathcal{T}}_1N_{\F(v)}\cups \partial^{\mathcal{T}}_kN_{\F(v)}$ be the boundary components given by the JSJ-tori. Then, up to a reordering of indices, the coherence relation (\ref{butterfly}) implies that 
$$f_v: (\widehat{\pi_1M_v},\{\overline{\pi_1\partial^{\mathcal{T}}_iM_v}\}_{i=1}^{k}) \tto (\widehat{\pi_1N_{\F(v)}},\{\overline{\pi_1\partial^{\mathcal{T}}_iN_{\F(v)}}^{h_i}\}_{i=1}^{k})$$
is an isomorphism of profinite group pairs, where $h_1,\cdots, h_k\in \widehat{\pi_1N_{\F(v)}}$ are some elements that induces the conjugation. 
Thus, by \autoref{PROP: conjugation invariant},
$$
\H_3(\widehat{\pi_1M_v},\{\overline{\pi_1\partial^{\mathcal{T}}_iM_v}\}_{i=1}^{k};\widehat{\Z})\cong \H_3(\widehat{\pi_1N_{\F(v)}},\{\overline{\pi_1\partial^{\mathcal{T}}_iN_{\F(v)}}\}_{i=1}^{k};\widehat{\Z}).
$$

Moreover, according to \autoref{COR: 3mfd with surface},
$$
\H_3(\widehat{\pi_1M_v},\{\overline{\pi_1\partial^{\mathcal{T}}_iM_v}\}_{i=1}^{k};\widehat{\Z}) \cong \tensor H_3(M_v,\partial^{\mathcal{T}}M_v;\Z)
$$
and
$$
\H_3(\widehat{\pi_1N_{\F(v)}},\{\overline{\pi_1\partial^{\mathcal{T}}_iN_{\F(v)}}\}_{i=1}^{k};\widehat{\Z})\cong  \tensor H_3(N_{\F(v)},\partial^{\mathcal{T}}N_{\F(v)};\Z).
$$
Since $H_3(M_v,\partial^{\mathcal{T}}M_v;\Z)$ and $H_3(N_{\F(v)},\partial^{\mathcal{T}}N_{\F(v)};\Z)$ are finitely generated, we derive that
$$
H_3(M_v,\partial^{\mathcal{T}}M_v;\Z)\cong H_3(N_{\F(v)},\partial^{\mathcal{T}}N_{\F(v)};\Z).
$$
Note that $M_v\cap \partial M=\varnothing$ if and only if $H_3(M_v,\partial^{\mathcal{T}}M_v;\Z)\cong \Z$ and $N_{\F(v)}\cap \partial N=\varnothing$ if and only if $ H_3(N_{\F(v)},\partial^{\mathcal{T}}N_{\F(v)};\Z)\cong \Z$. So this finishes the proof of (\ref{lem1}).
\end{proof}






\subsection{Profinite isomorphism between Seifert fibered spaces}

In this subsection, we shall only consider Seifert fibered spaces with non-empty boundary which are not $S^1\times D^2$, $S^1\times S^1\times I$, or the orientable $I$-bundle over Klein bottle. To simplify notation, the Seifert fibered spaces being considered are called {\em major Seifert fibered spaces}, following the notation of Wilkes \cite{Wil17,Wil18}. 

Any profinite isomorphism $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$  between major Seifert fibered spaces that respects the peripheral structure  has a well-defined scale type $(\pm\lambda,\pm \mu)\in (\Zx/\{\pm1\})^2$. In fact, fixing a Seifert presentation of the fundamental group $\pi_1M$, we can find  a positively oriented $\Z$-basis $(h^M,e_i^M)$ for each peripheral subgroup $\pi_1\partial_iM$ such that $h^M$ represents the regular fiber, and $e_i^M$ represents the peripheral cross-section. We use the similar notation for $N$. We remind the readers that the regular fibers $h^M$ and $h^N$ generate infinite cyclic normal subgroups in $\pi_1M$ and $\pi_1N$, and  profinite isomorphisms between major Seifert fibered spaces always preserve the closure of the fiber subgroup according to \cite[Theorem 5.5]{Wil17}. The scale type $(\pm\lambda,\pm \mu)$ is defined such that
\begin{equation}\label{scaletypeequ}
C_{g_i}\circ  f\begin{pmatrix}  h^M & e_i^M \end{pmatrix}= \begin{pmatrix}  h^N & e_i^N \end{pmatrix} \begin{pmatrix} o(g_i)\lambda & o(g_i)\rho_i \\ 0 &  o(g_i)\mu\end{pmatrix}
\end{equation}
where $o:\widehat{\pi_1N}\to \widehat{\pi_1^{\text{orb}}\O_N}\to \{\pm1\}$ is the orientation homomorphism when the base orbifold $\O_N$ is non-orientable, and  $o(g)=1$ when the base orbifold $\O_N$ is orientable. 
Note that $\lambda$ and $\mu$ are unified when varying between boundary components. We refer the readers to \cite{Wil17,Wil18} and \cite[Section 8]{Xu24a} for details.

\begin{lemma}[{\cite[Lemma 9.3]{Xu24a}}]\label{LEM: gluing Seifert}
Follow the setting of \autoref{THM: JSJ} and the notation in diagram (\ref{butterfly}). Suppose $e\in E(\Gamma^M)$ such that both $M_{\partial_-(e)}$ and $M_{\partial_+(e)}$ are Seifert fibered, and both $f_{\partial_-(e)}$ and $f_{\partial_+(e)}$ respects the peripheral structure.
\begin{enumerate}[leftmargin=*]
\item\label{sl1} If $f_{\partial_-(e)}$ has scale type $(\pm\lambda, \pm\mu)$, then $f_{\partial_+(e)}$ has scale type $(\pm\mu, \pm\lambda)$.
\item\label{sl2} If $f_{\partial_-(e)}$ has scale type $(\pm\lambda, \pm\lambda)$, then $f_{\partial_-(e)}$ is peripheral $\lambda$-regular at $\partial_iM_{\partial_-(e)}$ and $f_{\partial_+(e)}$ is peripheral $\lambda$-regular at $\partial_kM_{\partial_+(e)}$.
\end{enumerate}
\end{lemma}


\begin{lemma}\label{LEM: Seifert last one}
Let $M$ and $N$ be Seifert fibered spaces each containing at least two boundary components. Label the boundary components of $M$ as $\partial_1M,\cdots, \partial _n M$ ($n\ge 2$). Suppose $f:\widehat{\pi_1M}\to \widehat{\pi_1N}$ is an isomorphism that respects the peripheral structure, and $f$ is peripheral $\lambda$-regular at $\partial_1M,\cdots,\partial_{n-1}M$. 
Then, $M$ is homeomorphic to $N$, and $f$ is also peripheral $\lambda$-regular at $\partial_nM$.
%Then $f$ is also peripheral $\lambda$-regular at $\partial_nM$.
\end{lemma}
\begin{proof}
The fact that $M$ is homeomorphic to $N$ follows from \cite[Proposition 8.20]{Xu24a}. As a result, one can choose the same Seifert presentation for $\pi_1M$ and $\pi_1N$, which defines the $\Z$-bases $(h^M,e_i^M)$ and $(h^N,e_i^N)$ for the peripheral subgroups in $\pi_1M$ and $\pi_1N$. %We remind the readers that the regular fibers $h^M$ and $h^N$ generate infinite cyclic normal subgroups in $\pi_1M$ and $\pi_1N$. 
In this case, the scale type of $f$ is $(\pm\lambda,\pm\lambda)$. By a careful choice of the orientations, we can assume that
$$
C_{g_i}\circ  f\begin{pmatrix}  h^M & e_i^M \end{pmatrix}= \begin{pmatrix}  h^N & e_i^N \end{pmatrix} \begin{pmatrix} o(g_i)\lambda & o(g_i)\rho_i \\ 0 &  o(g_i)\lambda\end{pmatrix}
$$
\iffalse
where $\rho_i\in\widehat{\Z}$, \com{see}. Here, $o:\widehat{\pi_1N}\to \widehat{\pi_1^{\text{orb}}\O_N}\to \{\pm1\}$ is the orientation homomorphism when the base orbifold $\O_N$ is non-orientable, and  $o(g)=1$ when the base orbifold $\O_N$ is orientable. 
\fi

Since $f$ is peripheral $\lambda$-regular at $\partial_1M,\cdots,\partial_{n-1}M$, we have $\rho_1,\cdots, \rho_{n-1}\in \lambda\Z$. In addition, since we are starting from the same Seifert presentation, \cite[Lemma 8.16]{Xu24a} implies that 
$$
\sum_{i=1}^{n} \rho_i=0.
$$
Therefore, $\rho_n\in \lambda\Z$, and $f$ is peripheral $\lambda$-regular at $\partial_nM$. 
%By \com{Wilkes}, $M$ and $N$ have isomorphic base orbifolds. We first consider the case that $M$ and $N$ have orientable base orbifolds
\end{proof}


\subsection{The mixed case}
In this subsection, we finish the proof of \autoref{THM: Mixed peripheral}. 
\begin{proof}[Proof of \autoref{THM: Mixed peripheral}]
Let $f_{\bullet}:(\widehat{\mathcal{G}^M},\Gamma^M)\to (\widehat{\mathcal{G}^N},\Gamma^N)$ be the congruent isomorphism induced by $f$ given in \autoref{THM: JSJ}. Then, by \autoref{LEM: JSJ}~(\ref{lem4}), for any $v\in V(\Gamma^K)$, $f_v$ respects the peripheral structure. 

We claim that for any $v\in V(\Gamma^K)$ such that $M_v$ is Seifert fibered, the scale type of $f_v$ is $(\pm1,\pm1)$. First, we consider an arbitrary Seifert fiberd piece $M_v$ adjacent to a hyperbolic piece $M_u$. Then, according to \autoref{mainthm: regular}, $f_u$ is peripheral regular at the boundary component corresponding to their common JSJ-torus, and  \autoref{LEM: JSJ}~(\ref{lem3}) implies that $f_v$ is also peripheral regular at this corresponding boundary component. Thus, by definition in (\ref{scaletypeequ}), $f_u$ has scale type $(\pm1,\pm1)$. Next,  we consider a Seifert fiberd piece $M_v$ not adjoint to a hyperbolic piece. Then there exists a finite sequence of edges in $\Gamma^M$ with Seifert fibered endpoints that connects $v$ to a Seifert fibered vertex $w$ which is adjacent to a hyperbolic piece. We have shown that $f_w$ has scale type $(\pm1,\pm1)$, so by repeated applying \autoref{LEM: gluing Seifert}~(\ref{sl1}) along this path, we derive that $f_v$ also has scale type $(\pm1,\pm1)$. 

Now we prove the peripheral regularity. Suppose $\partial_iM$ is a boundary component of $M$ belonging to the JSJ-piece $M_v$. According to the commutative diagram (\ref{congruentdiag1}), in order to show that $f$ is peripheral regular at $\partial_iM$, it suffices to show that $f_v$ is peripheral regular at $\partial_iM$. When $M_v$ is a hyperbolic piece, this follows directly from \autoref{mainthm: regular}. When $M_v$ is a Seifert fibered piece, by assumption, all other boundary components of $M_v$ are given by the JSJ-tori. Since $f_v$ has scale type $(\pm1,\pm1)$, \autoref{LEM: gluing Seifert}~(\ref{sl2}) implies that $f_v$ is peripheral regular at all boundary components given by JSJ-tori. Thus, it follows from  \autoref{LEM: Seifert last one} that $f_v$ is also peripheral regular at the only remaining boundary component $\partial_iM$, which finishes the proof. 
\end{proof}





