\begin{proposition}[{\cite[Proposition 4.2]{CL96}}]\label{PROP: A-polynomial reverse}
Reversing the orientation of $K$ does not change $A_K$ and $\widetilde{A}_K$. However, reversing the orientation of the ambient space $S^3$ changes $A_K$; to be precise, $\widetilde{A}_{\overline{K}}(M,L)\doteq \widetilde{A}_{K}(M^{-1},L)$ where $\overline{K}$ is the mirror image of $K$,
\end{proposition}

