\begin{proposition}\label{THM: rep matchup}
Let $(\!(M,N,f)\!)$ be a standard peripheral regular setting (\autoref{convsprs}), and let $n\in \mathbb{N}$. Given any representation $\theta: \pi_1N\to \SL(n,\C)$, there exists a representation $\phi:\pi_1M\to \SL(n,\C)$ such that for each $1\le i \le k$, the two representations
\begin{equation*}
\begin{gathered}
\phi_i: \pi_1\partial_iM\hookrightarrow \pi_1 M \xrightarrow{\phi} \SL(n,\C) \quad \text{and}\quad 
\psi_i^{\ast}\theta_i: \pi_1\partial_iM \xrightarrow{\psi_i}\pi_1\partial_iN \hookrightarrow \pi_1N \xrightarrow{\theta} \SL(n,\C)
\end{gathered}
\end{equation*}
are equivalent (by conjugation in $\SL(n,\C)$). 
%
Moreover, when $\theta$ is non-abelian (resp. irreducible),  $\phi$ is also non-abelian (resp. irreducible).
\end{proposition}
\begin{proof}
According to  \autoref{LEM: extend}, there exists a field isomorphism $\varsigma: \overline{\Q_p}\to \C$ such that $\theta$ extends to a representation 
\begin{equation*}
\begin{tikzcd}
