\end{tikzcd}
\end{equation*}
Let $\Phi=\Theta\circ f: \widehat{\pi_1M}\to \SL(n,\Q_p)$, which is continuous, and let 
\begin{equation*}
\begin{tikzcd}
\phi:\;\pi_1M \arrow[r,hook] & \widehat{\pi_1M} \arrow[rr,"\Phi=\Theta\circ f","\text{(continuous)}"'] &  & \SL(n,\overline{\Q_p}) \arrow[r,"\varsigma_\ast","\cong"']& \SL(n,\C).
\end{tikzcd}
\end{equation*}
\iffalse
