                                                                       &                                                                   &  &  &  &  &             \\
                                                                       & \widehat{\pi_1M} \arrow[dd, "f"',"\cong"] \arrow[rrrrrd, "\Phi=\Theta\circ f"']    &  &  &  &  &             \\
                                                                       &                                                                   &  &  &  &  & {\SL(2,\C)} \\
                                                                       & \widehat{\pi_1N} \arrow[rrrrru, "\Theta "] &  &  &  &  &             \\
                                                                       &                                                                   &  &  &  &  &             \\
\pi_1N \arrow[ruu, "\iffalse\iota_K\fi", hook] \arrow[rrrrrruuu, "\theta"'] &                                                                   &  &  &  &  &            
