{\section{}\label{AppA}}
Without loss of generality, we assign generator 1 as the slack generator. Solving the power balance equation via
\begin{align}
p_{g,1}=1^{T}\left(p_{d}+\delta\right)-\hat{1}^{T}\hat{p}_{g},
\end{align}
the generation limit and flow limit inequalities are given as
\begin{align}
\underline{p}_{f}\leq\hat{\Phi}\hat{p}_{g}-\Phi\left(p_{d}+\delta\right) & \leq\overline{p}_{f}\\
\underline{p}_{g}\leq\left[\begin{array}{c}
1^{T}\left(p_{d}+\delta\right)-\hat{1}^{T}\hat{p}_{g}\\
\hat{p}_{g}
\end{array}\right] & \leq\overline{p}_{g}.
\end{align}
Thus, the following compact inequality can be formulated:
\begin{align}
\underbrace{\left[\!\!\begin{array}{c}
\hat{\Phi}\\
-\hat{\Phi}\\
-\hat{1}^{T}\\
I\\
\hat{1}^{T}\\
-I
\end{array}\!\!\right]}_{A}p+\underbrace{\left[\begin{array}{c}
-\Phi\\
\Phi\\
1^{T}\\
0\\
-1^{T}\\
0
\end{array}\right]}_{B}\delta+\underbrace{\left[\!\!\begin{array}{c}
-\Phi p_{d}-\overline{p}_{f}\\
\underline{p}_{f}+\Phi p_{d}\\
\left[\!\!\begin{array}{c}
1^{T}p_{d}\\
0
\end{array}\!\!\right]-\overline{p}_{g}\\
\underline{p}_{g}-\left[\!\!\begin{array}{c}
1^{T}p_{d}\\
0
\end{array}\!\!\right]
\end{array}\!\!\right]}_{b}\le0.
\end{align}
To simplify paper notation, we have defined $p\triangleq \hat{p}_g$ as the reduced generation vector. We note that $\hat{\Phi}\hat{p}_{g}$ and ${\Phi}{p}_{g}$ are equivalent, since slack generator injections do not explicitly alter network flows. Finally, if load perturbations or generators are only present at subsets of buses, we can introduce matrices, $N_g$ and $N_d$, which map load and generation to their respective buses via, e.g., $\Phi N_gp_{g}$ and $\Phi N_dp_{d}$. Such mapping matrices are used in the numerical test results sections.



{\section{}\label{AppB}}
Taking the Lagrange dual of \eqref{eq: quad_proj} yields
\begin{align}
\max_{\lambda}\min_{\delta}\;\delta^{T}\delta+\lambda\left(a_{i}^{T}p_0+b_{i}^{T}\delta+c_{i}\right).
\end{align}
Applying stationarity conditions to the primal, via $\frac{\partial\mathcal{L}}{\partial\delta}=2\delta+\lambda b_{i}=0$ yields a solution $\delta=-\frac{1}{2}\lambda b_{i}$. Plugging this back into the Lagrangian yields
\begin{align}
\max_{\lambda}\;-\frac{1}{4}\lambda^{2}b_{i}^{T}b_{i}+\lambda\left(a_{i}^{T}p_0+c_{i}\right).
\end{align}
Again applying stationarity conditions, via $\frac{\partial\mathcal{L}}{\partial\lambda}=-\frac{1}{2}\lambda b_{i}^{T}b_{i}+a_{i}^{T}p_0+c_{i}=0$, yields a solution for $\lambda$:
\begin{align}
\lambda=2\frac{a_{i}^{T}p_0+c_{i}}{b_{i}^{T}b_{i}}.
\end{align}
Plugging this solution into $\delta=-\frac{1}{2}\lambda b_{i}$ yields
\begin{align}
\delta^{(i)}_{\rm lb}=-\frac{\left(a_{i}^{T}p_0+c_{i}\right)}{b_{i}^{T}b_{i}}b_{i}.
\end{align}
%\will{Was it obvious a priori that $\delta_{\rm lb}^{i}$ is a projection of $a_i^Tp_0 + c_i$ onto $b_i$? If it's obvious, maybe we should mention it. If not, ... is it interesting?}
Finally, we may take the inner product of $\delta^{(i)}_{\rm lb}$ with itself to compute the size of the perturbation: 
\begin{align}\label{eq: pi_solution}
(\delta^{(i)}_{\rm lb})^T\delta^{(i)}_{\rm lb}=\frac{\left(a_{i}^{T}p_0+c_{i}\right)^{2}}{b_{i}^{T}b_{i}}.
\end{align}
We may directly extend this solution to account for inclusion of the parameterized control policy $G$ in \eqref{eq: p_control}:
\begin{align}\label{eq: ld_gp}
\max_{\lambda}\min_{\delta}\;\delta^{T}\delta+\lambda\left(a_{i}^{T}p_{0}+\left(a_{i}^{T}G+b_{i}^{T}\right)\delta+c_{i}\right).
\end{align}
Its solution is given by substituting into \eqref{eq: pi_solution}
\begin{align}
\delta^{(i)}_{\rm lb}=-\frac{\left(a_{i}^{T}p_0+c_{i}\right)}{\left(G^{T}a_{i}+b_{i}\right)^{T}\left(G^{T}a_{i}+b_{i}\right)}\left(G^{T}a_{i}+b_{i}\right).
\end{align}
We may take the inner product of $\delta^{(i)}_{\rm lb}$ with itself to compute the size of this perturbation: 
\begin{align}\label{eq: param_pert_size}
\bigl\Vert \delta_{{\rm lb}}^{(i)}\bigr\Vert _{2}^{2}=\frac{\left(a_{i}^{T}p_0+c_{i}\right)^{2}}{\left(G^{T}a_{i}+b_{i}\right)^{T}\left(G^{T}a_{i}+b_{i}\right)}.
\end{align}

{\section{}\label{AppC}}
For a general linear program with feasibility constraints
\begin{subequations}\label{eq: f1a}
\begin{align}
Ax+b & =0\\
Cx+d & \le0,
\end{align}
\end{subequations}
Farkas' lemma offers an alternative system of equations
\begin{subequations}\label{eq: f2a}
\begin{align}
\lambda^{T}A+\mu^{T}C & =0\\
\lambda^{T}b+\mu^{T}d & >0\\
\mu  &\ge 0.
\end{align}
\end{subequations}
Either \eqref{eq: f1a} or \eqref{eq: f2a} is satisfiable, but never both.

{\section{}\label{AppD}}
\textbf{Example 1:} \textit{Rank-1 Control Policy. }Assuming a uniform distributed slack model, injection perturbations ($p-p_0$) are mapped to nodal generator responses via 
\begin{align}
\Phi\left(p+1\frac{1^{T}(p-p_{0})}{n}\right)=\underbrace{\Phi\left(I+\frac{11^{T}}{n}\right)}_{\text{rank-1 PTDF update}}p-\underbrace{\Phi\frac{11^{T}}{n}p_{0}}_{\rm bias}.
\end{align}
Thus, distributed slack implicitly applies a rank-1 update to the PTDF matrix. \hfill $\qed$

