%
% Figure: Source spectrum
%
\begin{figure}[h]
  \begin{centering}
    \includegraphics[width=1.0\textwidth,
    keepaspectratio, height=0.9\textheight]{f1_spectrum_forcing2.pdf}
    \caption{(a) Gravity wave spectrum at the source level  represented by a Gaussian distribution of horizontal momentum fluxes as a function of horizontal phase speeds on 2 June 2020, 0000 UT at 50$^\circ$N, 0$^\circ$ longitude (Greenwich Meridian). The source spectrum is asymmetric since it takes into account the local mean winds ($u_s =3.8$ m~s$^{-1}$ at this location and time). Panel (b) shows the associated momentum forcing (in m~s$^{-2}$) required to generate the spectrum in (a).} 
    \label{fig:spectrum_figure}
  \end{centering}
\end{figure}


%
%%% Background atmosphere at 75N
%
\begin{figure}[h!]
  \includegraphics[width=1\textwidth,
  keepaspectratio, height=0.9\textheight]{f2_background_atm_2June_lat75_v02.pdf}
  \caption{The background atmosphere as simulated by the CMAT2 GCM at a representative location and time: Latitude $\theta =75^\circ$N, longitude $\phi = 0^\circ$ (Greenwich Meridian), 2 June 2020, 0000 UT. (a) Background horizontal wind components, (b) neutral temperature $T$, (c) pressure scale height $H$. In (a), $u $ and $v$ denote the zonal and meridional components of the horizontal wind velocity $\mathbf{u}$, and $u_a $ is the  projection of the upper level horizontal winds on the direction of wave propagation, which coincides with the wind direction at the launch height.}
  \label{fig:background-wind}
\end{figure}


%
%% Figure 3:  c=+80 column model
%
\begin{figure}[h!]
  \centering
  \hspace*{-1.3cm}
  \includegraphics[width=1.2\textwidth]{f3_single_harmonic_c-80_v02.pdf}
  \caption{Instantaneous column model results for  the incident test harmonic $c_i = 80$ m~s$^{-1}$ on 2 June 2020 0000 UT, taking into account nonlinear interactions with a broad spectrum of waves, at a representative grid point  ($\theta = 75^\circ$, $\phi = 0^\circ$): (a) gravity wave variance $\overline{u^{\prime 2}}$ (black) and horizontal momentum flux $\overline{u^\prime w^\prime}$ (blue) in m$^{-2}$~s$^{-2}$; the  wave flux per unit mass in case of conservative propagation (red dotted) is added. (b) Background density variation relative to the source level density $\rho_0$, which is representative of the wave growth; (c) total gravity wave dissipation rate $\beta$; (d) gravity wave transmissivity $\tau$; (e) zonal gravity wave drag $a_x$ in m~s$^{-1}$~day$^{-1}$. The incident gravity wave spectrum is the same as in Figure \ref{fig:spectrum_figure} with the maximum source flux of $\overline{u^\prime w^\prime}_{max} = 3 \times 10^{-4}$~m$^{-2}$~s$^{-2}$ and the characteristic horizontal wavelength $\lambda_h = 300$ km. The source  flux associated with the test harmonic is $\overline{u^\prime w^\prime}_i (z_0) \approx 0.329 \times 10^{-5}$ m$^2$~s$^{-2}$. Extra-tropospheric sources are not included.} 
    \label{fig:column_model-c-80}
  \end{figure}

%
%%% Figure 4: Mean fields and differences
%
\begin{figure}[t!]
    \centering
    \vspace{-1.4cm}
    \hspace*{-1cm}
    \includegraphics[width=1.1\linewidth]{f4_mean_fields_all_pres_v02.pdf}
    \caption{Pressure-latitude distributions of the  fields simulated with CMAT2 for the Northern Hemisphere summer solstice conditions: (a) Neutral temperature $T$, (b) zonal wind $u$, (c) meridional wind $v$. The fields are averaged longitudinally and temporally between June 6 and July 5. Shown are the simulations including only the tropospheric sources (EXP0), with added localized sources at 90 km (EXP1) and 50 km (EXP2), and with sources distributed over all heights (EXP3). Solid and dashed lines for the zonal and meridional winds represent eastward/northward and westward/southward directions, respectively. The differences between the runs EXP1--EXP3 and the benchmark EXP0 are shown in color shading. The differences for the zonal and meridional use the same color scale. The mean geopotential height is shown on the right.}
    \label{fig:mean_fields_all_pres}
\end{figure}

