\section{Introduction}

In this paper, we study the Boltzmann equation
\begin{align*}
    \partial_t F + v \cdot \nabla_x F = Q(F,F), \quad F(0,x,v)=F_0(x,v),\quad t \geq 0, \,\, x\in \O, \,\, v\in\R^{3},
\end{align*} 
where $F(t,x,v) \geq 0$ is probability density function which describes behavior of rarefied gas particles. Here, $t$ is time, $x$ is position variable in domain $\O$, and $v$ is velocity variable in $\R^{3}$. The Boltzmann equation describes evolution of the density function $F$ taking elastic binary collision $Q(F,F)$ into account. Explicitly, quadratic nonlinear colllisional operator $Q(F,F)$ is defined by 
\begin{align*} 
    Q(F,F)(t,x,v)&:= \int_{\mathbb{R}^{3}} \int_{\mathbb{S}^{2}_{+}} B(v-u,\omega)  \left(F(t,x,u')F(t,x,v')-F(t,x,u)F(t,x,v)\right)   d\omega du\\
    &:=Q_{gain}(F,F)(t,x,v)-Q_{loss}(F,F)(t,x,v),
\end{align*} 
where $B(v-u,\omega)$ is collision kernel, and post collisional velocities $u'$ and $v'$ are written as
\begin{align*} 
	u'=u+\left((v-u)\cdot\omega\right) \omega, \text{\quad and \quad} v'=v-\left((v-u)\cdot\omega\right) \omega,\quad \omega\in \S^{2}_{+}.
\end{align*} 

For cutoff type Boltzmann equation, collision kernel $B(v-u,\omega)$ is defined by 
\[
	B(v-u,\omega)= |v-u|^{\gamma}b(\cos\theta),\quad -3 < \gamma \leq 1,\quad 0 \leq b(\cos\theta) \leq C|\cos\theta|,
\]
where $\cos\theta := \frac{(v-u)\cdot \o}{|v-u|}$. In this paper, we deal with hard sphere model $B(v-u,\omega)=|(v-u)\cdot \omega|$. \\

When it comes to boundary, we are interested in exterior domain of uniform convex object.
\begin{definition}\label{def:domain}
	Let $\Omega = \mathbb{R}^3 \setminus \overline{\mathcal{O}}$ be the exterior domain of a uniformly convex, bounded open set $\mathcal{O} \subset \mathbb{R}^3$, where $\mathcal{O}= \{x \in \R^3: \xi(x)>0\}$ for a sufficiently smooth function $\xi(x)$. Additionally, there exists a constant $\theta_{\O} >0$ such that 
	\begin{align}\label{convex_xi}
\zeta \cdot(- \nabla^2 \xi(x))   \zeta	:=  \sum_{i,j=1}^3  (-\p_{ij} \xi(x)) \zeta_i\zeta_j \geq \theta_{\O} |\zeta|^2 \text{\quad for \quad} \zeta \in \R^3,
	\end{align}
	which means that $\mathcal{O}$ is a uniformly convex object. In other words, $\O = \{x \in \R^3: \xi(x)<0 \}$ with $\xi$ of \eqref{convex_xi}. We define the boundary of the domain
    \begin{align*}
        \partial\O  :=\overline{\mathcal{O}}  \backslash \mathcal{O}= \{x \in \R^3: \xi(x)=0 \}, 
        \quad \bO := \O \cup \partial\O,
    \end{align*} 
   a unit normal vector 
	\begin{align*}
	    n(x) :=  \frac{\nabla \xi (x)}{|\nabla \xi(x)|} \text{\quad for \quad}  x \in \partial \O,
	\end{align*}
    and the distance to the boundary
    \[
    	d(x,\partial\O) := \min_{y \in \partial \O}|x-y| \text{\quad for \quad}  x \in  \bO.
    \]

	\end{definition} 

    We impose specular reflection boundary condition on the boundary $\p\O$,
	\begin{equation*}
		F(t,x,v) = F(t,x,R_{x}v) \  \textit{ for } x\in\p\O, \  \textit{ where } \ R_x v := \left(I - 2n (x)\otimes n(x)\right)v,
	\end{equation*} 
	where $R_{x}$ is reflection operator on $x\in \p\O$.  \\

	If $F$ has sufficiently fast decay in large $|v|$, it is well-known that $Q(F,F)=0$ is obtained when $F$ is a local Maxwellian
	\[
		F(t,x,v) = \frac{\rho(t,x)}{\sqrt{2\pi T(t,x)}^3} e^{-\frac{|v-U(t,x)|^2}{2T(t,x)}}
	\]
	where macroscopic quantities $\rho$, $U$, and $T$ are defined by 
	\[
		\rho = \int_{v} F dv,\quad \rho U = \int_{v}vF dv,\quad 3\rho T = \int_{v}|v-U|^2 F dv.
	\]
	When the macroscopic quantities are independent to time and position, the local Maxwellian is a uniform Gaussian function of $v$ and called global Maxwellian. In this paper, we use $\mu$ to denote  $\mu(v) := e^{- \frac{ |v|^2}{2} }$. We rewrite the Boltzmann equation with the specular reflection boundary condition in terms of scaled density function $f(t,x,v) := F(t,x,v)/\sqrt{\mu}(v)$. Then $f$ solves
\begin{align}
& \p_{t}f + v\cdot \nabla_{x} f := \Gamma_{\text{gain}}(f,f) - \nu(f) f ,  
\ \ 
f|_{t=0} =f_0,  \label{f_eqtn} \\
& f(t,x,v)  = f(t,x,R_{x}v), \quad x\in \p\O, 
\label{specular}
\end{align}
where
\begin{align*}
&\Gamma_{\text{gain}}(f,f) = \frac{1}{\sqrt{\mu}(v)}Q_{\text{gain}}(\sqrt{\mu}f,\sqrt{\mu}f),\\
&\nu(f) = \int_{\R^3}\int_{\mathbb{S}^{2}_{+}} |(v-u)\cdot\omega| \sqrt{\mu}(u) f(t,x,u) d\omega du. 
\end{align*}

To define mild formulation, let us define characteristic. Backward exit time and position is defined by 
 	\begin{equation} \notag % \label{backward_exit}
 	\begin{split}
 	\tb(x,v)   &:=  \sup \big\{  s \geq 0 :  x-\tau v  \in \O  \ \ \text{for all}  \ \tau \in ( 0, s )  \big\}, \quad t_{1}(t,x,v) := t-\tb(x,v),  \\
 	\xb(x,v)   &:=  x- \tb( x,v) v \in \partial\O.  
 	\end{split}
 	\end{equation}
 	If $x-\tau v \in \O$ for all $\tau\in \R$, i.e., backward in time trajectory from $(x,v)$ does not intersect with $\p\O$, we define $\tb(x,v)=\infty$ and $t_1(t,x,v)=-\infty$. \\

 	In the case of $\O$, the domain is uniformly concave and billiard trajectory undergoes only one bounce on $\p\O$ at most. Therefore, we define billiard trajectory $(X(s;t,x,v), V(s;t,x,v))$ as 
 	\begin{align*}
 		\begin{split}
 			&(X(s;t,x,v), V(s;t,x,v)) \mathbf{1}_{\{\tb(x,v) < \infty\}} \\
 			&= \begin{cases} (x-(t-s) v, v)  
 				\ \ \text{for} \ \ s \in (t-\tb(x,v),t]
 				\\
 				(\xb(x,v) - (t-\tb(x,v) - s) R_{\xb(x,v)} v, R_{\xb(x,v)} v
 				)
 				\ \ \text{for} \ \ s \in [0,t-\tb(x,v) ].
 			\end{cases}
 		\end{split}
 	\end{align*}
 	and
 		\begin{align*}
 		\begin{split}
 			(X(s;t,x,v), V(s;t,x,v)) \mathbf{1}_{\{\tb(x,v) = \infty\}} = (x-(t-s) v, v),  
 		\end{split}
 	\end{align*}
 	with Hamiltonian structure
 	\begin{equation} \notag
 		\frac{d}{ds} (X(s;t,x,v), V(s;t,x,v)  )   =    (V(s;t,x,v), 0),  \ \  \ 
 		(X(s;t,x,v)  , V (s;t,x,v)  )|_{s=t}=(x,v).
 	\end{equation} 

Now we read the the scaled Boltzmann equation \eqref{f_eqtn} in terms of $(X(s;t,x,v), V(s;t,x,v))$ and take integration in $s\in (0,t)$ to obtain the mild formulation
\Be \label{f_expan}
\begin{split} 
	f(t,x,v)
	&=  
	e^{- \int^t_ 0 \nu(f) (\tau, X(\tau;t,x,v), V(\tau;t,x,v)) d \tau}
	f(0,X(0;t,x,v), V(0;t,x,v))\\
	& \ \ + \int^t_0
	e^{- \int^t_ s \nu(f) (\tau, X(\tau;t,x,v), V(\tau;t,x,v)) d \tau}
	\Gamma_{\text{gain}}(f,f)(s,X(s;t,x,v), V(s;t,x,v)) ds
\end{split}
\Ee 
for \eqref{f_eqtn} and \eqref{specular}. The local in time existence of the mild solution \eqref{f_expan} is known as following.

\begin{lemma}[Local existence, \cite{GuoKim_boundary}] \label{lem:loc}
	Assume that the initial data $f_{0}$ satisfies $\|w_{0}(v)f_{0}\|_{\infty} := \|e^{\vartheta_{0}|v|^{2}}f_{0}\|_{\infty} < \infty$ for $0 < \vartheta_{0} < \frac{1}{4}$ and the initial compatibility condition \eqref{specular}. Then (\ref{f_expan}) has a unique local-in-time solution $f(t,x,v)$ on the interval $[0,T^*]$ for some $T^*>0$. Moreover, the solution satisfies
	\begin{equation*}
		\sup_{0\leq s \leq T^{*}} \|w(v) f(s)\|_{\infty} :=
		\sup_{0\leq s \leq T^{*}} \|e^{\vartheta |v|^{2}}f(s)\|_{\infty} \lesssim \|e^{\vartheta_{0} |v|^{2}}f_{0}\|_{\infty},
	\end{equation*}
	for some $0 < \vartheta < \vartheta_{0}$.  \\
\end{lemma}

