\section{Preliminary results}\label{sect2}

In this section, we show some general results that will be useful later. First, note that the function $h(t,x)$ defined in \eqref{eq:main1} is $2 \pi-$periodic with respect to $t$. Since the  periodic solutions of equation \eqref{eq:main1} are always $2 \pi$-periodic solutions, periodic will mean $2 \pi-$periodic in the following. Taking into account that the function $h(t,x)$ is globally Lipschitz continuous with respect to $x$, the solution $u(t,\tau,x)$ is defined for every $t\in\mathbb{R}$. 

Note that, for $p,q,\mu\in\mathbb{R}$, the solution $v(t,\tau,x)$ of the linear differential equation
\begin{equation}\label{eq:linearode}
    x'=px+q+\mu\sin t,
\end{equation}
with initial condition $v(\tau,\tau,x)=x$ is given by 
\begin{equation}\label{eq:sollinear}
v(t,\tau,x)= e^{p (t-\tau)}x+\int_{\tau}^t (q+\mu \sin( s)) e^{p(t- s)}\,ds.
\end{equation}
Thus, since differential equation \eqref{eq:main1} is piecewise linear, if $u(s,\tau,x)\leq -1$ for every $s\in[\tau,t]$, then
\begin{equation}\label{f1}
u(t,\tau,x)= e^{a (t-\tau)}x+\int_{\tau}^t (a-b+\mu \sin( s)) e^{a(t- s)}\,ds,
\end{equation}
if $-1\leq u(s,\tau,x)\leq 1$ for every $s\in[\tau,t]$, then
\begin{equation}\label{f2}
u(t,\tau,x)=e^{b( t-\tau)}x+\int_{\tau}^t \mu \sin(s) e^{b(t- s)}\, ds
\end{equation}
and if $u(s,\tau,x)\geq 1$ for every $s\in[\tau,t]$, then
\begin{equation}\label{f3}
u(t,\tau,x)= e^{a( t-\tau)}x+ \int_{\tau}^t (b-a+\mu \sin( s))e^{a(t- s)}\,ds.
\end{equation}

Define the Poincaré map for equation \eqref{eq:main1} as 
\begin{equation}\label{eq:Poincaremap}
P(x):=u(2 \pi,0,x)
\end{equation}
and the displacement function of \eqref{eq:main1} as
\begin{equation}\label{eq:disp_app}
d(x) := P(x)-x.
\end{equation}
Notice that the periodic solutions of equation \eqref{eq:main1} correspond to the fixed points of the Poincaré map $P$; that is, the zeroes of the displacement function $d$. Moreover, the limit cycles of the differential equation \eqref{eq:main1} correspond to the isolated zeroes of $d$.

From the odd symmetry of function $f$ given in \eqref{eq:f} it follows that $-u(t+\pi,\tau,x)$ is a solution of \eqref{eq:main1}. Thus, 
\[-u(t+\pi,0,x)=u(t,0,-u(\pi,0,x)),\]
and if we denote 
\begin{equation}\label{eq:semipoinca}
Q(x):=-u(\pi,0,x),
\end{equation}
then
\[
Q^2(x)=Q(Q(x))=Q(-u(\pi,0,x))=-u(\pi,0,-u(\pi,0,x))=u(2\pi,0,x),
\]
that is, $Q^2(x)=P(x)$. The map $Q$ is called a Poincaré half-map for equation \eqref{eq:main1}.

\begin{defi}
We say that the solution $u(t,0,x)$ is a symmetric periodic solution of \eqref{eq:main1} if $x$ is a fixed point of the map $Q$.
\end{defi}

The following result ensures that the Poincaré map $P$, the displacement function $d$, and the Poincaré half-map $Q$ are functions of class $\mathcal{C}^1$. Its proof can be adapted directly from the proof of Proposition 4.6 of \cite{Carmona200471} (alternatively, Theorem~A.1 of~ \cite{BravoFernandezTineo07}) given for piecewise linear differential equations with two zones of linearity. 

\begin{prop}\label{prop:der}
The Poincaré map $P$ defined in \eqref{eq:Poincaremap}, the  displacement function given in \eqref{eq:disp_app}, and the Poincaré half-map $Q$ given in \eqref{eq:semipoinca} are continuously differentiable, and their respective derivatives can be written as 
\[
P'(x) = e^{2\pi\,a + (b-a)\, m(A_{in}(x))},
\]
\[
d'(x) = e^{2 \pi a + (b-a) m(A_{in}(x))}-1 
\]
and 
\[
Q'(x) = -e^{\pi\,a + (b-a)\, m(A_{in}(x)\cap [0,\pi])},
\]
where $A_{in}(x):=\{t\in[0,2\pi] \colon |u(t,0,x)|\leq 1 \}$ and $m(\cdot)$ denotes, as usual, the measure of a measurable set in $\mathbb{R}$.
\end{prop}

\begin{proof}
For the differentiability, we refer the reader to Proposition 4.6 of \cite{Carmona200471} or Theorem~A.1 of~ \cite{BravoFernandezTineo07}. Then,
we have that $u(t,0,x)$ is continuously differentiable with respect to $x$ and that
\begin{equation*}
u_x(t,0,x)= \exp\left(\int_0^t f'(u(s,0,x))\,ds \right),
\end{equation*}
where the subscript means partial derivative. Now, it suffices to observe that $P(x)=u(2\pi,0,x)$, that $Q(x)=-u(\pi,0,x)$ and that $f'(u(s,0,x))=a$, if $|u(s,0,x)|\geq1$ and $f'(u(s,0,x))=b$, if $|u(s,0,x)|\leq1$.
\end{proof}

Observe that if $P(\bar x)=\bar x$ and $P'(\bar x)\ne 1$, then the periodic solution $u(t,0,\bar x)$ is a hyperbolic limit cycle and this limit cycle is attractive (resp. repulsive) if $P'(\bar x)<1$ (resp. $P'(\bar x)>1$). In addition, the periodic solution is singular or non-hyperbolic (that is, $P'(\bar x)=1$)  if and only if $m(A_{in}(\bar x)) = 2\pi\, a/(a-b)$.

The following result is \cite[Teorema 1]{CFPT2}. We include the proof for the sake of completeness.
\begin{prop}[\cite{CFPT2}]\label{prop:sym}
Equation \eqref{eq:main1} has exactly one symmetric periodic solution, which we will denote by $u^s(t)$.
\end{prop}

\begin{proof} When $|x|$ is large enough, by means of expressions \eqref{f1} and  \eqref{f3}, one obtains that
\begin{equation*}
Q(x)-x= (-e^{ \pi\, a}-1)x+ \ldots,
\end{equation*}
where the dots denote terms not depending on $x$. Hence, $\lim_{x\to\infty}(Q(x)-x)=-\lim_{x\to -\infty}(Q(x)-x) \ne 0$ and since $Q$ is continuous,  it is deduced that $Q$ has at least one fixed point $\bar x^s$. Now, from Proposition \ref{prop:der} it follows that $Q'(x)<0$ for all $x\in \mathbb{R}$ and so we conclude the uniqueness of the symmetric periodic orbit $u^s(t):=u\left(t,0,\bar x^s\right)$.
\end{proof}


As a direct consequence of Proposition \ref{prop:sym}, we have that equation \eqref{eq:main1} possesses at least one periodic solution, the symmetric one.

\begin{rema}\label{rema:signo}
The change of variable $t \to -t$ transforms the equation $x' = f(x) + \mu \sin(t)$ into $x' = f(-x) + \mu \sin(t)=-f(x) + \mu \sin(t)$, so we can choose the sign of $a$ or $b$. Moreover, the change of variable $t\to t+\pi$ transforms $x'=f(x)+\mu \sin(t)$ into $x'=f(x)-\mu \sin(t)$, so we can also choose the sign of $\mu$.
\end{rema}

