%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Uniqueness of limit cycles for the case $ab\geq0$}\label{Sect3}

Note that \eqref{eq:main1} has a center if the displacement function \eqref{eq:disp_app} is zero in an entire interval. If the displacement function of \eqref{eq:main1} is identically zero, the center is said to be global.

\begin{theo} \label{teor:unicilc}
Assume that $ab\geq 0$. Then the dynamics of equation~\eqref{eq:main1} is one of the following:
\begin{enumerate}
\item Equation \eqref{eq:main1} has a global center if and only if $a=b=0$.
\item If $b = 0$ and $|\mu| < 1$, equation \eqref{eq:main1} has a center and no limit cycles.
\item In any other case, equation \eqref{eq:main1} has exactly one limit cycle, which is the symmetric periodic solution $u^s(t)$ given in Proposition \ref{prop:sym}. Moreover, the limit cycle is hyperbolic, globally asymptotically stable when $b<0$ and unstable when $b>0$.
\end{enumerate}
\end{theo}

The proof of this result is organized as follows: the characterization that \eqref{eq:main1} is a global center, that is item (1), is Proposition~\ref{prop:globalcenter}, while items (2) and (3) are obtained as a consequence of Propositions~\ref{prop:b0} and \ref{prop:a0}, which correspond to the cases $b=0$ and $b \neq  0$, respectively.

\begin{prop}\label{prop:globalcenter}
Equation \eqref{eq:main1} is a global center if and only if $a=b=0$.
\end{prop}

\begin{proof} Note that by Remark~\ref{rema:signo}, we can assume, without loss of generality, that $b,\mu\in(-\infty, 0]$. If equation \eqref{eq:main1} is a global center, then $u(t,0,x)$ is periodic for all $x\in\mathbb{R}$. So, considering the vector field defined by equation \eqref{eq:main1} on the line $x=-1$, one can see that $u(t,0,x)<-1$ for every $t\in [0,2\pi]$ and $x \ll -1$ 
Therefore using \eqref{f1} we obtain
\[x = u(2\pi,0,x)= e^{2\pi a}x+\int_0^{2\pi} (a-b+\mu \sin( s)) e^{a(2\pi- s)}\,ds;\]
for all $x \ll -1$ and so  $a=b=0$. Conversely,  when $a=b=0$, equation \eqref{eq:main1} is $x'= \mu \sin(t)$, which presents clearly a global center.
\end{proof}

\begin{prop}\label{prop:b0}
Suppose $a \ne 0$ and $b=0$, then equation \eqref{eq:main1} either has a center and no limit cycles, if $0\leqslant |\mu| <1$, or it has exactly one limit cycle, if $|\mu|\geqslant 1$.
\end{prop}

\begin{proof}
When $b=0$, by Proposition~\ref{prop:der}, the derivative of displacement function $d$ is $d'(x)=e^{a(2\pi- m(A_{in}(x)))}-1$. Therefore, since $m(A_{in}(x)) \leq 2\pi$, for $a\ne 0$ we have that $a d'(x)\geqslant 0$ and that it is zero only for those $x$ such that $|u(t,0,x)|\leq 1$, for every $t \in [0,2\pi]$. Now,  according to \eqref{f2},  if $| u(s,0,x) | \leq 1$ for every $s \in [0,t]$, then $u(t,0,x) = x+\mu(1-\cos(t))$, and we conclude that there exists an open interval $I \subset [-1,1]$ such that $|u(t,0,x)|\leq 1$ for every $x \in I$ and $t \in [0,2\pi]$ if and only if $0\leqslant |\mu| <1$. Moreover, in this case, $d(x) = 0$ for every $x \in I$.

In summary, equation \eqref{eq:main1} has a center with no limit cycles if $0\leqslant |\mu| <1$ and has at most one limit cycle otherwise. By Proposition \ref{prop:sym} we obtain the desired result.
\end{proof}

\begin{prop}\label{prop:a0}
If $ab\geq 0$ and $b \neq 0$, then \eqref{eq:main1} has exactly one limit cycle, the symmetric periodic solution $u^s(t)$ given in Proposition \ref{prop:sym}. Moreover, the limit cycle is hyperbolic, globally asymptotically stable when $b<0$ and unstable when $b>0$.
\end{prop}

\begin{proof}
Recall that, by Proposition~\ref{prop:der}, $d'(x) = e^{2 \pi a + (b-a) m(A_{in}(x))}-1$. 

If $a = 0$, then $d'(x)=e^{b\, m(A_{in}(x))}-1$. So, since $m(A_{in}(x)) \geqslant 0$, we have $bd'(x)\geqslant 0$ and, for $b\ne 0$,  it is zero only for those $x$ such that $|u(t,0,x)|\geq 1$, for every $t \in [0,2\pi]$. Therefore, by \eqref{f1} or \eqref{f3} as appropriate, we conclude that $d(x) = -2\pi b\sgn(x)$ for those $x$ such that $|u(t,0,x)|\geqslant 1$ for $t \in [0,2\pi]$. Thus, when $b\ne 0$, it is easy to see that equation \eqref{eq:main1} has at most one limit cycle $u(t,0,\bar x)$ and it is verified $bd'(\bar x)> 0$. Thus, from Proposition \ref{prop:sym}, the limit cycle unique and, moreover, it is hyperbolic, globally asymptotically stable when $b<0$ and unstable when $b>0$.

If $ab > 0$, then $d'(x)$ does not vanish because $m(A_{in}(x)) \in [0,2\pi].$ So, we conclude that $d'(x)$ has a constant sign. Therefore, equation \eqref{eq:main1} has at most one limit cycle  and its hyperbolicity and stability follow from $\sgn(d'(x))=\sgn(a (2\pi-m(A_{in}(x))+b\, m(A_{in}(x))))$. By Proposition \ref{prop:sym} the conclusion follows.
\end{proof}

