%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Number of limit cycles for extreme values of $\mu$}\label{Sect:Compacity}

According to Theorem \ref{teor:unicilc}, possible bifurcations can only occur if $ab$ is strictly negative. Thus, assuming $a b < 0$, we show that there are exactly three limit cycles for $|\mu|$ close to zero (Theorem \ref{Th:-mu_small}), and exactly one non-singular limit cycle for $|\mu|$ sufficiently large (Theorem \ref{Th:-mu_large}). 

Let us start with a useful lemma.

\begin{lema}\label{le:1}
Consider equation \eqref{eq:linearode} with $p\ne 0$. The only periodic solution of equation \eqref{eq:linearode} is 
\begin{equation}
\label{eq:opeqlinear}
    v(t)=-\frac{q}{p}-\frac{\mu(\cos(t)+p\sin(t))}{p^2+1}.
\end{equation}
Moreover, this periodic solution is non-singular (that is, hyperbolic), globally asymptotically stable when $p<0$, and unstable when $p>0$.
\end{lema}

\begin{proof}
From expression \eqref{eq:sollinear}, one can deduce that the Poincaré map for equation \eqref{eq:linearode} is given by the linear map 
\[
\tilde P(x):=v(2\pi,0,x)=\frac{\left(e^{2 \pi  p}-1\right)
   \left(p^2+1\right) q+e^{2 \pi  p}
   p \left(\mu +p^2
   x+x\right)-\mu 
   p}{p^3+p}
\]
which, for $p\ne 0$, has a unique fixed point $\bar x=-q/p-\mu\left(p^2+1 \right)^{-1}$. This fixed point provides the unique solution periodic $v(t):=v(t,0,\bar x)$ given in \eqref{eq:opeqlinear}. Since the derivative of $P$ is $\tilde P'(x)=e^{2\pi p}$, the conclusion of the hyperbolicity and stability of the periodic solution $v$ is direct.
\end{proof}

Due to the previous lemma, we can determine when equation~\eqref{eq:main1} has a periodic solution in the regions $x\geq 1$ and $x\leq -1$.

\begin{prop}\label{prop:1}
Consider equation \eqref{eq:main1} with $ab<0$. The following statements are equivalent.
\begin{enumerate}
\item There exists a periodic solution $u^+$ of equation \eqref{eq:main1} such that $u^+(t) \geq 1$ for all $t\in\mathbb{R}$.
\item There exists a periodic solution $u^-$ of equation \eqref{eq:main1} such that $u^-(t) \leq -1$ for all $t\in\mathbb{R}$.
\item $|\mu|\leqslant -b \sqrt{a^2+1}/a$.
\end{enumerate}
In these cases, the periodic solutions are the only ones in the corresponding zone of linearity;  specifically,
\begin{equation}
\label{eq:opumas}
    u^+(t) = \frac{a-b}{a} - \frac{\mu(\cos(t)+a\sin(t))}{a^2+1}\quad \text{and}\quad u^-(t) = -u^+(t+\pi).
\end{equation}
In addition, these periodic solutions are hyperbolic, asymptotically stable when $b>0$, and unstable when $b<0$.
\end{prop}

\begin{proof}
Since the equivalence of items (1) and (2) follows by symmetry, it suffices to prove the equivalence of items (1) and (3). 

If equation \eqref{eq:main1} possesses a periodic solution $u^+$ such that $u^+(t) \geqslant  1$ for all $t\in\mathbb{R}$, then the solution $u^+$ is a periodic solution of the linear differential equation $x'= ax+(b-a)+\mu \sin(t)$. Thus, by Lemma \ref{le:1}, the expression for the periodic solution $u^+$ is provided in \eqref{eq:opumas} by substituting $p=a$ and $q=b-a$ in the periodic solution $v$ of \eqref{eq:opeqlinear}. 

A straightforward computation indicates that the global minimum of the function $u^+$ given in \eqref{eq:opumas} is 
\[H:=\frac{a-b}{a}-\frac{|\mu|}{\sqrt{1+a^2}}.\]
Therefore, the function $u^+$ is a periodic solution of \eqref{eq:main1} if and only if $H\geqslant 1$, which is equivalent to the inequality of item (3). The expression for the periodic solution $u^-$ follows by symmetry, and, since $a b < 0$, the conclusion for the hyperbolicity and stability of the periodic solutions is a direct consequence of Lemma \ref{le:1}.
\end{proof}

Next, we study when limit cycles of equation  \eqref{eq:main1} exist in the zone $|x|\leqslant 1$. The proof of the next result is similar to the proof of Proposition \ref{prop:1} and is omitted.

\begin{prop}\label{prop:2}
Consider equation \eqref{eq:main1} with $b\ne0$. There exists a isolated periodic solution $u$ of equation \eqref{eq:main1} such that $|u(t)| \leqslant 1$ for all $t\in\mathbb{R}$ if and only if $|\mu|\leqslant \sqrt{b^2+1}$. In these cases, the periodic solution is the only one in the  zone $|x|\leqslant 1$; specifically,
\[
u(t) = -\frac{\mu (\cos(t)+b\sin(t))}{b^2+1},
\]
which is the symmetric periodic solution $u^s$ given in Proposition \ref{prop:sym}. In addition, this periodic solution is hyperbolic, asymptotically stable when $b<0$ and unstable when $b>0$.
\end{prop}

Summarizing, we can state our result for the existence of three limit cycles for equation \eqref{eq:main1}.

\begin{theo}\label{Th:-mu_small}
Suppose that $ab < 0$. Equation~\eqref{eq:main1} has exactly three limit cycles, each of them located in a zone of linearity, if and only if
\[
|\mu| \leq \min\left\{ \frac{-b\sqrt{a^2 + 1}}{a}, \sqrt{b^2 + 1} \right\}.
\]
These three limit cycles are hyperbolic; the those in the zones $x \geq 1$ and $x \leq -1$ are asymptotically stable when $b > 0$ and unstable when $b < 0$, and the limit cycle contained in the region $|x| \leq 1$ is asymptotically stable when $b < 0$ and unstable when $b > 0$.
\end{theo}

To conclude this section, we prove the uniqueness of limit cycles for $|\mu|$ sufficiently large, where the size depends on parameters $a$ and $b$. 

\begin{theo}\label{Th:-mu_large} 
Suppose that $ab<0$. 
There exists a value $\bar{\mu}=\bar{\mu}(a,b)> 0$ such that if $|\mu| >\bar\mu$, then equation \eqref{eq:main1} has only one limit cycle $u(t,0,x)$. Moreover, this limit cycle is symmetric, hyperbolic, globally asymptotically stable when $b>0$ and unstable when $b<0$ and the initial condition $x$ satisfies $|x|\leqslant |\mu|(1+1/|a|)$.
\end{theo}

\begin{proof}
First, note that periodic solutions of equation \eqref{eq:main1} are constant when $\mu=0$. For $\mu\neq 0$, the change of variable $X=x/|\mu|$ transforms equation \eqref{eq:main1} into the equation
\begin{equation}\label{eq:cvmain1}
X'=g(X)+\sgn(\mu)\sin t
\end{equation}
where 
\[
g(X)=
\begin{cases}
a\, X+\frac{a-b}{|\mu|},\quad \text{if }X\leq -\frac{1}{|\mu|},\\
b\, X,\quad \text{if }-\frac{1}{|\mu|}<X < \frac{1}{|\mu|},\\
a\, X+\frac{b-a}{|\mu|},\quad \text{if } X \geq \frac{1}{|\mu|}.
\end{cases}	
\]
Note that the limit differential equation of \eqref{eq:cvmain1} when $|\mu|$ tends to  infinity is the scalar linear differential equation 
\begin{equation}\label{eq:linear_limit}
X'=aX+\sgn(\mu)\sin t.
\end{equation}

By means of Lemma \ref{le:1}, for $a\ne 0$, linear differential equation \eqref{eq:linear_limit} has a unique limit cycle $U_l$ and this limit cycle is hyperbolic, globally asymptotically stable when $a<0$ and unstable when $a>0$. 
Moreover, $U_l$ is symmetric and crosses the straight line $X=0$ transversely. 

As the vector field \eqref{eq:cvmain1} is continuous with respect to $\nu = 1/|\mu|$, the solutions of \eqref{eq:cvmain1} in a neighborhood $V$ of $U_l$ for $t\in[0,2\pi]$ are also transversal to $X=0$ for $t\in[0,2\pi]$. 
Moreover, for every solution~$U$ of equation ~\eqref{eq:cvmain1} contained in $V$ for $t\in[0,2\pi]$,
\[\lim_{\nu\to 0}m(A_{in}(\nu,U))=0,\] 
where $A_{in}(\nu,U)=\{t\in[0,2\pi]\colon |U(t)|\leq \nu\}$. As the change of variables preserves the parametrization of time, Proposition~\ref{prop:der} and the hyperbolicity of $U_l$ implies the existence of $\tilde \mu=\mu(a,b)>0$ such that equation \eqref{eq:cvmain1} has a unique limit cycle in $V$ for $|\mu|>\tilde \mu$. 

In addition, this limit cycle is symmetric, hyperbolic, and crosses transversely the separation straight lines $X=-1/|\mu|$ and $X=1/|\mu|$. Moreover, this limit cycle has the same stability as the limit cycle $U_l$ and, since $ab<0$, it is globally asymptotically stable when $b>0$ and unstable when $b<0$.

The vector field defined by equation \eqref{eq:linear_limit} in the lines $X=\pm(1+1/|a|)$ satisfies
\[
\begin{array}{l}
aX'|_{1+1/|a|}=a(a+\sgn(a)+\sgn(\mu)\sin t)>0 \quad \mbox{for all} \quad t\in\mathbb{R},
\\
\noalign{\medskip}
aX'|_{-(1+1/|a|)}=-a(a+\sgn(a)-\sgn(\mu)\sin t)<0 \quad \mbox{for all} \quad t\in\mathbb{R},
\end{array}
\]
which means that the band $|X|\leqslant 1+1/|a|$ is a positively (resp., negatively) invariant region for equation \eqref{eq:linear_limit} when $a<0$ (resp. $a>0$). Thus, there exists a value $\hat \mu=\hat\mu(a,b)>0$ such that the periodic solutions of equation \eqref{eq:cvmain1} are bounded in the band $|X|\leqslant 1+1/|a|$ for $|\mu|>\hat \mu$. 

Now, if for each $n\in\mathbb{N},n>\max\{\tilde \mu, \hat \mu\}$, equation \eqref{eq:cvmain1} with $|\mu|=n$ has a periodic solution $U_n$ other than the symmetric periodic solution (see Proposition \ref{prop:sym}), then, by compacity, there exists a convergent subsequence $\{U_{n_k}\}$ and, by means of continuity with respect to the parameters and initial conditions, this subsequence converges to $U_l$, the unique periodic solution of equation \eqref{eq:linear_limit}. Therefore, for $|\mu|=n_k$ sufficiently large, equation \eqref{eq:cvmain1} has two periodic solutions in a neighborhood of $U_l$ and this is impossible based on the hyperbolicity of the solution $U_l$. 

Therefore, there exists a value $\bar{\mu}=\bar{\mu}(a,b)>\max\{\tilde \mu, \hat \mu\}$ such that if $|\mu| >\bar\mu$, then equation \eqref{eq:main1} has only one limit cycle $u(t,0,x)$. The hyperbolicity and stability of this limit cycle are straightforward and the bound of $|x|$ follows from the invariance of the band $|x/\mu|=|X| \leq 1+1/|a|$.
\end{proof}

