\section{First order perturbation}\label{Sect:Melnikov}

Define $f(x)$ as in \eqref{eq:f} and consider, for $|\epsilon|$ is sufficiently small, the differential equation 
\[
x'=\epsilon f(x)+\mu \sin t.\tag{\ref{eq:ef}}
\]
In this section, we compute the first order Melnikov function or averaging function for the deformation~\eqref{eq:ef} and prove the following result.

\begin{theo}\label{theo:Melnikov}
Let $a$ and $b$ be fixed such that $a b<0$. Let us define the values
\begin{equation}
\label{ecu:defmu1yc}
\mu_1 := \frac{c}{\sin(c)}\, , \qquad \mu_2:=\frac{1}{\cos(c/2)}\, ,\qquad \mbox{with} \qquad c:=\frac{ \pi b}{b-a}\,.
\end{equation}
Then $0 < \mu_1 < \mu_2$ and, for each $\mu\in\mathbb{R}$, there exists a value $\varepsilon_0(\mu)>0$ such that 
\begin{enumerate}
    \item if $0\leq |\mu|<\mu_2$, then equation \eqref{eq:ef} has exactly three limit cycles,
    \item if $\mu_2< |\mu|<\mu_1$, then equation \eqref{eq:ef} has exactly five limit cycles,
    \item if $|\mu|>\mu_1$, then equation \eqref{eq:ef} has exactly one limit cycle,
\end{enumerate}
whenever $|\varepsilon|<\varepsilon_0(\mu)$.
\end{theo}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Melnikov function: general properties.} Let us write $u(t,x,\mu,\epsilon)$ for the solution of equation \eqref{eq:ef} such that $u(0,x,\mu,\epsilon)=x$. 

For $\epsilon = 0$,  equation \eqref{eq:ef} has a  global center, since \[u(t,x,\mu,0) = \mu(1-\cos t) + x,\] for every $x \in \mathbb{R}$. 

The change of variable $x\to \mu(1-\cos t)+x $ transforms the differential equation \eqref{eq:ef} into the form
\[
x'=\varepsilon f(\mu(1-\cos t)+x),
\]
and, therefore, the study of the periodic solutions of equation \eqref{eq:ef} for $|\varepsilon|$ sufficiently small can be carried out by means of the averaging theory (or Menilkov theory) recently developed for non--smooth systems in works as \cite{Carmona201344,Llibre20154007,Llibre20171,Llibre2014563,Novaes20241486}, and also applied to Abel equation by Neto~\cite{Neto1980}. Thus, for instance, from Theorem A in \cite{Llibre20154007}, one can deduce that the zeros of the first-order averaging function  
\begin{equation}
\label{ecu:Melnikovfun}
\mathcal{M}(x,\mu):=\int_0^{2\pi} f(\mu(1-\cos t)+x)\,dt
\end{equation}
with non--zero Brouwer degree provide limit cycles of equation \eqref{eq:ef} for $|\varepsilon|$ sufficiently small. Notice that the derivative with respect to $\varepsilon$ of the solution $u(t,x,\mu,\varepsilon)$ for $t=2\pi$ and $\varepsilon=0$ coincides with the averaging function $\mathcal{M}$ defined in \eqref{ecu:Melnikovfun}. That is,
\[
u_{\varepsilon}(2\pi,x,\mu,0) = \int_0^{2\pi} f(\mu(1-\cos t)+x)\,dt.
\]
For this reason, function $\mathcal{M}$ is also called the first order Melnikov function (see, for instance,  \cite{Carmona201344,Novaes20241486,Blows1994341}). 

From now on, the main objective will be the proof of Theorem \ref{theo:Melnikov}, which will rely primarily on the analysis of the Melnikov function $\mathcal{M}$, and more specifically, on the precise description of its zero set. To that end, it is appropriate to first perform a translation that allows us to work with a symmetric function that inherits the symmetry of equation \eqref{eq:ef} (see Remark \ref{rema:signo}). Thus, we define the function
\begin{equation}
\label{ecu:Melnikovfuntilde}
 M (x,\mu)=\mathcal{M}(x-\mu,\mu)=\int_0^{2\pi} f(x-\mu\cos t)\,dt.
\end{equation}

Now, we will show that the function $M$ is continuously differentiable (see Proposition \ref{prop:der} and its proof) and provide expressions for the derivatives of 
$ M$ with respect to $x$ and with respect to $\mu$.

\begin{prop}
\label{prop:dertildeM}
Function $ M$ defined in \eqref{ecu:Melnikovfuntilde} is continuously differentiable in $\mathbb{R}^2$. Moreover, the derivatives of $ M$ with respect to $x$ and with respect to $\mu$ are given, respectively, by 
\begin{equation}
\label{ecu:DerMtildex}
 M_x(x,\mu)=2 \pi a - (a-b)  m\left( A_{in}(x,\mu)\right) 
\end{equation}
and 
\begin{equation}
\label{ecu:DerMtildemu}
 M_\mu(x,\mu)=(a-b)\int_{ A_{in}(x,\mu)}\cos t \, dt,
\end{equation}
where 
\begin{equation}
\label{ecu:Atilde}
 A_{in}(x,\mu)=\left\{ t\in[0,2\pi]:|x-\mu\cos t|\leqslant 1\right\} 
\end{equation}
and $m(\cdot)$ denotes, as usual, the measure of a measurable set in $\mathbb{R}$.
\end{prop}
\begin{proof}
Since function $f$ defined in \eqref{eq:f} is continuous and piecewise linear, it is clear that function $ M$ is continuously differentiable in $\mathbb{R}^2$. The derivative of  $ M$ with respect to $x$ is 
\[
\begin{split}
 M_x(x,\mu)& = \int_0^{2\pi}  f'(x-\mu\cos t)\,dt=\int_{ A_{in}(x,\mu)} b\,dt
+ \int_{[0,2\pi]\setminus  A_{in}(x,\mu)} a\,dt\\
& = b\, m\left( A_{in}(x,\mu)\right) + a\, (2 \pi - m\left( A_{in}(x,\mu)\right)=2 \pi a - (a-b)  m\left( A_{in}(x,\mu)\right),
\end{split}
\]
where the set $ A_{in}(x,\mu)$ is defined in \eqref{ecu:Atilde}.

The derivative of $ M$ with respect to $\mu$ is 
\[
\begin{split}
 M_\mu(x,\mu)& = \int_0^{2\pi}  -f'(x-\mu\cos t)\cos t\,dt= \int_{ A_{in}(x,\mu)} -b\cos t\,dt
+ \int_{[0,2\pi]\setminus  A_{in}(x,\mu)} -a\cos t\,dt\\ &
=(a-b)\int_{ A_{in}(x,\mu)} \cos t\,dt,
\end{split}
\]
because 
\begin{equation}
\label{eq:intcons02pi}
0=\int_0^{2\pi}\cos t=\int_{ A_{in}(x,\mu)} \cos t\,dt+\int_{[0,2\pi]\setminus A_{in}(x,\mu)} \cos t\,dt.
\end{equation}
\end{proof}
\begin{rema}
The expressions for the partial derivatives of $ M$ given in Proposition \ref{prop:dertildeM} allow us to obtain a new expression for $ M$ depending on $ M_x$ and $ M_\mu$. Indeed, by using the expression for function $f$ given in \eqref{eq:f}, it follows that
\[
\begin{array}{ccl}
 M(x,\mu)&=&{\displaystyle \int_0^{2\pi} f(x-\mu\cos t)\,dt=\int_{A^+(x,\mu)} (a(x-\mu\cos t)+(b-a)) dt}+ \\
\noalign{\medskip}
& & {\displaystyle \int_{ A_{in}(x,\mu)} b(x-\mu\cos t) dt}+ {\displaystyle \int_{A^-(x,\mu)} (a(x-\mu\cos t)+(a-b)) dt}, \\
\end{array}
\]
where $ A_{in}(x,\mu)$ is given in \eqref{ecu:Atilde}, 
\begin{equation}
\label{eq: A+-}
\begin{array}{lcl}
A^+(x,\mu)& =& \{ t\in[0,2\pi]: x-\mu\cos t \geqslant 1\} \qquad \mbox{and}  \\
\noalign{\medskip}
A^-(x,\mu)& = & \{ t\in[0,2\pi]: x-\mu\cos t \leqslant -1\}.
\end{array}
\end{equation}
Hence, since $A^+(x,\mu)\cup A^-(x,\mu)=[0,2\pi]\setminus A_{in}(x,\mu) $, one gets
\[
\begin{array}{ccl}
 M(x,\mu)&=&{\displaystyle \int_{[0,2\pi]\setminus A_{in}(x,\mu)} ax \, dt -\mu\left(\int_{[0,2\pi]\setminus A_{in}(x,\mu)} a\cos t \,dt+ \int_{ A_{in}(x,\mu)} b\cos t \,dt \right)} +\\
\noalign{\medskip}
& & {\displaystyle \int_{ A_{in}(x,\mu)} bx \, dt+ \int_{A^+(x,\mu)} (b-a) \, dt+ \int_{A^-(x,\mu)} (a-b)\,  dt }\\
\end{array}
\]
and, from expressions \eqref{ecu:DerMtildex}, \eqref{ecu:DerMtildemu} and \eqref{eq:intcons02pi}, it has 
\begin{equation}
\label{ecu:Mtildeversion}
 M(x,\mu)=x M_x(x,\mu)+\mu M_\mu(x,\mu)-(a-b)\left(m\left(A^+(x,\mu) \right)- m\left(A^-(x,\mu) \right)\right).
\end{equation}
\end{rema}

\begin{rema}
\label{rema:derMmu}
The following observations are made with regard to the derivative with respect to $\mu$  of function $ M$.

Let us consider the periodic function $v(t)=x-\mu\cos t$ and the set $ A_{in}(x,\mu)$ defined in \eqref{ecu:Atilde}. Function $v$ is one--zonal if and only if $ A_{in}(x,\mu)= \emptyset$ or $ A_{in}(x,\mu)= [0,2\pi]$. Thus,  from expression for $M_\mu$ given in \eqref{ecu:DerMtildemu}, one has $ M_\mu(x,\mu)=0$ when $v$ is one--zonal.

If $v$ is two--zonal, then $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$ and the equation $|v(t)|=1$ has exactly two solutions $t_1=t_1(x,\mu)$ and $t_2=t_2(x,\mu)=2\pi-t_1(x,\mu)$ in the interval $(0,2\pi)$, with $t_1\in(0,\pi)$. Thus, it is immediate to observe that $ A_{in}(x,\mu)=[t_1,2\pi-t_1]$ or $[0,2\pi]\setminus  A_{in}(x,\mu)=[t_1,2\pi-t_1]$.  If $ A_{in}(x,\mu)=[t_1,2\pi-t_1]$, from expression \eqref{ecu:DerMtildemu}, follows 
\begin{equation}
\label{eq:dertildeMmu2z}
 M_\mu(x,\mu)=(a-b)\int_{ A_{in}(x,\mu)}\cos t \, dt=(a-b)\int_{t_1}^{2\pi-t_1}\cos t \, dt=-2(a-b)\sin t_1\ne 0.
\end{equation}
When $[0,2\pi]\setminus  A_{in}(x,\mu)=[t_1,2\pi-t_1]$, from expressions \eqref{ecu:DerMtildemu}  and \eqref{eq:intcons02pi}, it is deduced
\begin{equation}
\label{eq:dertildeMmu2zb}
 M_\mu(x,\mu)=(a-b)\int_{ A_{in}(x,\mu)}\cos t \, dt=-(a-b)\int_{t_1}^{2\pi-t_1}\cos t \, dt=2(a-b)\sin t_1\ne 0.
\end{equation}

If $v$ is three--zonal, then $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$ and the equation $|v(t)|=1$ has exactly four solutions in the interval $(0,2\pi)$. Namely, $\hat t_1=t_1(x,\mu),\hat t_2=t_2(x,\mu)$, $\hat t_3=2\pi-\hat t_2$, and $\hat t_4=2\pi-t_1$ (with $0<\hat t_1<\hat t_2<\pi$), where 
\begin{equation}
\label{eq:t1t23z}
|x-\mu\cos \hat t_1|=|x-\mu\cos \hat t_2|=1 \quad \mbox{and}\quad  (x-\mu\cos \hat t_1)(x-\mu\cos \hat t_2)=-1.
\end{equation}
Hence, $ A_{in}(x,\mu)=[\hat t_1,\hat t_2]\cup [2\pi-\hat t_2,2\pi-\hat t_1]$ and 
\begin{equation}
\label{eq:dertildeMmu3z}
 M_\mu(x,\mu)=(a-b)\int_{ A_{in}(x,\mu)}\cos t \, dt=2(a-b)\left( \sin \hat t_2- \sin \hat t_1 \right).
\end{equation}

\end{rema}


Taking into account that, from Proposition \ref{prop:dertildeM}, the function $ M$ is continuously differentiable, we may replace the Brouwer degree in Theorem A of \cite{Llibre20171} with the derivative of 
$ M$ with respect to x, and state the following result concerning the existence of limit cycles of equation \eqref{eq:ef} for $|\varepsilon|$ sufficiently small (see also Theorem 1.2  of \cite{Blows1994341}). Observe that Melnikov function $\mathcal{M}$ defined in \eqref{ecu:Melnikovfun} is also continuously differentiable and 
$
\mathcal{M}_x(x,\mu)= M_x(x+\mu,\mu).
$

\begin{prop}
\label{prop:existclMel}
Suppose that the parameters $a$ and $b$ are fixed with $ab<0$ and let us consider function $ M$ defined in \eqref{ecu:Melnikovfuntilde}. If there exists $(x_0,\mu_0)\in \mathbb{R}^2$ such that $ M(x_0,\mu_0)=0$ and $ M_x(x_0,\mu_0)\ne 0$, then exists $\tilde\varepsilon_0(x_0,\mu_0)>0$ such that equation \eqref{eq:ef} for $\mu=\mu_0$ and $|\varepsilon|<\tilde\varepsilon_0(x_0,\mu_0)$ has a unique limit cycle in a neighborhood of the periodic solution $u(t,x_0,\mu_0,0) = \mu_0(1-\cos t) + x_0$. Moreover, this limit cycle converges to the periodic solution $u(t,x_0,\mu_0,0)$  as $\varepsilon$ goes to zero.
\end{prop}

From Proposition \ref{prop:existclMel}, the number of simple zeros of the function $ M$ determines a lower-bound of the number of limit cycles of \eqref{eq:ef}.

\subsection{Characterization of zero set of the function $ M$}
Some basic properties of the function $M$ are collected in the next result. In particular, we compile results regarding the symmetry properties of the function $ M$ (see Remark \ref{rema:signo}) and prove that its zero set corresponding to non-zero values of $x$ is contained within a compact subset of the plane.


\begin{prop}
\label{prop:tildeM}
Suppose that the parameters $a$ and $b$ are fixed with $ab<0$. Then, function $M$ defined in \eqref{ecu:Melnikovfuntilde} satisfies the following properties:
\begin{enumerate}
\item \label{item1proptildeM} $ M(-x,\mu) = -  M(x,\mu)$ for every $(x,y)\in\mathbb{R}^2$. In particular, $ M(0,\mu) =0$ for all $\mu\in\mathbb{R}$. Moreover, if $|\mu|\leqslant 1$, then   $ M_x(0,\mu)=2\pi b \ne 0$.
\item \label{item2proptildeM} $ M(x,-\mu) =  M(x,\mu)$ for every $(x,\mu)\in\mathbb{R}^2$.
\item \label{item3proptildeM} Suppose that the periodic function $v(t)=x-\mu\cos t $, with $x\ne 0$, is one--zonal. Then,  $ M(x,\mu) =0$ if and only if $|x|=1-b/a$ and $|\mu|\leqslant -b/a$. In addition, $ M_x(\pm(1-b/a),\mu)=2\pi a \ne 0$ for $|\mu|\leqslant -b/a$.
\item\label{itemdermuproptildeM}  $ M_\mu(0,\mu)=0$ for all $\mu\in \mathbb{R}$. Moreover,  if the set  $ A_{in}(x,\mu)$ defined in \eqref{ecu:Atilde} is $ A_{in}(x,\mu)= \emptyset$ or $ A_{in}(x,\mu)= [0,2\pi]$, then  $ M_\mu(x,\mu)=0$. In addition, $ M_\mu(x,\mu)\ne 0$ if $x\ne 0$ and $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$.
\item \label{item5proptildeM} If $|x|> 1-b/a$, then $\sgn\left( M(x,\mu)\right)=\sgn(x) \sgn(a)\ne 0$ for all $\mu\in\mathbb{R}$.
\item \label{item6proptildeM}There exists a value $\check \mu=\check \mu(a,b)>0$ such that $\sgn\left( M(x,\mu)\right)=\sgn(x) \sgn(a)\ne 0$ for $x\ne 0$ and $|\mu|>\check \mu$.
\end{enumerate}
\end{prop}

\begin{proof}
\begin{enumerate}
\item Since  function $f$ given in \eqref{eq:f} is odd, we have that 
\begin{align*}
 M(-x,\mu) = \int_0^{2\pi} f(-x-\mu\cos t)\,dt = -\int_0^{2\pi} f(x+\mu \cos t)\,dt= \\ 
 -\int_0^{2\pi} f(x-\mu\cos(t-\pi))\,dt = -\int_{-\pi}^{\pi} f(x-\mu\cos t)\,dt   = - M(x,\mu).
\end{align*}
Hence, $ M(0,\mu) =0$ for all $\mu\in\mathbb{R}$. If $|\mu|\leqslant 1$, then  the function $v(t)=-\mu\cos t$ lives in the zone $|x|\leqslant 1$, so $ A_{in}(0,\mu)=[0,2\pi]$ and, from \eqref{ecu:DerMtildex}, $ M_x(0,\mu)=2\pi b \ne 0$. 
\item Function $ M$ satisfies 
\begin{align*}
 M(x,-\mu) &= \int_0^{2\pi} f(x+\mu\cos t)\,dt = & \\ 
 &  \int_0^{2\pi} f(x-\mu \cos (t-\pi)\,dt= \int_{-\pi}^{\pi} f(x-\mu\cos t)\,dt   =  M(x,\mu). &  
\end{align*}
\item When the periodic function $v(t)=x-\mu\cos t $ is one--zonal, one gets
\[
 M(x,\mu)= \int_0^{2\pi}f(x)\,dt=2\pi f(x).
\]
Thus, for $x\ne 0$, $ M(x,\mu)=0$ if and only if  $|x|=1-b/a$, because $ab<0$. Now, it is direct to observe that functions $v^\pm(t)=\pm(1-b/a)-\mu\cos t$ are one--zonal if and only if $|\mu|\leqslant -b/a$.  Therefore, for $|\mu|\leqslant -b/a$, it has $ A_{in}(\pm(1-b/a),\mu)=\emptyset$ and so, from expression \eqref{ecu:DerMtildex},  $ M_x(\pm(1-b/a),\mu)=2\pi a \ne 0$ and the proof of item \eqref{item3proptildeM} is concluded. 
\item By using of item  \eqref{item1proptildeM}, $ M(0,\mu) =0$ for all $\mu\in\mathbb{R}$ and so $ M_\mu(0,\mu) =0$ for all $\mu\in\mathbb{R}$. By means of Remark \ref{rema:derMmu}, it follows that $ M_\mu(x,\mu)=0$ if $ A_{in}(x,\mu)= \emptyset$ or $ A_{in}(x,\mu)= [0,2\pi]$. Moreover, when $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$ and the periodic function $v(t)=x-\mu\cos t$ is two--zonal, from \eqref{eq:dertildeMmu2z} and \eqref{eq:dertildeMmu2zb}, it gets $ M_\mu(x,\mu)\ne 0$. Finally, if $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$, the periodic function $v$ is three--zonal and $ M_\mu(x,\mu)=0$, from \eqref{eq:dertildeMmu3z}, it deduces the relationship $\hat t_2=\pi-\hat t_1$, which implies, by means of \eqref{eq:t1t23z}, $x=0$ and the proof of item \eqref{itemdermuproptildeM} is completed. 
\item For $\mu=0$, we have 
\[
 M(x,0)= \int_0^{2\pi}f(x)\,dt=2\pi f(x)
\]
and so, if $|x|>1-b/a$, then it is direct to see that $\sgn\left( M(x,0)\right)=\sgn(x) \sgn(a)$. Now, we will prove the result for $x>1-b/a$ and $\mu<0$. When $x>1-b/a$ and $\mu<0$, the global maximum  of the function  $v(t)=x-\mu\cos t$ is $v(0)=x-\mu$ and its global minimum is $v(\pi)=x+\mu$. Hence, for $x>1-b/a$ fixed, when $\mu$ decreases from zero to $-\infty$, the set  $ A_{in}(x,\mu)$ defined in \eqref{ecu:Atilde} adopts the forms $ A_{in}(x,\mu)=\emptyset$ or  $ A_{in}(x,\mu)=[0,2\pi]$, $ A_{in}(x,\mu)=[t_1,2\pi-t_1]$, and $ A_{in}(x,\mu)=[\hat t_1,\hat t_2]\cup[2\pi-\hat t_2,2\pi-\hat t_1]$, (with $0<t_1<\pi$ and $0<\hat t_1<\hat t_2<\pi$). Therefore,
from Remark \ref{rema:derMmu} and item \eqref{itemdermuproptildeM}, it is deduced that $ M_\mu(x,\mu)=0$ if $ A_{in}(x,\mu)=\emptyset$ or  $ A_{in}(x,\mu)=[0,2\pi]$ and, 
\[
\sgn\left(  M_\mu(x,\mu)\right)=-\sgn(a-b)=-\sgn(a),
\]
when $\emptyset\ne A_{in}(x,\mu)\varsubsetneq [0,2\pi]$, because $ab<0$. Thus, $\sgn\left( M(x,\mu)\right)=\sgn(x) \sgn(a)\ne 0$ for $x>1-b/a$ and $\mu<0$.
By using items \eqref{item1proptildeM} and \eqref{item2proptildeM}, the result follows for $|x|>1-b/a$ and $\mu\in\mathbb{R}$. 
\item In view of items \eqref{item1proptildeM}, \eqref{item2proptildeM}, and \eqref{item5proptildeM}, we only need to prove the result for $x\in(0,1-b/a]$ and $\mu>0$. As previously established (see, for instance, Remark \ref{rema:derMmu}), the set $ A_{in}(x,\mu)$ given in \eqref{ecu:Atilde} is determined by the solutions $t\in(0,2\pi)$ of the equation $|x-\mu\cos t|=1$. Hence, by compacity, $m\left( A_{in}(x,\mu)\right)$ tends to zero as $\mu \to +\infty$ (uniformly in $x$) and so, from expression \eqref{ecu:DerMtildex}, there exist a value $\check \mu=\check \mu(a,b)>0$ such that $\sgn\left(  M_x(x,\mu)\right)=\sgn(2\pi a)\ne 0$ for $x\in(0,1-b/a]$ and $\mu>\check\mu$. Therefore, by using Theorem \ref{Th:-mu_large} and Proposition \ref{prop:existclMel} follows that $M(x,\mu)\ne0$ for $x\in(0,1-b/a]$ and $\mu>\check\mu$. Now, by means of item \eqref{item5proptildeM} and the continuity of function $ M$ one can conclude that $\sgn\left( M(x,\mu)\right)=\sgn(x)\sgn(a)\ne 0$ for $x\in(0,1-b/a]$ and $\mu>\check\mu$ and the proof is finished.
\end{enumerate}
\end{proof}
\begin{rema}
\label{rema:unizonaspertur}
It should be noted that item  \eqref{item1proptildeM} of Proposition \ref{prop:tildeM} provides a reformulation of Propositions \ref{prop:sym} and \ref{prop:2}   tailored to the perturbed differential equation \eqref{eq:ef} because the function $v(t)=-\mu\cos t$ is symmetric and the inequality $|\mu|\leqslant \sqrt{b^2+1}$ becomes the inequality $|\mu|\leqslant 1$ when $b$ is transformed into $\varepsilon b$ and $\varepsilon$ goes to zero.  Analogously,  item  \eqref{item3proptildeM} of Proposition \ref{prop:tildeM} is a reformulation of Proposition \ref{prop:1}. In this case, the inequality $|\mu|\leqslant -b \sqrt{a^2+1}/a$ becomes the inequality $|\mu|\leqslant -b/a$ when $a$ and $b$  are transformed into $\varepsilon a$ and $\varepsilon b$, respectively, and $\varepsilon$ tends to zero. It is worth recalling that, for $ab\ne 0$, piecewise differential equation \eqref{eq:main1} admits at most one periodic solution within each linearity region. Based on Proposition \ref{prop:existclMel} and items \eqref{item1proptildeM} and \eqref{item3proptildeM} of Proposition \ref{prop:tildeM}, sufficient conditions are established for the existence of one--zonal periodic solutions in the perturbed system \eqref{eq:ef} for $|\varepsilon|$ small enough. Finally, item \eqref{item6proptildeM} of Proposition \ref{prop:tildeM} is a reformulation of Theorem \ref{Th:-mu_large}.
\end{rema}


Continuing with the aim of characterizing the zero set of the function $ M$, we shall prove that this set is defined by a unique function $\mu$ that depends on $x$, for strictly positive values of both $x$ and $\mu$. Naturally, the symmetry properties described in items \eqref{item1proptildeM} and \eqref{item2proptildeM} of Proposition \ref{prop:tildeM} allow us to extend this dependence from the first quadrant of the $x-\mu$ plane to any other quadrant.  The following Theorem refers to a complete characterization of the zero set of $ M$ (see Figure~\ref{fig:zeroset} for a scheme of the zero set of $ M$). 

\begin{theo}\label{theo:zerosettildeM}
Suppose that the parameters $a$ and $b$ are fixed with $ab<0$. Then, there exists a unique function  $\varphi:[0,1-b/a]\longrightarrow (0,+\infty)$ such that the zero set of function $ M$ defined in \eqref{ecu:Melnikovfuntilde} can be written in the form:
\begin{equation}\label{eq:M1}
 M^{-1}(\{0\})=\left\{(0,\mu)\in\mathbb{R}^2:\mu\in\mathbb{R} \right\}\cup Z_1\cup S_1(Z_1)\cup S_2(Z_1)\cup S_2(S_1(Z_1)),
\end{equation}
where $S_1$ and $S_2$ are the symmetries $S_1(x,\mu):=(-x,\mu)$ and $S_2(x,\mu):=(x,-\mu)$ and 
\[
Z_1=\left\{(1-b/a,\mu)\in\mathbb{R}^2:0\leqslant \mu\leqslant  -b/a \right\}\cup \left\{(x,\mu)\in\mathbb{R}^2: \mu=\varphi(x), 0< x < 1-b/a \right\}.
\]

Moreover, function $\varphi$ satisfies the following properties:
\begin{enumerate}
\item \label{item1thM}
$\varphi$ is differentiable in $(0,1-b/a)$.
\item %\label{item2thM}
$\varphi$ possesses a unique critical point $x_1\in (1-b/a,0)$. Furthermore,  $\varphi'(x)>0$ for $x\in(0,x_1)$, $\varphi'(x)<0$ for $x\in(x_1,1-b/a)$ and  $x_1$ is given by 
\begin{equation}
\label{ecu:defx1}
x_1:=1-\mu_1\cos (c),
\end{equation}
where the values $\mu_1$ and $c$ are defined in \eqref{ecu:defmu1yc}.
%\begin{equation}
%\label{ecu:defmu1yc}
%\mu_1 := \frac{c}{\sin(c)}\, \qquad \mbox{and} \qquad c:=\frac{ \pi b}{b-a}\,.
%\end{equation}
\item  \label{item3thM} $\varphi$ is continuous in $[0,1-b/a]$, $\varphi(1-b/a)=-b/a$ and $\varphi(0)=\mu_2$, with $\mu_2$ defined in \eqref{ecu:defmu1yc}.
%\begin{equation}
%\label{defmu2}
%\mu_2:=\varphi(0)=\frac{1}{\cos(c/2)}\, ,
%\end{equation}
%with $c$ defined in \eqref{ecu:defmu1yc}.
\end{enumerate}
\end{theo}

Before presenting the proof of Theorem~\ref{theo:zerosettildeM}, we require a technical result concerning the solution of~\eqref{eq:ef} for $\epsilon=0$ determined by the initial condition $x_1$,  which lives exactly in the zones $x\geqslant 1$ and $-1<x<1$. 

\begin{lema}
\label{lema:v1}
Suppose that the parameters $a$ and $b$ are fixed with $ab<0$ and let us consider the values   $\mu_1$   and $c$ given in \eqref{ecu:defmu1yc} and the value  $x_1$ given in \eqref{ecu:defx1}. Then, the inequality $\mu_1\cos c>b/a$ holds and the periodic function $v_1(t)=x_1+\mu_1\cos t $ lives exactly in the zones $x\geqslant 1$ and $-1<x<1$.
\end{lema}

\begin{proof}
The inequality $\mu_1\cos c> b/a$ can be written into the form 
\[
c\left(\frac{\cos c}{\sin c}+\frac{1}{\pi-c}\right)>0.
\]
Since $ab<0$, the value $c$ defined in \eqref{ecu:defmu1yc} belongs to the open interval $(0,\pi)$ and so the previous inequality is transformed in 
\[
(\pi-c)\cos c+\sin c>0.
\]
Taking into account that the function $g(s)=(\pi-s)\cos s+\sin s$ is strictly decreasing, $g(0)=\pi$, and $g(\pi)=0$, the inequality $\mu_1\cos c> b/a$ holds.

Since $c\in(0,\pi)$ and $\mu_1>0$, the periodic function $v_1(t)=x_1+\mu_1\cos t =1-\mu_1\cos (c)+\mu_1\cos t$ satisfies $v_1(c)=1$ and $v'(c)=-\mu_1\sin(c)<0$. Thus, the function $v_1$ lives in the zones $x\geq 1$ and $x<1$. Now, we will prove that this function does not cross the straight line $x=-1$. To this end, we will see that its global minimum $v_1(\pi)=1-\mu_1(1+\cos c)$ is strictly greater than $-1$. That is, we will show that
\[
\frac{c (1+\cos c)}{\sin c}<2.
\]
The function $h(s)=s (1+\cos s)/\sin s$ is strictly decreasing, $\lim_{s\to 0^+}h(s)=2$, and $\lim_{s\to \pi^-}h(s)=0$, and so the result follows.
\end{proof}


\begin{proof}[Proof of Theorem \ref{theo:zerosettildeM}]
First, we will prove the existence of the function $\varphi$ defined in the open interval $(0,1-b/a)$. Further on, we will extend the definition of function $\varphi$ to the endpoints of this interval. 

Suppose that $x\in(0,1-b/a)$ is fixed. It is direct to see that $\sgn\left( M(x,0) \right)=\sgn(f(x))=\sgn(b)$. From item \eqref{item6proptildeM} of Proposition \ref{prop:tildeM}, it has 
$\sgn\left( M(x,\mu)\right)=\sgn(a)$ when $\mu$ is sufficiently large. Since $ab<0$, by continuity of function $ M $, there exists a value $\mu(x)>0$ such that $ M(x,\mu(x))=0$. By using Remark \ref{rema:derMmu} and item \eqref{itemdermuproptildeM} of Proposition \ref{prop:tildeM}, it easy to conclude that the value $\mu(x)$ is unique and so we get a unique function $\varphi: (0,1-b/a)\longrightarrow (0,+\infty)$ such that if $x\in(0,1-b/a)$, $\mu>0$ and $ M(x,\mu)=0$, then $\mu=\varphi(x)$. Moreover, from item \eqref{item5proptildeM} of Proposition \ref{prop:tildeM}, if $x,\mu>0$, then $M(x,\mu)=0$ if and only if $(x,\mu)\in Z_1$. Finally, by \eqref{item1proptildeM} and \eqref{item2proptildeM} of Proposition~\ref{prop:tildeM}, we obtain~\eqref{eq:M1}.

Now, we will prove items \eqref{item1thM}-\eqref{item3thM}. 

\begin{enumerate}
\item Notice that, by using item \eqref{item3proptildeM} of Proposition \ref{prop:tildeM}, the function $v(t)=x-\varphi(x)\cos t$, with $x\in(0,1-b/a)$, is not one--zonal, that is,  $\emptyset\ne A_{in}(x,\varphi(x))\varsubsetneq [0,2\pi]$, and so, from item \eqref{itemdermuproptildeM} of  Proposition~\ref{prop:tildeM}, $ M_\mu(x,\varphi(x))\ne0$. This implies, from the Implicit Function Theorem, that function $\varphi$ is differentiable in the open interval $(0,1-b/a)$ and so item \eqref{item1thM} is true. 
\item In the following we will prove that the function $\varphi$ has a unique critical point in the open interval $(0,1-b/a)$. For this purpose, we will consider the periodic function $w(t)=x+\varphi(x)\cos t$.
Note that function $w$ is not one--zonal, its global maximum is $w(0)=x+\varphi(x)$ and its global minimum is $w(\pi)=x-\varphi(x)$. 

If function $w$ is two--zonal, then there exists $t_1=t_1(x)\in(0,\pi)$ such that
\begin{equation}
\label{eq:t12z}
x+\varphi(x) \cos t_1=1 \qquad \mbox{with} \qquad x-\varphi(x)=-1+z,
\end{equation}
 where $z\in(0,2)$. Thus, the set $ A_{in}$ defined in \eqref{ecu:Atilde} is  $ A_{in}(x,-\varphi(x))=[t_1,2\pi-t_1]$ and the sets $A^\pm$ given in \eqref{eq: A+-} are $A^+(x,-\varphi(x))=[0,\hat t_1]\cup[2\pi-\hat t_1,2\pi]$ and $A^-(x,-\varphi(x))=\emptyset$. Therefore, by using expressions \eqref{ecu:Mtildeversion} and \eqref{eq:dertildeMmu3z}, it is deduced that 
\begin{equation}
\label{2ecu:2z}
0= M(x,-\varphi (x))= x  M_x(x,-\varphi (x))+2 \varphi(x)(a-b)  \sin t_1 -2(a-b) t_1.
\end{equation}

If function $\varphi$ possesses a critical point $x_1\in(0,1-b/a)$, with $w(t)=x_1+\varphi(x_1)\cos t$ two--zonal, then $ M_x(x_1,-\varphi (x_1))=0$ and the relationship \eqref{2ecu:2z} is 
\begin{equation}
\label{ecu:ecut1yfi}
\varphi(x_1)\sin t_1 =t_1.
\end{equation}

Taking into account that $ A_{in}(x_1,-\varphi(x))=[t_1,2\pi-t_1]$, by means of expression  \eqref{ecu:DerMtildex}, $ M_x(x_1,-\varphi (x_1))=0$ if and only if $t_1=c$, with $c$ given in \eqref{ecu:defmu1yc}. Thus, from expression \eqref{ecu:ecut1yfi}, $\varphi(x_1)=\mu_1$, where $\mu_1$ is defined in \eqref{ecu:defmu1yc} and, from the first expression of \eqref{eq:t12z} for $x=x_1$,  it follows $x_1=1-\varphi(x_1)\cos t_1=1-\mu_1\cos c$. Notice that, from Lemma \ref{lema:v1}, $x_1\in(0,1-b/a)$ and the function $v_1=x_1+\mu_1\cos(t)$ is two--zonal. 

When function $w$ is three--zonal, there exist $\hat t_1=\hat t_1(x),\hat t_2=t_2(x)$ (with $0<\hat t_1<\hat t_2<\pi$), such that $w(\hat t_1)=1$ and $w(\hat t_2)=-1$, that is, 
\begin{equation}
\label{eq:t1t23zb}
x+\varphi(x) \cos \hat t_1=1 \qquad \mbox{and} \qquad x+\varphi(x) \cos \hat t_2=-1.
\end{equation}
Hence, the set $ A_{in}$ defined in \eqref{ecu:Atilde} is  $ A_{in}(x,-\varphi(x))=[\hat t_1,\hat t_2]\cup [2\pi-\hat t_2,2\pi-\hat t_1]$ and the sets $A^\pm$ given in \eqref{eq: A+-} are $A^+(x,-  \varphi(x))=[0,\hat t_1]\cup[2\pi-\hat t_1,2\pi]$ and $A^-(x,-\varphi(x))=[\hat t_1,\hat t_2]$. Therefore, by using expressions \eqref{ecu:Mtildeversion} and \eqref{eq:dertildeMmu3z}, it is deduced that 
\begin{equation}
\label{3ecu:z}
0= M(x,-\varphi (x))= x  M_x(x,-\varphi (x))-2 \varphi(x)(a-b)\left( \sin \hat t_2- \sin \hat t_1 \right)-2(a-b)(\hat t_1+\hat t_2-\pi).
\end{equation}


If function $\varphi$ possesses a critical point $x_1\in(0,1-b/a)$, with $w(t)=x_1+\varphi(x_1)\cos t$ three--zonal, then $ M_x(x_1,-\varphi (x_1))=0$ and the relationship \eqref{3ecu:z} is 
\begin{equation}
\label{ecu:ecut1yt2}
-\varphi(x_1)\left( \sin \hat t_2- \sin \hat t_1 \right)=(\hat t_1+\hat t_2-\pi)
\end{equation}

By means of the expressions of \eqref{eq:t1t23zb}, it follows
\begin{equation}
\label{ecu:ecut1yt2b}
\varphi(x_1)\left( \cos \hat t_2- \cos \hat t_1 \right)=-2.
\end{equation}

From expressions \eqref{ecu:ecut1yt2} and \eqref{ecu:ecut1yt2b}, one has 
\[
-4\varphi(x_1)\sin\left(\frac{\hat t_2-\hat t_1}{2} \right)\left[ \cos\left(\frac{\hat t_2+\hat t_1}{2} \right)+\left(\frac{\hat t_2+\hat t_1}{2}-\frac{\pi}{2} \right) \sin\left(\frac{\hat t_2+\hat t_1}{2} \right)\right]=0
\]
Since $\varphi(x_1)>0$, $0<\hat t_1<\hat t_2<\pi$ and the unique solution $s\in(0,\pi)$ of equation $\cos s+(s-\pi/2)\sin s=0$ is $s=\pi$, it follows that $\hat t_1+\hat t_2=\pi$ and from expressions of  \eqref{eq:t1t23zb} for $x=x_1$, it deduces $x_1=0$. Because this is impossible, then the function $\varphi$ has no critical points corresponding to three-zonal functions $w$.

This concludes that  $x_1 = 1 - \mu_1 \cos(c)$ is effectively the unique critical point of the function $\varphi$. The sign of the derivative $\varphi$ is a  direct consequence of the continuity and the signs of $ M_x$ and $ M_\mu$ established in Remark \ref{rema:derMmu} and Proposition \ref{prop:tildeM}

\item From  the monotony of $\varphi$ in the intervals $(0,x_1)$ and $(x_1,1-b/a)$, it is direct to see that the limits 
\[
\lim_{x\to 1-\frac{b}{a}^-}\varphi(x) \qquad \mbox{and} \qquad \lim_{x\to 0^+}\varphi(x)
\]
exist. Moreover, by means of Remark \ref{rema:unizonaspertur}, one has $\lim_{x\to1-\frac{b}{a}^-}\varphi(x)=-b/a$ and $L=\lim_{x\to 0^+}\varphi(x)>-b/a$. Therefore, by defining 
$\varphi(1-b/a)=-b/a$ and $\varphi(0)=L$,  it follows that $\varphi$ is continuous in $[0,1-b/a]$. In addition, since the line $\left\{(0,\mu)\in\mathbb{R}^2:\mu\in\mathbb{R} \right\}$ is contained in the zero set of function $ M$,  one has that $ M_x(0,-\varphi(0))=0$ and $w(t)=\varphi(0)\cos t $ is three--zonal. By following the reasoning in item (2), it follows that $\hat t_1+\hat t_2=\pi$, from expression \eqref{ecu:DerMtildex}, it has  $\hat t_1=c/2$, and, from \eqref{eq:t1t23zb}, one deduces $\varphi(0)=\mu_2$, with $\mu_2$ given in \eqref{ecu:defmu1yc}. 
\end{enumerate}
\end{proof}

