\section{Examples} \label{Ex}
\setcounter{equation}{0}
Let us consider several examples corresponding to the case $n=1$, where the asymptotical behaviour of $v(x,t)$
greatly varies.
\begin{Ee}\label{Ee1} Assume that $n=1$,
\begin{align}\label{2.27}&
a=\I r, \,\, c=0, \,\, d=r^2/2,  \,\,  A=\I \la, \,\, h_1=g, \,\, h_2=1 \quad (r,\, \la,\, \in \BR), \\
\label{2.28} &
r\not=0,   \quad \la > |r|, \quad Q=\I \mu, \quad  \mu=\sqrt{\la^2-r^2},
\end{align}
where any of the two branches  of the square root in \eqref{2.28} may be fixed.
\end{Ee}
It follows from \eqref{2.17}--\eqref{2.20} that
\begin{align}\label{2.29}&
\Lam_1(x,t)=\E^{-\I d t}\big(g \exp\{(\I \la t-x)\mu\}+\exp\{(x-\I\la t)\mu\}\big),\\
\label{2.30} &
\Lam_2(x,t)=(1/\I r)\E^{\I d t}\big((\la +\mu)g \exp\{(\I \la t-x)\mu\}+(\la - \mu)\exp\{(x-\I\la t)\mu\}\big).
\end{align}
In view of \eqref{2.9}, we obtain
\begin{align}& \label{2.31}
S(x,t)=\frac{1}{2\la}\big(| \Lam_1(x,t)|^2+| \Lam_2(x,t)|^2\big)>0.
\end{align}
Finally, formulas \eqref{2.10} and \eqref{2.29}--\eqref{2.31} yield
\begin{align}& \label{2.32}
v(x,t)=\E^{2\I d t}\left(a+\frac{4\la\om_1(x,t)}{\I r \om_2(x,t)}\right),
\end{align}
where $d=r^2/2$ and
\begin{align}\nn 
\om_1(x,t)=&(\la+\mu)|g|^2\E^{-2x\mu}+(\la-\mu)\E^{2x\mu}+(\la-\mu)\ov{g}\E^{-2\I \la t\mu}+(\la+\mu){g}\E^{2\I \la t\mu},\\
\nn 
\om_2(x,t)=&\big((1+((\la+\mu)/r)^2\big)|g|^2\E^{-2x\mu}+\big(1+((\la-\mu)/r)^2\big)\E^{2x\mu}\\
\label{2.33} &
+2\ov{g}\E^{-2\I \la t\mu}+2{g}\E^{2\I \la t\mu}.
\end{align}
The family of the solutions $v(x,t)$ given by \eqref{2.32} is determined by the parameters $a$ (or $r$) and $\la$.
In order to derive \eqref{2.33}, we used  the equality $\la^2-\mu^2=r^2$, which also yields
\begin{align}& \label{2.33+}
(\la-\mu)^2+r^2=2\la(\la-\mu), \quad (\la+\mu)^2+r^2=2\la(\la+\mu).
\end{align}
Let us  set $\psi(x,t)$ and fix the branch of $\mu$ via the formulas:
\begin{align}& \label{2.34}
\psi(x,t)=e^{-2\I dt}v(x,t), \quad \mu>0.
\end{align}
Then, the equality $a=\I r$ and  relations \eqref{2.32}--\eqref{2.34} yield the following corollary.
\begin{Cy}\label{CyEx1} Let \eqref{2.34} hold. Then, for the NLS solutions $v(x,t)$  in Example~\ref{Ee1} we have
\begin{align}\label{2.35}&
\lim_{x\to \infty}\psi(x,t)=\lim_{x\to -\infty}\psi(x,t)=-\I r.
\end{align}
For the subcase $g=0$ $($in \eqref{2.27}$)$, we obtain $\psi(x,t)\equiv -\I r$.
\end{Cy}
We note that the functions $\psi(x,t)$ above are periodic with respect to $t$.
\begin{Rk} \label{RkPseudo} The pseudo-rational solutions $($i.e., the solutions expressed via  the seed term $a\E^{2\I(cx +dt)}$ and rational terms$)$ 
may appear in the case of the polynomial expressions $\E^{\pm \I \clr(x,t)}$, which, according
to \eqref{2.19}, happens if the matrix $Q$ is nilpotent. However, in many cases one gets $\det S(x,t)\equiv 0$ or the evident case $v(x,t) \equiv -v_0(x,t)$.
For instance, in the case of $n=3$, a $3\times 3$ matrix $Q=\{ \delta_{i+1,k}\}_{i,k=1}^3$ and $A=(c+\I |a|)I_3+\frac{1}{2\I |a|}Q^2$, we have $\det S(x,t)\equiv 0$
if
\begin{align}& \label{3.1}
h_1=\begin{bmatrix} 1 \\ 0 \\ 1\end{bmatrix}, \quad h_2= \begin{bmatrix} 0 \\ 1 \\ -1\end{bmatrix},
\end{align}
and we have $\det S(x,t)\equiv \frac{1}{64 |a|^9}$, $v(x,t) \equiv -v_0(x,t)$ if
\begin{align}& \label{3.2}
h_1=\begin{bmatrix} 0 \\ 0 \\ 1\end{bmatrix}, \quad h_2= \begin{bmatrix} 0 \\ g \\ 0\end{bmatrix} \quad (g\in \BC).
\end{align}
The case of pseudo-rational solutions will be treated in greater detail in the future work.
\end{Rk}
Example \eqref{2.27}, \eqref{2.28} for the special  case $t=0$ and $g\in \BR$ was considered in \cite[Example 4.3]{ALS1},
although we omitted there the fact that the limits of $v(x)$ at $+\infty$ and $-\infty$ coincide.
 The next two examples
were not studied earlier even for $t=0$. 
\begin{Ee}\label{Ee2} 
Let us fix $r$, which does not essentially effect the behaviour of the corresponding solution, and set
\begin{align}\label{3.3}&
a=\I, \,\, c=0, \,\, d=1/2,  \,\,  A=\I \la \,\, (0<\la<1), \,\, h_1=g, \,\, h_2=1, 
\\ & \label{3.4}
Q=\mu=\sqrt{1-\la^2}. 
\end{align}
where any of the two branches  of the square root in \eqref{3.4} may be fixed.
\end{Ee}
It follows from \eqref{1.2} and \eqref{3.3} that $v_0(x,t)=\I \E^{\I t}$.
Similar to the Example~\ref{Ee1}, the equality \eqref{2.31} holds. According to \eqref{2.20}, we have
\begin{align}\label{3.5}
h_3=-g(\I \la+\mu), \quad h_4=-(\I \la-\mu).
\end{align}
By virtue of \eqref{2.17}, we obtain
\begin{align}\label{3.6}
\Lam_1(x,t)=\E^{-\I t/2}\big(g\E^{\I \mu (x-\I \la t)}+\E^{-\I \mu (x-\I \la t)}\big).
\end{align}
Formulas \eqref{2.18} and \eqref{3.5} yield
\begin{align}\label{3.7}
\Lam_2(x,t)=-\E^{\I t/2}\big(g(\I \la +\mu)\E^{\I \mu (x-\I \la t)}+(\I \la-\mu)\E^{-\I \mu (x-\I \la t)}\big).
\end{align}
Formulas \eqref{3.3} and \eqref{3.4} imply that
\begin{align}&\nn
(\I\la +\mu)(\I \la -\mu)=-(\la^2+\mu^2)=-1,
 \\ & \nn
 1-(\I \la +\mu)^2=2\la (\la -\I \mu),\,\, 1-(\I \la -\mu)^2=2\la (\la +\I \mu).
\end{align}
Hence, using \eqref{2.31}, \eqref{3.6} and \eqref{3.7} we derive
\begin{align}\label{3.8}
S(x,t)=\big(|g|^2\E^{2\mu \la t}+\E^{-2\mu \la t}+g\la (\la -\I \mu)\E^{2\I \mu x}+\ov{g}\la (\la +\I \mu)\E^{-2\I \mu x}\big)\big/ \la .
\end{align}
Using again \eqref{3.6} and \eqref{3.7} and setting $\om(x,t)=\E^{-\I t}\Lam_1(x,t)^*\Lam_2(x,t)$, we also derive
\begin{align}\nn\om(x,t)=-\big(&|g|^2(\I \la +\mu)\E^{2\mu \la t}+(\I \la -\mu)\E^{-2\mu \la t}+g(\I\la + \mu)\E^{2\I \mu x}
\\ \label{3.9} &
+\ov{g} (\I\la - \mu)\E^{-2\I \mu x}\big).
\end{align}
Finally, formula \eqref{2.10} takes the form
\begin{align}\label{3.10}&
v(x,t)=\E^{\I t}\big(\I+2\om(x,t)\big/ S(x,t)\big).
\end{align}
\begin{Rk}\label{RkNL}
The considered case $0<\la <1$ differs essentially from the case $\la >r=1$ $($see Example \ref{Ee1}$)$.
In view of \eqref{3.8}--\eqref{3.10}, the function $\psi(x,t)=\E^{-\I t}v(x,t)$ $($as well as the function $v(x,t))$ is periodic with respect to $x$ and therefore
does not have any limits when $x$ tends to $+\infty$ or $-\infty$. $($Even $|\psi(x,t)|$ does not have any limits.$)$ The periodic in $x$ solutions
of NLS given by  \eqref{3.10} belong to the class of modulation solutions \cite{Akh, SaA2, Tr}.
\end{Rk}
\begin{Rk}\label{RkB} In the case $a=A=\I$ $(r=\la=1)$, which is intermediate between Examples \ref{Ee1} and \ref{Ee2}, we have
$($similar to some cases in Remark~\ref{RkPseudo}$)$ $v(x,t)=-v_0(x,t)=-\I \E^{\I t}$.
\end{Rk}
%%%%%%%%%%%%%%%%%
\begin{Ee}\label{Ee3} 
Let us   consider the case $c\not=0$ and set:
\begin{equation}\label{3.11}
a=\I, \,\,  d=1/2-c^2,  \,\,  A=2 \I,  \,\, h_1=g, \,\, h_2=1, \,\, Q=\mu=\sqrt{c^2-4\I c-3},
\end{equation}
where $\mu \in \BC$ and any of the two branches  of the square root in \eqref{3.11} may be fixed.
Clearly, conditions \eqref{3.11}  satisfy \eqref{2.11} and the second equality in \eqref{1.2}.
\end{Ee}
It follows from \eqref{3.11} and \eqref{1.2}, \eqref{2.19}, \eqref{2.20} that 
\begin{align}\nn &
v_0(x,t)=\I \E^{2\I(cx+dt) }=\I \exp\{\I(2cx-2c^2t+t)\}, \quad \I\clr(x,t)=\I \mu\big(x-(2\I+c)t\big),
\\ \label{3.12} &
h_3=-g(2\I-c+\mu), \quad h_4=-(2\I-c-\mu).
\end{align}
Hence, relations \eqref{2.17} and \eqref{2.18} yield
\begin{align}\nn
\Lam_1(x,t)^*\Lam_2(x,t)=&-\exp\{\I(2cx-2c^2t+t)\}
\\ & \nn
\times\big(|g|^2(2\I-c+\mu)\exp\{\I(\mu-\ov{\mu})(x-ct)+2(\mu+\ov{\mu})t\}
\\ & \nn
+(2\I-c-\mu)\exp\{-\I(\mu-\ov{\mu})(x-ct)-2(\mu+\ov{\mu})t\}
\\ & \nn
+g(2\I-c+\mu)\exp\{\I(\mu+\ov{\mu})(x-ct)+2(\mu-\ov{\mu})t\}
\\ & \label{3.13}
+\ov{g}(2\I-c-\mu)\exp\{-\I(\mu+\ov{\mu})(x-ct)-2(\mu-\ov{\mu})t\}
\big).
\end{align}
Relations \eqref{2.9}, \eqref{2.17} and \eqref{2.18} imply that
\begin{align}\nn
S(x,t)=&\frac{1}{4}\big(|\Lam_1(x,t)|^2+|\Lam_2(x,t)|^2\big)
\\ \nn = &
\frac{1}{4}\big((|g|^2+|h_3|^2))\exp\{\I(\mu-\ov{\mu})(x-ct)+2(\mu+\ov{\mu})t\}
\\ \nn  &
+(1+|h_4|^2)\exp\{-\I(\mu-\ov{\mu})(x-ct)-2(\mu+\ov{\mu})t\}
\\ \nn  &
+(g+h_3\ov{h_4})\exp\{\I(\mu+\ov{\mu})(x-ct)+2(\mu-\ov{\mu})t\}
\\  \label{3.14} &
+(\ov{g}+h_4\ov{h_3})\exp\{-\I(\mu+\ov{\mu})(x-ct)-2(\mu-\ov{\mu})t\}\big).
\end{align}
Choosing the branch of the square root, where $\Im(\mu)<0$, we see that the first
exponents in the sums of such in \eqref{3.13} and \eqref{3.14} are the leading terms
in the case $x\to \infty$ and the second exponents are the leading terms
in the case $x\to -\infty$. Therefore, using \eqref{2.10} and setting
\begin{align}\label{3.15}&
\psi(x,t)=\exp\{-\I(2cx-2c^2t+t)\}v(x,t),
\end{align}
we see that
\begin{align}\label{3.16}&
\lim_{x\to \infty}\psi(x,t)=\I-\frac{8|g|^2(2\I-c+\mu)}{|g|^2+|h_3|^2}=\I-\frac{8(2\I-c+\mu)}{1+|2\I-c+\mu |^2},
\end{align}
and
\begin{align}\label{3.17}&
\lim_{x\to -\infty}\psi(x,t)=\I-\frac{8(2\I-c-\mu)}{1+|h_4|^2}=\I-\frac{8(2\I-c-\mu)}{1+|2\I-c-\mu |^2}.
\end{align}
\begin{Cy}\label{CyStep} For $\psi(x,t)$ of the form \eqref{3.15}, where the NLS solution $v(x,t)$ is determined
by the formulas \eqref{2.10} and \eqref{3.11}--\eqref{3.14}, the limits \eqref{3.16} and \eqref{3.17} exist
for $x$ tending to $+\infty$ and $-\infty$, respectively. These limits coincide if and only if $c=0$. When
$c\not=0$, we speak about step-like solutions.
\end{Cy}

In order to show that the right-hand sides of \eqref{3.16} and \eqref{3.17} coincide only for $c=0$, we note
that the equality there is equivalent to the equality
$$(2\I-c+\mu)\big(1-(2\I-c-\mu)(2\I+c+\ov{\mu})\big)=(2\I-c-\mu)\big(1-(2\I-c+\mu)(2\I+c-\ov{\mu}),$$
which, in view of \eqref{3.11}, is equivalent to the equality $2(\mu +\ov{\mu})=0$. Using again the
expression for $\mu$ in \eqref{3.11}, we see that the last equality is equivalent to $c=0$.
\begin{Rk} \label{RkStep} Step-like solutions are of interest and are studied in the literature although such solutions are absent in the
mentioned above works on rogue waves.
\end{Rk}

In the Examples \ref{Ee1}, \ref{Ee2} and \ref{Ee3} above, we considered the case  $
n= \nobreak  1$. In a partly similar to Example \ref{Ee1}
case, where $n=2$, $a=1, \,\, c=0, \,\,  d=1/2$,   $ A=2 \I I_2,  \,\, h_1=\begin{bmatrix}g \\ 0 \end{bmatrix}, \,\, h_2=\begin{bmatrix}1 \\ -1 \end{bmatrix}$,
$Q=\I \mu I_2, \,\, \mu =\sqrt{3}>0$, one obtains $v(x,t)=v_0(x,t)$.
Interesting GBDT transformations $v(x)$ of the constant seed, where $n=2$ and $A$ is a $2\times 2$ Jordan cell, are treated in 
\cite[Example~4.4]{ALS1}.  The 
asymptotical behaviour of $v(x)$ is described in that case in \cite[Proposition~4.5]{ALS1}. However, that behaviour greatly differs from the
cases of asymptotics discussed in this work.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

A class of the $N$-modulation solutions of NLS generated by the initial solution $v_0=\E^{\I t}$ (i.e., $c=0$)
was constructed in \cite{SaA2}. Let us construct a much wider class of such solutions for $c\not=0$.
\begin{Ee}\label{Ee2+}  Assume that $v_0$  is given by \eqref{1.2}, $n\in \BN$ and 
\begin{align}\label{3.19-}&
 A=\diag\{\cla_1,\cla_2, \ldots, \cla_n\}, \quad \cla_k=c+\I b_k \quad (b_k \in \BR, \,\,1\leq k\leq n).
\end{align} 
According to \eqref{2.11},
$Q=\diag\{\clq_1,\clq_2,\ldots,\clq_n\}$, where $\clq_k^2=|a|^2-b_k^2$  $\break (1\leq k\leq n)$. We will assume that $\clq_k$
are commensurable with $c$:
\begin{align}\label{3.18}&
b_k^2=|a|^2-\frac{r_k^2}{\ell_k^2}c^2>0 \quad (r_k, \ell_k \in \BN), \quad \clq_k=\pm \frac{r_k}{\ell_k}c.
\end{align}
Moreover, we assume that  \eqref{2.27--} holds, where $\cll_k$ are the rows of $\Lam$.
\end{Ee}
It follows that 
\begin{align}\label{3.19}&
\I\clr(x,t)=\I \, \diag\{\clr_1(x,t),\ldots \clr_n(x,t)\}, \quad \clr_k(x,t)=\clq_kx-\clq_k(2c+\I b_k)t.
\end{align}
In view of \eqref{2.17}, \eqref{2.18} and \eqref{3.19}, $v_0(x,t)$, $\Lam_1(x,t)$ and $\Lam_2(x,t)$ are periodic with respect to $x$
with the period 
\begin{align}\label{3.20}&
T=(2\pi /c)\prod_{k=1}^n\ell_k.
\end{align}
According to  Corollary \ref{CyDiag}, $S(x,t)$ has the same period and is invertible. Thus, $S(x,t)^{-1}$ has the same
period $T$ given by \eqref{3.20}. Finally, it follows from \eqref{2.10} that the corresponding GBDT- transformed solutions
$v(x,t)$ are $N$-modulation solutions with the period $T$.
