\section{Baker-Akhiezer functions and evolution of the Weyl-Titchmarsh functions} \label{Evol}
\setcounter{equation}{0}
{\bf 1.} According to \eqref{2.10--}, we need to know $w_0(x,t,z)$ satisfying \eqref{2.10!} in order to construct Baker-Akhiezer functions $w(x,t,z)$ 
satisfying \eqref{2.10-}, that is,  Baker-Akhiezer functions corresponding to the 
GBDT-generated solutions of NLS. Recall that $G_0$ and $F_0$ in \eqref{2.10!} are given by \eqref{2.2} and \eqref{2.3}, where one sets
$v(x,t)=v_0(x,t)$ and $v_0$ is given by \eqref{1.2}.
\begin{Pn}\label{Pnw0}  The matrix function $w_0$ of the form
\begin{align}\label{4.1}&
w_0(x,t,z):=\E^{\I (c x+dt) j}Z(z)\exp\big\{\I  \zeta(z)\big(x-(z+c)t\big) j\big\}, \quad {\mathrm{where}}
\\ & \label{4.2}
\zeta(z)=\sqrt{(z-c)^2+|a|^2}, \quad Z(z)=\begin{bmatrix}\I a & \I a \\
z-c-\zeta(z) & z-c+\zeta(z)
\end{bmatrix},
\end{align}
 satisfies systems \eqref{2.10!} $($i.e., $w_0$ is the initial Baker-Akhiezer function$)$.
\end{Pn}
{\it Proof}. In view of \eqref{4.1}, the equation $\frac{\p}{\p x}w_0(x,t,z)=G_0(x,t,z)w_0(x,t,z)$ is equivalent to the equality
\begin{align}\label{4.3}&
\I \E^{\I (c x+dt) j}(cjZ(z)+\zeta(z)Z(z)j)=(\I z j+ j V_0(x,t))\E^{\I (c x+dt) j}Z(z),
\end{align}
which is, in turn, equivalent to
\begin{align}\label{4.3+}&
\I\big(z j Z(z)-cj Z(z)-\zeta(z)Z(z)j\big)+\E^{-\I (c x+dt) j} j V_0(x,t)\E^{\I (c x+dt) j}Z(z)=0.
\end{align}
Taking into account \eqref{4.2}, we see that
\begin{align}\label{4.4}&
(z-c-\zeta(z))(z-c+\zeta(z))=-|a|^2.
\end{align}
Using \eqref{4.2} and \eqref{4.4}, we obtain
\begin{align}\label{4.5}&
z j Z(z)-cj Z(z)-\zeta(z)Z(z)j=\begin{bmatrix}\I a(z-c-\zeta(z)) & \I a (z-c+\zeta(z))\\
|a|^2 & |a|^2
\end{bmatrix}.
\end{align}
It follows from \eqref{1.2} that 
\begin{align}\label{4.6}
\E^{-\I (c x+dt) j} j V_0(x,t)\E^{\I (c x+dt) j}Z(z)&=\begin{bmatrix}0 & a \\-\ov{a} &0
\end{bmatrix}Z(z)
\\ & \nn
=-\I \begin{bmatrix}\I a(z-c-\zeta(z)) & \I a (z-c+\zeta(z))\\
|a|^2 & |a|^2
\end{bmatrix}.
\end{align}
Formula \eqref{4.3+} is immediate from \eqref{4.5} and \eqref{4.6}, and so the first equation in \eqref{2.10!}
is proved.

For $w_0$ given by \eqref{4.1}, let us prove the second equation in \eqref{2.10!}.  Formulas \eqref{2.3}, \eqref{2.12} and \eqref{1.2}
yield
\begin{align}\nn
F_0(x,t,z)&=\I \left(-z^2+\frac{|a|^2}{2}\right)j-(z+c )jV_0(x,t)
\\ \label{4.7}&
=-\big(\I(z^2-c^2-d)j+(z+c)jV_0(x,t)\big).
\end{align}
Hence, the second equation in \eqref{2.10!} is equivalent to the equality
\begin{align}\nn &
\big(\I(z^2-c^2-d)j+(z+c)jV_0(x,t)\big)\E^{\I (c x+dt) j}Z(z)
\\ \label{4.8}&
=-\I \E^{\I (c x+dt) j}(d jZ(z)-(z+c)\zeta(z)Z(z)j).
\end{align}
The equality \eqref{4.8} is equivalent to the equality
\begin{align}\label{4.9} &
\I(z-c)jZ(z)-\I \zeta(z)Z(z)j+\E^{-\I (c x+dt) j}jV_0(x,t)\E^{\I (c x+dt) j}=0.
\end{align}
The equality \eqref{4.9} easily follows from \eqref{4.5} and \eqref{4.6}. Hence,  the second equation in \eqref{2.10!}
is proved. $\Box$
\begin{Rk} Now, Baker-Akhiezer function corresponding to the triple $\break \{A, S(0,0), \Lam(0,0)\}$ is given by the relation \eqref{2.10--}
as well as by the formulas \eqref{2.9+}, \eqref{4.1}, where $\Lam(x,t)$ and $S(x,t)$ in \eqref{2.9+} are given by \eqref{2.17}, \eqref{2.18} and \eqref{2.7},
\eqref{2.8}, respectively.
\end{Rk}

{\bf 2.} In order to define Weyl functions of the skew-selfadjoint auxiliary Dirac systems \eqref{1.3} (see \cite{ALS1, SaSaR} and the references therein)
we need the notation $\BC_M:=\{z: \, z\in \BC, \,\, \Im(z)>M>0\}.$ Here,  we consider the case $p=1$ and define Weyl functions for this case although the generalization
for $p>1$ is evident. By $W(x,z)$, we denote the fundamental solution  of the Dirac system $W^{\prime}(x,z)=(\I z j+j V(x))W(x,z)$ normalised by the equality
$W(0,z)=I_2$. Recall that  $j=\begin{bmatrix}1 & 0 \\   0 & - 1\end{bmatrix}$ and $V(x)=\begin{bmatrix}0 & v(x) \\  \ov{v(x} & 0\end{bmatrix}$.
\begin{Dn} \label{DnW2}  A  function $\vp(z)$, which is  holomorphic in $\BC_M$
$($for some  $M>0)$ and satisfies the inequality
\begin{align}&      \label{4.10}
\int_0^{\infty}
\begin{bmatrix}
1 & \vp(z)^*
\end{bmatrix}
W(x,z)^*W(x,z)
\begin{bmatrix}
1 \\ \vp(z)
\end{bmatrix}dx< \infty , \quad z\in \BC_M,
\end{align}
is called a Weyl function of  the skew-selfadjoint Dirac system on $[0,\infty)$.
\end{Dn}
For the solutions of the general type inverse problems to recover $v(x)$ from the  Weyl function see \cite {SaSaR} and references therein.

Evolution $\vp(t,z)$ of the Weyl function for the case of GBDT-transformed $v(x,t)$ instead of $v(x)$ is easily expressed (in terms
of $\Lam(0,t)$ and $S(0,t)$ given by \eqref{2.6} and \eqref{2.8}) using  \cite[Theorem 5.7]{ALS1} on the Weyl function for the case of GBDT-transformed $v(x)$.
Recall that $\zeta(z)=\sqrt{(z-c)^2+|a|^2}$. Here, we choose the branch of the square root so that $\zeta(z)\in \BC_+$ for $z\in \BC_+$.
\begin{Tm}\label{TmEvol} Let $v(x,t)$ be generated by the triple $\{A,S(0,0), \Lam(0,0)\}$ and initial seed $v_0(x,t)$ of the form \eqref{1.2}.
Then, the Weyl function $\vp(t,z)$ of the corresponding skew-selfadjoint Dirac system on $[0,\infty)$ is given by the formula
\begin{align}\label{4.11} &
\vp(t,z)={\E^{-2\I dt}}\Big(D(z)+\big(D(z)C_1-C_2\big)(A^{\times}-z I_n)^{-1}B(z)\Big)\big/(\I a),
\end{align}
where $D(z)=z-c-\zeta(z)$,
\begin{align}\label{4.12} &
 C_1=\frac{1}{a}{\E^{-2\I dt}}\Lam_1(0,t)^*S(0,t)^{-1}, \quad C_2=\I  \Lam_2(0,t)^*S(0,t)^{-1},  
\\ \label{4.13} &
A^{\times}=A-B(z)C_1, \quad B(z)=\I a \E^{2\I dt}\Lam_1(0,t)+D(z)\Lam_2(0,t).
\end{align}
\end{Tm}
Note that the representation \eqref{4.11} of $\vp(t,z)$ is close to the {\it realisations} in \cite{GKS2} (it would be a realisation if $D$ and $B$ did not depend on $z$). 


